        self._bind_canvas_scroll(preview_canvas)
        self.preview_canvas = preview_canvas
        self._preview_items = []
        self._thumb_photos = []
        self._preview_active = False
        self._preview_cols = 5

        self.protocol("WM_DELETE_WINDOW", self._on_close)

        self.lift()
