        tk.Button(fn_load_row, text="📁 Load Folder", command=self._load_floating_folder,
                  bg="#f39c12", fg="#1b1b1b", activebackground="#f5b041",
                  relief=tk.FLAT, cursor="hand2", font=("Helvetica", 8, "bold")).pack(side=tk.LEFT, padx=(0, 4))
        tk.Button(fn_load_row, text="✕", command=self._clear_floating_images, width=2,
                  bg="#e74c3c", fg="#ffffff", activebackground="#c0392b",
                  relief=tk.FLAT, cursor="hand2", font=("Helvetica", 8, "bold")).pack(side=tk.LEFT)

        fn_search_row = tk.Frame(size_frame, bg=FNODE_BG)
        fn_search_row.pack(fill=tk.X, pady=(2, 4))
        tk.Button(fn_search_row, text="\U0001F50D  Search Images", command=self._search_floating_images,
                  bg="#e67e22", fg="#ffffff", activebackground="#f39c12",
                  relief=tk.RIDGE, bd=3, cursor="hand2",
                  font=("Helvetica", 10, "bold")).pack(fill=tk.X, ipady=4)

        self.floating_node_images: List[str] = []
        self._floating_search_temp_dirs: List[str] = []
        self.floating_images_status_var = tk.StringVar(value="No images loaded")
        tk.Label(size_frame, textvariable=self.floating_images_status_var,
                 bg=FNODE_BG, fg=FNODE_MUTED, font=("Helvetica", 8)).pack(fill=tk.X, pady=(0, 6))

        def _var_spin_row(parent, label_text, var, from_val=0, to_val=3000, width=6,
                           row_bg=FNODE_BG, row_fg=FNODE_FG):
            row = tk.Frame(parent, bg=row_bg)
            row.pack(fill=tk.X, pady=(1, 1))
            tk.Label(row, text=label_text, bg=row_bg, fg=row_fg,
                     font=("Helvetica", 8), width=16, anchor="w").pack(side=tk.LEFT)
            spin = tk.Spinbox(row, from_=from_val, to=to_val, textvariable=var, width=width,
                              bg=self.colors["entry_bg"], fg="#000000",
                              font=("Consolas", 9), relief=tk.SOLID, bd=1)
            spin.pack(side=tk.LEFT)
            bind_mousewheel_to_spinbox(spin)
            return spin

        self.float_dot_spacing_var = tk.IntVar(value=30)

        self.float_origin_x_var = tk.IntVar(value=0)
        self.float_origin_y_var = tk.IntVar(value=0)

        self.float_img_width_var = tk.IntVar(value=300)
        self.float_img_height_var = tk.IntVar(value=200)
        _var_spin_row(size_frame, "Image Width", self.float_img_width_var, from_val=10, to_val=2000)
        _var_spin_row(size_frame, "Image Height", self.float_img_height_var, from_val=10, to_val=2000)

        self.float_random_size_var = tk.BooleanVar(value=False)
        tk.Checkbutton(size_frame, text="Custom / Random Size (ignore default W/H above)",
                       variable=self.float_random_size_var,
                       bg=FNODE_BG, fg=FNODE_FG,
                       activebackground=FNODE_BG, selectcolor=FNODE_SELECT,
                       font=("Helvetica", 8), wraplength=280, justify=tk.LEFT).pack(anchor="w", pady=(4, 2))

        self.float_size_assignment: List[tuple] = []
        tk.Button(size_frame, text="\U0001F3B2 Randomize Size", command=self._randomize_floating_sizes,
                  bg="#e84393", fg="#ffffff", activebackground="#ff85b8",
                  relief=tk.FLAT, cursor="hand2", font=("Helvetica", 9, "bold")).pack(fill=tk.X, pady=(2, 0))

        imf = tk.LabelFrame(right_content, text=" Image for mindmap(IFM) Section ",
                            bg=IFM_BG, fg=IFM_FG,
                            font=("Helvetica", 9, "bold"), padx=8, pady=8)
        imf.pack(fill=tk.X, pady=(0, 8))
        imf._no_theme = True

        # A real packed header row instead of .place(): the AMX section
        # frame right below is packed fill=X and starts at this same
        # frame's very top, so a .place()'d widget here ends up sitting
        # underneath it (hidden) once that frame is mapped. Packing the
        # switch into its own row -- with the row packed first -- keeps
        # it visible, top-right, above everything else in the section.
        ifm_header_row = tk.Frame(imf, bg=IFM_BG)
        ifm_header_row.pack(fill=tk.X, pady=(0, 6))

        self.ifm_enabled_var = tk.BooleanVar(value=False)
        self.ifm_switch_chk = tk.Checkbutton(ifm_header_row, text="Enable IFM",
                                              variable=self.ifm_enabled_var,
                                              bg=IFM_BG, fg=IFM_FG,
                                              activebackground=IFM_BG,
                                              selectcolor=IFM_SELECT,
                                              font=("Helvetica", 9, "bold"))
        self.ifm_switch_chk.pack(side=tk.RIGHT)

        # M3-139: dropdown right at the top of the IFM section -- lets
        # Automatic Search pull its node names from either the loaded AMX
        # .xmind file (the long-standing default, unchanged behavior) or
        # straight from the hierarchy text currently sitting in the main
        # editor (self.input_text), parsed the same way Export/Preview
        # parse it (HierarchyParser). This means a mind map doesn't have
        # to be exported/loaded as an .xmind file first just to search
        # for its node names -- typing/pasting the hierarchy text is
        # enough. See _ifm_gather_search_targets, which is the single
        # place that reads this dropdown and branches accordingly.
        ifm_source_row = tk.Frame(imf, bg=IFM_BG)
        ifm_source_row.pack(fill=tk.X, pady=(0, 6))
        tk.Label(ifm_source_row, text="Search node names from:",
                 bg=IFM_BG, fg=IFM_FG, font=("Helvetica", 9, "bold")).pack(side=tk.LEFT)
        self.ifm_node_source_var = tk.StringVar(value="AMX Section")
        _IFM_SOURCE_OPTIONS = ["AMX Section", "Text Area (Condensed Data)"]
        self.ifm_source_combo = tk.OptionMenu(ifm_source_row, self.ifm_node_source_var,
                                              *_IFM_SOURCE_OPTIONS)
        self._style_app_dropdown(self.ifm_source_combo, self.ifm_node_source_var, _IFM_SOURCE_OPTIONS)
        self.ifm_source_combo.pack(side=tk.LEFT, padx=(4, 0), fill=tk.X, expand=True)
        # M3-141: switching this dropdown immediately invalidates any
        # stored Automatic Search positional mapping -- belt-and-braces
        # on top of _ifm_pool_images_for_source's per-image tagging, so a
        # mapping from one source is never even considered for the
        # other, not even in some future edge case where the node counts
        # happen to coincidentally still line up. Mirrors exactly what a
        # fresh search or a reloaded/cleared IFM file already resets
        # (see _clear_structure_images / _load_ifm_xmind).
        self.ifm_node_source_var.trace_add("write", self._on_ifm_node_source_changed)

        # M3-144: which of the multi-sheet hierarchy editor's OWN sheets
        # (self.sheets -- see the "+"/tab strip above the editor)
        # Automatic Search reads node names from -- and Preview/Export
        # build into one .xmind -- when the dropdown above is set to
        # "Text Area (Condensed Data)". Used to be silently limited to
        # whichever ONE sheet happened to be active; this checklist (only
        # shown/populated while that source is selected -- see
        # _update_ifm_text_sheets_visibility) mirrors the AMX Section's
        # own "Sheets to search" checklist just below. Built empty here;
        # _rebuild_ifm_text_sheet_checklist fills it in on demand.
        self.ifm_text_sheets_frame = tk.LabelFrame(imf, text=" Text Area Sheets (\U0001F50D search/build) ",
                                                   bg=IFM_BG, fg=IFM_FG,
                                                   font=("Helvetica", 9, "bold"))
        self.ifm_text_sheet_vars: List[tk.BooleanVar] = []
        self.ifm_text_sheet_output_vars: List[tk.BooleanVar] = []
        self.ifm_text_sheet_search_checks: List[tk.Checkbutton] = []
        self._ifm_text_sheet_names_at_last_build: List[str] = []
        # M3-145: live state for a click-and-hold-then-move gesture on a
        # row in the checklist above -- see _on_ifm_text_sheet_row_press/
        # _motion/_release. None whenever no row is currently being
        # pressed/dragged. Separate from self._sheet_drag (the editor's
        # own horizontal tab strip) since this checklist's rows stack
        # vertically instead.
        self._ifm_text_sheet_drag: Optional[Dict[str, Any]] = None
        # Not packed here -- _update_ifm_text_sheets_visibility packs/
        # unpacks it (before ifm_amx_frame, so it always sits in the same
        # slot) depending on the dropdown's current value.

        # IFM's own AMX Section -- deliberately independent of the F-Node
        # AMX Section above (separate loaded-file state, no sheet
        # combobox/View PMM / XMM Structure GUI): this one just needs a target
        # .xmind file to paste the images below into its existing nodes.
        ifm_amx_frame = tk.LabelFrame(imf, text=" AMX Section ",
                                      bg=IFM_BG, fg=IFM_FG,
                                      font=("Helvetica", 9, "bold"))
        ifm_amx_frame.pack(fill=tk.X, pady=(0, 8))
        self._ifm_amx_frame_ref = ifm_amx_frame

        self.ifm_loaded_xmind_path: Optional[str] = None

        ifm_amx_load_row = tk.Frame(ifm_amx_frame, bg=IFM_BG)
        ifm_amx_load_row.pack(fill=tk.X, pady=(4, 2))
        tk.Button(ifm_amx_load_row, text="📂 Load .xmind File", command=self._load_ifm_xmind,
                  bg="#3498db", fg="#ffffff", activebackground="#5dade2",
                  relief=tk.FLAT, cursor="hand2", font=("Helvetica", 9, "bold")).pack(side=tk.LEFT, fill=tk.X, expand=True, padx=(0, 4))
        tk.Button(ifm_amx_load_row, text="✕ Clear", command=self._clear_ifm_xmind,
                  bg="#e74c3c", fg="#ffffff", activebackground="#c0392b",
                  relief=tk.FLAT, cursor="hand2", font=("Helvetica", 9, "bold")).pack(side=tk.LEFT)

        self.ifm_loaded_xmind_status_var = tk.StringVar(
            value="No file loaded -- load the .xmind app you want images pasted into.")
        tk.Label(ifm_amx_frame, textvariable=self.ifm_loaded_xmind_status_var,
                 bg=IFM_BG, fg=IFM_MUTED, font=("Helvetica", 8),
                 wraplength=280, justify=tk.LEFT).pack(fill=tk.X, pady=(0, 4))

        (self.ifm_level_counts_frame, self.ifm_level_count_labels,
         self.ifm_total_nodes_var, self.ifm_total_nodes_label) = \
            self._make_xmind_level_counts_widget(ifm_amx_frame, IFM_BG, IFM_MUTED)

        # M3-120: which sheet(s) of the loaded .xmind Automatic Search reads
        # node names from (and Preview/Export paste images into). Used to be
        # hard-coded to sheet 1 no matter how many sheets the file actually
        # had -- silently invisible to both the level counts above and
        # Automatic Search, and with no way to tell IFM "skip this sheet".
        # Rebuilt by _rebuild_ifm_sheet_checklist (called from
        # _load_ifm_xmind/_clear_ifm_xmind) every time the loaded file
        # changes; every sheet starts checked (included) by default.
        # M3-121: two independent checkboxes per sheet now -- "Include in
        # output" (whether the sheet appears in the previewed/exported
        # file at all, see _xmind_filter_sheets) and "Search for images"
        # (whether Automatic Search reads that sheet's node names / Preview
        # & Export paste images into it, unchanged from before). A sheet
        # excluded from output can never be searched -- see
        # _on_ifm_sheet_output_toggle -- since there'd be nothing left for
        # a search result to land in.
        tk.Label(ifm_amx_frame, text="Sheets (\U0001F4C4 include in file / \U0001F50D search for images):",
                 bg=IFM_BG, fg=IFM_FG,
                 font=("Helvetica", 8, "bold"), wraplength=280, justify=tk.LEFT).pack(anchor="w", pady=(2, 0))
        self.ifm_sheets_frame = tk.Frame(ifm_amx_frame, bg=IFM_BG)
        self.ifm_sheets_frame.pack(fill=tk.X, pady=(0, 4))
        self.ifm_loaded_xmind_sheets: List[str] = []
        self.ifm_sheet_output_vars: List[tk.BooleanVar] = []
        self.ifm_sheet_include_vars: List[tk.BooleanVar] = []
        self.ifm_sheet_search_checks: List[tk.Checkbutton] = []
        self._rebuild_ifm_sheet_checklist([])

        # M3-145: initializes the "Text Area Sheets" checklist above and
        # packs/hides it to match the dropdown's current ("AMX Section")
        # default -- hidden at startup, built the first time the dropdown
        # is switched to "Text Area (Condensed Data)" (see
        # _on_ifm_node_source_changed) or a sheet is added/closed/
        # reordered/renamed while that source is already selected (see
        # _on_sheets_changed).
        self._update_ifm_text_sheets_visibility()

        self.structure_images: List[str] = []
        self._structure_search_temp_dirs: List[str] = []
        self.structure_images_status_var = tk.StringVar(value="No images loaded")
        # M3-141: which "Search node names from" source (see
        # ifm_node_source_var / _IFM_SOURCE_OPTIONS) each Automatic-
        # Search-downloaded or Load & Resume-recovered path in
        # structure_images above was actually fetched for. Only entries
        # that came from one of those two flows are ever added here --
        # images added via "Load Images"/"Load Folder"/"Search Images"
        # are deliberately left untagged so they stay usable regardless
        # of which source option is selected, exactly as before this
        # change. See _ifm_pool_images_for_source, which is what
        # Preview/Export's cycling fallback now goes through instead of
        # the raw structure_images list, so a run's images can never
        # silently get pasted into a build made under a different
        # source after the dropdown is switched.
        self.ifm_auto_image_source: Dict[str, str] = {}

        # Automatic Search's own result mapping -- kept separate from the
        # plain structure_images pool above so a handful of failed/skipped
        # node lookups can never shift every later image onto the wrong
        # node (see inject_images_into_xmind_nodes' positional_image_paths
        # and _run_ifm_auto_search). None entry i means node i's search
        # never found a usable image even after retries; that node is left
        # unimaged at export time rather than borrowing a neighbor's image.
        # Invalidated (reset to None) whenever the IFM file is (re)loaded/
        # cleared or a fresh Automatic Search starts, since it's only
        # trustworthy against the exact node set it was searched against.
        self.ifm_auto_search_positional_images: Optional[List[Optional[str]]] = None
        self.ifm_auto_search_source_path: Optional[str] = None
        # M3-120: which sheet indices (see "Sheets to search" above) the
        # stored positional mapping above was actually searched against --
        # _ifm_get_positional_images_if_valid compares this to the
        # checklist's CURRENT selection, since a mapping searched against a
        # different set of sheets can't be trusted to still line up.
        self.ifm_auto_search_sheet_indices: Optional[List[int]] = None
        # Whether "Replace images already in the file" was checked when
        # the stored mapping above was searched -- toggling it since
        # changes which nodes count as targets (see _ifm_dfs_targets'
        # include_existing), so _ifm_get_positional_images_if_valid must
        # invalidate the mapping if this no longer matches the checkbox's
        # current state, the same way a changed sheet selection does.
        self.ifm_auto_search_replace_existing: Optional[bool] = None

        # M3-138: separate from ifm_auto_search_positional_images above --
        # that one only ever gets set by a run that actually happened in
        # THIS process. This one holds a mapping recovered from disk by
        # "Load & Resume" (see _load_and_resume_ifm_images), for when a
        # previous run's own in-memory progress was lost entirely (power
        # loss, crash, ...) and all that's left is the folder of already-
        # downloaded image files. Consumed (reset to None) the moment
        # _start_ifm_auto_search actually uses it to seed a new run, so a
        # later unrelated run can't accidentally pick it back up.
        # Invalidated the same places ifm_auto_search_positional_images
        # is -- see _load_ifm_xmind / _clear_ifm_xmind.
        self.ifm_recovered_positional: Optional[List[Optional[str]]] = None
        self.ifm_recovered_terms: Optional[List[str]] = None
        self.ifm_recovered_sheet_indices: Optional[List[int]] = None
        self.ifm_recovered_replace_existing: Optional[bool] = None

        im_load_row = tk.Frame(imf, bg=IFM_BG)
        im_load_row.pack(fill=tk.X, pady=(0, 2))
        tk.Button(im_load_row, text="🖼 Load Images", command=self._load_structure_images,
                  bg="#1abc9c", fg="#ffffff", activebackground="#48c9b0",
                  relief=tk.FLAT, cursor="hand2", font=("Helvetica", 8, "bold")).pack(side=tk.LEFT, padx=(0, 4))
        tk.Button(im_load_row, text="📁 Load Folder", command=self._load_structure_folder,
                  bg="#f39c12", fg="#1b1b1b", activebackground="#f5b041",
                  relief=tk.FLAT, cursor="hand2", font=("Helvetica", 8, "bold")).pack(side=tk.LEFT, padx=(0, 4))
        # M3-138: recovers a previous Automatic Search run's progress
        # after the app itself never got to finish it cleanly -- see
        # _load_and_resume_ifm_images's own docstring for the full
        # explanation of how it matches files back to nodes.
        tk.Button(im_load_row, text="\U0001F504 Load & Resume", command=self._load_and_resume_ifm_images,
                  bg="#27ae60", fg="#ffffff", activebackground="#2ecc71",
                  relief=tk.FLAT, cursor="hand2", font=("Helvetica", 8, "bold")).pack(side=tk.LEFT, padx=(0, 4))
        tk.Button(im_load_row, text="✕", command=self._clear_structure_images, width=2,
                  bg="#e74c3c", fg="#ffffff", activebackground="#c0392b",
                  relief=tk.FLAT, cursor="hand2", font=("Helvetica", 8, "bold")).pack(side=tk.LEFT)

        im_search_row = tk.Frame(imf, bg=IFM_BG)
        im_search_row.pack(fill=tk.X, pady=(2, 4))
        tk.Button(im_search_row, text="\U0001F50D  Search Images", command=self._search_structure_images,
                  bg="#e67e22", fg="#ffffff", activebackground="#f39c12",
                  relief=tk.RIDGE, bd=3, cursor="hand2",
                  font=("Helvetica", 10, "bold")).pack(fill=tk.X, ipady=4)

        # M3-88: one-click automatic sourcing -- searches every node name in
        # the loaded IFM .xmind file, one by one, in the same order the
        # images get pasted back in, and downloads the first usable image
        # for each with no browser window and no per-image clicking. IFM
        # only (not F-Node) since it's the only section whose images are
        # sourced from real node titles; RXF reaches the same logic through
        # its existing "IFM Section" checkbox instead of a second button --
        # see _rxf_auto_fill_ifm_images.
        im_auto_row = tk.Frame(imf, bg=IFM_BG)
        im_auto_row.pack(fill=tk.X, pady=(4, 4))
        tk.Button(im_auto_row, text="\U0001F916  Automatic Search option", command=self._start_ifm_auto_search,
                  bg="#8e44ad", fg="#ffffff", activebackground="#a569bd",
                  relief=tk.RIDGE, bd=3, cursor="hand2",
                  font=("Helvetica", 10, "bold")).pack(fill=tk.X, ipady=4)

        # M3-116: how many parallel headless Chromium instances Automatic
        # Search runs at once (see _wie_run_auto_search_pool). No fixed
        # upper bound here (see_start_ifm_auto_search's clamp) beyond a
        # sane spinbox arrow range and the natural cap of "however many
        # nodes are actually left to search" applied later -- opening
        # more browsers than that would just leave extras idle.
        im_auto_browsers_row = tk.Frame(imf, bg=IFM_BG)
        im_auto_browsers_row.pack(fill=tk.X, pady=(2, 0))
        tk.Label(im_auto_browsers_row, text="Parallel browsers:", bg=IFM_BG, fg=IFM_FG,
                 font=("Helvetica", 8, "bold")).pack(side=tk.LEFT, padx=(0, 4))
        self.ifm_auto_browsers_var = tk.StringVar(value="6")  # M3-120: 6 found to be the sweet
                                                               # spot -- fast enough to matter,
                                                               # not so many that most machines
                                                               # start choking on RAM/CPU.
        ifm_auto_browsers_spin = tk.Spinbox(im_auto_browsers_row, from_=1, to=9999, width=4,
                                            textvariable=self.ifm_auto_browsers_var,
                                            justify=tk.CENTER)
        ifm_auto_browsers_spin.pack(side=tk.LEFT)
        bind_mousewheel_to_spinbox(ifm_auto_browsers_spin)

        # M3-166: Automatic Search's Chromium instances normally run
        # headless (no visible window). Ticking this runs them visibly
        # instead -- handy for watching what a search is doing or
        # diagnosing a stuck/blocked one. Shared with GFM's identical
        # checkbox below (same tk.BooleanVar) since both sections'
        # Automatic Search browsers are already the same underlying
        # pool/cache -- see WIE_AUTO_SEARCH_SHOW_BROWSER's own comment.
        # Only affects browsers launched after it's changed; already-open
        # ones (from "Open Browsers") keep whatever mode they were
        # opened with until closed and reopened.
        self.auto_search_show_browser_var = tk.BooleanVar(value=False)
        tk.Checkbutton(imf, text="Show browser windows (instead of running headless)",
                       variable=self.auto_search_show_browser_var,
                       command=self._sync_auto_search_show_browser_flag,
                       bg=IFM_BG, fg=IFM_FG,
                       activebackground=IFM_BG, selectcolor=IFM_SELECT,
                       font=("Helvetica", 8), wraplength=280,
                       justify=tk.LEFT).pack(anchor="w", pady=(2, 0))

        # M3-119: how many extra passes Automatic Search retries a node
        # that didn't find a usable image, before finally leaving it
        # unimaged (used to be a hard-coded 10 -- see
        # _ifm_get_max_retry_passes / _run_ifm_auto_search /
        # _rxf_auto_fill_ifm_images). 0 means "no retries -- one pass only".
        im_auto_retries_row = tk.Frame(imf, bg=IFM_BG)
        im_auto_retries_row.pack(fill=tk.X, pady=(2, 0))
        tk.Label(im_auto_retries_row, text="Retry passes:", bg=IFM_BG, fg=IFM_FG,
                 font=("Helvetica", 8, "bold")).pack(side=tk.LEFT, padx=(0, 4))
        self.ifm_auto_retries_var = tk.StringVar(value="4")  # M3-120: 4 found to be the sweet
                                                              # spot -- catches nearly everything
                                                              # a retry can fix without dragging
                                                              # a run out chasing terms that
                                                              # simply have no usable image.
        ifm_auto_retries_spin = tk.Spinbox(im_auto_retries_row, from_=0, to=999, width=4,
                                           textvariable=self.ifm_auto_retries_var,
                                           justify=tk.CENTER)
        ifm_auto_retries_spin.pack(side=tk.LEFT)
        bind_mousewheel_to_spinbox(ifm_auto_retries_spin)

        # M3-119: "Open Browsers" pre-launches (and keeps sitting open) the
        # same number of headless Chromium instances the "Parallel browsers"
        # spinbox above is currently set to, so Automatic Search doesn't
        # have to pay that cold-launch time -- and the timeouts/errors it
        # can cause on the first search(es) -- inside the timed run itself.
        # The button doubles as "Close Browsers" once they're open; see
        # _toggle_ifm_prewarm_browsers. Disabled for the duration of an
        # Automatic Search run (see _start_ifm_auto_search /
        # _run_ifm_auto_search's _finish) so it can't be used to yank the
        # browsers a running search is actively using.
        self._ifm_browsers_prewarmed = False
        im_auto_prewarm_row = tk.Frame(imf, bg=IFM_BG)
        im_auto_prewarm_row.pack(fill=tk.X, pady=(4, 0))
        self.ifm_prewarm_btn = tk.Button(
            im_auto_prewarm_row, text="\U0001F310  Open Browsers",
            command=self._toggle_ifm_prewarm_browsers,
            bg="#16a085", fg="#ffffff", activebackground="#1abc9c",
            relief=tk.RIDGE, bd=2, cursor="hand2", font=("Helvetica", 9, "bold"))
        self.ifm_prewarm_btn.pack(fill=tk.X, ipady=2)

        # Small green "busy" spinner + live status text, shown whenever an
        # automatic search is running -- shared by this section's own
        # button (_run_ifm_auto_search) AND RXF's "Automatic search"
        # checkbox (_rxf_auto_fill_ifm_images), since both are the exact
        # same underlying search just triggered from different places.
        # Idle (no search running): empty canvas, empty status text.
        ifm_spinner_row = tk.Frame(imf, bg=IFM_BG)
        ifm_spinner_row.pack(fill=tk.X, pady=(0, 2))
        self.ifm_spinner_canvas = tk.Canvas(ifm_spinner_row, width=18, height=18,
                                             bg=IFM_BG, highlightthickness=0)
        self.ifm_spinner_canvas.pack(side=tk.LEFT, padx=(0, 6))
        self.ifm_auto_status_var = tk.StringVar(value="")
        tk.Label(ifm_spinner_row, textvariable=self.ifm_auto_status_var,
                 bg=IFM_BG, fg="#2ecc71", font=("Helvetica", 8, "bold"),
                 wraplength=250, justify=tk.LEFT).pack(side=tk.LEFT, fill=tk.X)
        self._ifm_spinner_angle = 0
        self._ifm_spinner_active = False

        # M3-135 fix (this label's text clipping on both left and right
        # once counts got past ~1,000): unlike the spinner status label
        # right above it (ifm_auto_status_var, which already sets
        # wraplength=250), this one had no wraplength at all. A Tk Label
        # with no wraplength never wraps -- it just requests however much
        # width its text needs. Once the text got long enough (four-digit
        # counts, e.g. "1,342 image(s) loaded this run (1,500 total in
        # pool) -- not yet placed on any node"), it overflowed this
        # panel's fixed width. Center anchor (Label's own default) is
        # what made it look clipped on BOTH sides rather than just
        # trailing off on the right -- the label wanted to grow evenly in
        # both directions from its own center, and the panel simply
        # doesn't grow to match, so both ends got cut off by the frame.
        # Matching the spinner label's own wraplength=250/justify=LEFT,
        # plus anchor="w" so wrapped lines stay left-aligned instead of
        # each one re-centering under the last, fixes it the same way --
        # and _update_structure_images_status below now comma-formats the
        # counts too, so it holds up cleanly all the way to 100k+ images.
        tk.Label(imf, textvariable=self.structure_images_status_var,
                 bg=IFM_BG, fg=IFM_MUTED, font=("Helvetica", 8),
                 wraplength=250, justify=tk.LEFT, anchor="w").pack(fill=tk.X, pady=(4, 0))

        ifm_size_frame = tk.LabelFrame(imf, text=" IFM Image Size ",
                                       bg=IFM_BG, fg=IFM_FG,
                                       font=("Helvetica", 8, "bold"), padx=6, pady=6)
        ifm_size_frame.pack(fill=tk.X, pady=(8, 0))

        self.ifm_img_width_var = tk.IntVar(value=240)
        self.ifm_img_height_var = tk.IntVar(value=180)
        _var_spin_row(ifm_size_frame, "Image Width", self.ifm_img_width_var,
                      from_val=10, to_val=2000, row_bg=IFM_BG, row_fg=IFM_FG)
        _var_spin_row(ifm_size_frame, "Image Height", self.ifm_img_height_var,
                      from_val=10, to_val=2000, row_bg=IFM_BG, row_fg=IFM_FG)

        self.ifm_random_size_var = tk.BooleanVar(value=False)
        tk.Checkbutton(ifm_size_frame, text="Custom / Random Size (ignore default W/H above)",
                       variable=self.ifm_random_size_var,
                       bg=IFM_BG, fg=IFM_FG,
                       activebackground=IFM_BG, selectcolor=IFM_SELECT,
                       font=("Helvetica", 8), wraplength=280, justify=tk.LEFT).pack(anchor="w", pady=(4, 2))

        # M3-165: Automatic Search normally accepts the first usable
        # candidate off the results page, so the same term always resolves
        # to the same top hit. Ticked, _wie_search_and_download_one
        # shuffles its candidate list first and takes a random one of
        # whatever that page detected. Written straight to the module-level
        # WIE_RANDOM_CANDIDATE_PICK flag (here and in
        # _start_ifm_auto_search) because the candidate walk runs in worker
        # threads that can't read a Tk variable.
        self.ifm_random_candidate_var = tk.BooleanVar(value=False)
        tk.Checkbutton(ifm_size_frame,
                       text="Pick a random candidate (instead of always the first detected)",
                       variable=self.ifm_random_candidate_var,
                       command=self._sync_ifm_random_candidate_flag,
                       bg=IFM_BG, fg=IFM_FG,
                       activebackground=IFM_BG, selectcolor=IFM_SELECT,
                       font=("Helvetica", 8), wraplength=280, justify=tk.LEFT).pack(anchor="w", pady=(2, 2))

        self.ifm_replace_existing_var = tk.BooleanVar(value=False)
        tk.Checkbutton(ifm_size_frame, text="Replace images already in the file (instead of only "
                                            "filling in nodes with no image)",
                       variable=self.ifm_replace_existing_var,
                       bg=IFM_BG, fg=IFM_FG,
                       activebackground=IFM_BG, selectcolor=IFM_SELECT,
                       font=("Helvetica", 8), wraplength=280, justify=tk.LEFT).pack(anchor="w", pady=(2, 2))

        self.ifm_size_assignment: List[tuple] = []
        tk.Button(ifm_size_frame, text="\U0001F3B2 Randomize Size", command=self._randomize_ifm_sizes,
                  bg="#e84393", fg="#ffffff", activebackground="#ff85b8",
                  relief=tk.FLAT, cursor="hand2", font=("Helvetica", 9, "bold")).pack(fill=tk.X, pady=(2, 0))

        # IFM's Preview/Export -- same auto-delete-timer / open-after-export
        # pattern as the main Export box, scoped to just this section.
        ifm_action_row = tk.Frame(imf, bg=IFM_BG)
        ifm_action_row.pack(fill=tk.X, pady=(6, 0))
        tk.Button(ifm_action_row, text="👁 Preview", command=self._ifm_preview,
                  bg="#6c5ce7", fg="#ffffff", activebackground="#a29bfe",
                  relief=tk.FLAT, cursor="hand2", font=("Helvetica", 9, "bold")).pack(side=tk.LEFT, fill=tk.X, expand=True, padx=(0, 3))
        tk.Button(ifm_action_row, text="📤 Export", command=self._ifm_export,
                  bg="#00b894", fg="#ffffff", activebackground="#55efc4",
                  relief=tk.FLAT, cursor="hand2", font=("Helvetica", 9, "bold")).pack(side=tk.LEFT, fill=tk.X, expand=True, padx=(3, 0))

        ifm_opt_row = tk.Frame(imf, bg=IFM_BG)
        ifm_opt_row.pack(fill=tk.X, pady=(4, 0))
        self._ifm_delay = self._build_autodelete_spinner(ifm_opt_row, initial_seconds=30)
        self._ifm_delay.frame.pack(side=tk.LEFT, padx=(0, 6))
        self.ifm_open_after_export_var = tk.BooleanVar(value=False)
        tk.Checkbutton(ifm_opt_row, text="Open after export",
                       variable=self.ifm_open_after_export_var,
                       bg=IFM_BG, fg=IFM_FG,
                       activebackground=IFM_BG,
                       selectcolor=IFM_SELECT,
                       font=("Helvetica", 9)).pack(side=tk.LEFT)

        # ============================================================
        # GFM (GIF for Mindmap) -- state layer (M3-144, Phase 2)
        # ============================================================
        # No widgets yet -- Phase 3 builds GFM's own AMX sub-section,
        # "Search node names from" dropdown, browser/retry controls, and
        # size settings (mirroring the IFM section immediately above this
        # one) and wires them up to the fields declared here. This block
        # only sets up what that UI will read from and write to: the flat
        # GIF pool, the Automatic Search positional mapping (plus the
        # fields needed to tell whether it's still valid), the per-GIF
        # source tag dict, and the pool's per-source cycling policy.
        # Deliberately separate from every self.ifm_*/self.structure_
        # images field above -- a GIF fetched by GFM and an image fetched
        # by IFM are pasted via two independent
        # inject_images_into_xmind_nodes calls, so sharing state between
        # them would let one tool's results silently fill the other's
        # node targets.

        # The flat pool: every GIF Phase 3's "Load GIFs"/"Load Folder"/
        # "Search GIFs" buttons or Automatic Search add lands here.
        # Mirrors self.structure_images / structure_images_status_var /
        # _structure_search_temp_dirs one-for-one.
        self.gfm_gif_pool: List[str] = []
        self._gfm_search_temp_dirs: List[str] = []
        self.gfm_gif_pool_status_var = tk.StringVar(value="No GIFs loaded")

        # Mirrors self.ifm_auto_image_source: which "Search node names
        # from" source (AMX Section vs Text Area (Condensed Data) --
        # Phase 3's dropdown will offer the same two options IFM's does)
        # each Automatic-Search-downloaded or Load & Resume-recovered
        # path in gfm_gif_pool above was actually fetched for. Entries
        # added via "Load GIFs"/"Load Folder"/"Search GIFs" are never
        # tagged here, so they stay usable regardless of which source is
        # selected -- same as IFM's manually-loaded images. A future
        # _gfm_pool_images_for_source (the GFM counterpart to
        # _ifm_pool_images_for_source) will filter gfm_gif_pool through
        # this dict before Preview/Export cycles the fallback pool, so
        # switching the dropdown after a run can't paste that run's GIFs
        # into a build made under the other source.
        self.gfm_auto_gif_source: Dict[str, str] = {}

        # Automatic Search's own per-node result mapping, kept separate
        # from the flat pool above for the same reason
        # ifm_auto_search_positional_images is: a handful of failed/
        # skipped node lookups must never shift every later GIF onto the
        # wrong node. None at index i means node i's search never found a
        # usable GIF even after retries; that node is left un-GIF'd at
        # export time rather than borrowing a neighbor's. The three
        # companion fields record exactly what this mapping was searched
        # against -- source_path mirrors ifm_auto_search_source_path
        # (None for Text Area, the loaded file's path for AMX Section),
        # sheet_indices mirrors ifm_auto_search_sheet_indices,
        # replace_existing mirrors ifm_auto_search_replace_existing --
        # so a future _gfm_get_positional_gifs_for_text_if_valid (the GFM
        # counterpart to _ifm_get_positional_images_for_text_if_valid)
        # can tell whether the mapping is still trustworthy against the
        # CURRENT file/sheets/checkbox state. All four are meant to reset
        # together wherever GFM's own AMX file is (re)loaded/cleared or a
        # fresh Automatic Search starts -- the same invalidation points
        # IFM's equivalents use.
        self.gfm_auto_search_positional_gifs: Optional[List[Optional[str]]] = None
        self.gfm_auto_search_source_path: Optional[str] = None
        self.gfm_auto_search_sheet_indices: Optional[List[int]] = None
        self.gfm_auto_search_replace_existing: Optional[bool] = None

        # Cycling policy -- M3-142 taught IFM's Text Area flow to always
        # pass allow_cycling=False to inject_images_into_xmind_nodes (a
        # partial run should leave un-found nodes blank, never repeat an
        # earlier node's image to paper over the gap) while every other
        # caller keeps the default allow_cycling=True (a pool the user
        # deliberately loaded to decorate many nodes with a handful of
        # repeating images IS meant to cycle). GFM needs the identical
        # split once Phase 3 wires up its own Preview/Export. Rather than
        # hard-code True/False at each future call site the way IFM does,
        # it's captured here as one explicit per-source policy dict, keyed
        # by the same "AMX Section" / "Text Area (Condensed Data)" strings
        # the node-source dropdown will use, so Phase 3 just looks it up.
        # Not user-facing -- no checkbox toggles these -- it exists so the
        # policy is declared once, in one place, instead of re-derived at
        # every call site.
        self.gfm_pool_allow_cycling: Dict[str, bool] = {
            "AMX Section": True,
            "Text Area (Condensed Data)": False,
        }

        # ============================================================
        # ============================================================
        # GFM (GIF for Mindmap) -- UI + wiring (M3-145, Phase 3)
        # ============================================================
        # Mirrors the IFM section above 1:1 -- same AMX sub-section shape,
        # same "Search node names from" dropdown, same Load/Load Folder/
        # Load & Resume/Search/Automatic Search/size-settings/Preview/
        # Export layout -- reading from and writing to the flat pool /
        # positional-mapping fields Phase 2 (above) already declared.
        # Two differences from IFM: an extra "Search engine" dropdown
        # (google / pinterest / google_pinterest -- see _GFM_ENGINE_LABELS)
        # since GFM offers a choice of engine and IFM doesn't, and no image
        # format anywhere -- GIFs are always kept exactly as downloaded/
        # loaded, never re-encoded, so animation survives all the way
        # through to the pasted .xmind file.
        GFM_BG, GFM_FG, GFM_MUTED, GFM_SELECT = "#3d1e4e", "#ffffff", "#d9b3f0", "#9b59b6"

        # Collapsible like a dropdown -- hidden by default (click the
        # arrow/title header to expand). See _make_collapsible_section.
        _gfm_outer, gfm = self._make_collapsible_section(
            right_content, " GIF for mindmap(GFM) Section ",
            GFM_BG, GFM_FG, GFM_SELECT, default_open=False)

        gfm_header_row = tk.Frame(gfm, bg=GFM_BG)
        gfm_header_row.pack(fill=tk.X, pady=(0, 6))

        self.gfm_enabled_var = tk.BooleanVar(value=False)
        self.gfm_switch_chk = tk.Checkbutton(gfm_header_row, text="Enable GFM",
                                              variable=self.gfm_enabled_var,
                                              bg=GFM_BG, fg=GFM_FG,
                                              activebackground=GFM_BG,
                                              selectcolor=GFM_SELECT,
                                              font=("Helvetica", 9, "bold"))
        self.gfm_switch_chk.pack(side=tk.RIGHT)

        # Same two options IFM's own dropdown offers -- see
        # _gfm_gather_search_targets, the single place that reads this and
        # branches accordingly.
        gfm_source_row = tk.Frame(gfm, bg=GFM_BG)
        gfm_source_row.pack(fill=tk.X, pady=(0, 6))
        tk.Label(gfm_source_row, text="Search node names from:",
                 bg=GFM_BG, fg=GFM_FG, font=("Helvetica", 9, "bold")).pack(side=tk.LEFT)
        self.gfm_node_source_var = tk.StringVar(value="AMX Section")
        _GFM_SOURCE_OPTIONS = ["AMX Section", "Text Area (Condensed Data)"]
        self.gfm_source_combo = tk.OptionMenu(gfm_source_row, self.gfm_node_source_var,
                                              *_GFM_SOURCE_OPTIONS)
        self._style_app_dropdown(self.gfm_source_combo, self.gfm_node_source_var, _GFM_SOURCE_OPTIONS)
        self.gfm_source_combo.pack(side=tk.LEFT, padx=(4, 0), fill=tk.X, expand=True)
        # Switching this dropdown immediately invalidates any stored
        # Automatic Search positional mapping -- mirrors
        # _on_ifm_node_source_changed exactly, just against GFM's own
        # fields.
        self.gfm_node_source_var.trace_add("write", self._on_gfm_node_source_changed)

        # GFM's own "Search engine" dropdown (no IFM equivalent -- IFM only
        # ever searches Google Images). See _GFM_ENGINE_FUNCS/_GFM_ENGINE_
        # LABELS (Phase 1) for what each option actually does.
        gfm_engine_row = tk.Frame(gfm, bg=GFM_BG)
        gfm_engine_row.pack(fill=tk.X, pady=(0, 6))
        tk.Label(gfm_engine_row, text="Search engine:",
                 bg=GFM_BG, fg=GFM_FG, font=("Helvetica", 9, "bold")).pack(side=tk.LEFT)
        self.gfm_engine_var = tk.StringVar(value=_GFM_ENGINE_LABELS["google"])
        _GFM_ENGINE_OPTIONS = list(_GFM_ENGINE_LABELS.values())
        self.gfm_engine_combo = tk.OptionMenu(gfm_engine_row, self.gfm_engine_var,
                                              *_GFM_ENGINE_OPTIONS)
        self._style_app_dropdown(self.gfm_engine_combo, self.gfm_engine_var, _GFM_ENGINE_OPTIONS)
        self.gfm_engine_combo.pack(side=tk.LEFT, padx=(4, 0), fill=tk.X, expand=True)

        # GFM's own AMX Section -- deliberately independent of the F-Node
        # AMX Section and IFM's own AMX Section: its own loaded-file state,
        # its own sheet checklist. Just needs a target .xmind file to paste
        # the GIFs below into its existing nodes.
        gfm_amx_frame = tk.LabelFrame(gfm, text=" AMX Section ",
                                      bg=GFM_BG, fg=GFM_FG,
                                      font=("Helvetica", 9, "bold"))
        gfm_amx_frame.pack(fill=tk.X, pady=(0, 8))

        self.gfm_loaded_xmind_path: Optional[str] = None

        gfm_amx_load_row = tk.Frame(gfm_amx_frame, bg=GFM_BG)
        gfm_amx_load_row.pack(fill=tk.X, pady=(4, 2))
        tk.Button(gfm_amx_load_row, text="📂 Load .xmind File", command=self._load_gfm_xmind,
                  bg="#9b59b6", fg="#ffffff", activebackground="#af7ac5",
                  relief=tk.FLAT, cursor="hand2", font=("Helvetica", 9, "bold")).pack(side=tk.LEFT, fill=tk.X, expand=True, padx=(0, 4))
        tk.Button(gfm_amx_load_row, text="✕ Clear", command=self._clear_gfm_xmind,
                  bg="#e74c3c", fg="#ffffff", activebackground="#c0392b",
                  relief=tk.FLAT, cursor="hand2", font=("Helvetica", 9, "bold")).pack(side=tk.LEFT)

        self.gfm_loaded_xmind_status_var = tk.StringVar(
            value="No file loaded -- load the .xmind app you want GIFs pasted into.")
        tk.Label(gfm_amx_frame, textvariable=self.gfm_loaded_xmind_status_var,
                 bg=GFM_BG, fg=GFM_MUTED, font=("Helvetica", 8),
                 wraplength=280, justify=tk.LEFT).pack(fill=tk.X, pady=(0, 4))

        (self.gfm_level_counts_frame, self.gfm_level_count_labels,
         self.gfm_total_nodes_var, self.gfm_total_nodes_label) = \
            self._make_xmind_level_counts_widget(gfm_amx_frame, GFM_BG, GFM_MUTED)

        tk.Label(gfm_amx_frame, text="Sheets (\U0001F4C4 include in file / \U0001F50D search for GIFs):",
                 bg=GFM_BG, fg=GFM_FG,
                 font=("Helvetica", 8, "bold"), wraplength=280, justify=tk.LEFT).pack(anchor="w", pady=(2, 0))
        self.gfm_sheets_frame = tk.Frame(gfm_amx_frame, bg=GFM_BG)
        self.gfm_sheets_frame.pack(fill=tk.X, pady=(0, 4))
        self.gfm_loaded_xmind_sheets: List[str] = []
        self.gfm_sheet_output_vars: List[tk.BooleanVar] = []
        self.gfm_sheet_include_vars: List[tk.BooleanVar] = []
        self.gfm_sheet_search_checks: List[tk.Checkbutton] = []
        self._rebuild_gfm_sheet_checklist([])

        # M3-138-equivalent: a Load & Resume mapping recovered from disk
        # (see _load_and_resume_gfm_gifs), separate from
        # gfm_auto_search_positional_gifs (Phase 2) -- that one only ever
        # gets set by a run that actually happened in this process.
        # Consumed (reset to None) the moment _start_gfm_auto_search uses
        # it to seed a new run. Invalidated the same places
        # gfm_auto_search_positional_gifs is -- see _load_gfm_xmind /
        # _clear_gfm_xmind.
        self.gfm_recovered_positional: Optional[List[Optional[str]]] = None
        self.gfm_recovered_terms: Optional[List[str]] = None
        self.gfm_recovered_sheet_indices: Optional[List[int]] = None
        self.gfm_recovered_replace_existing: Optional[bool] = None

        gfm_load_row = tk.Frame(gfm, bg=GFM_BG)
        gfm_load_row.pack(fill=tk.X, pady=(0, 2))
        tk.Button(gfm_load_row, text="\U0001F39E Load GIFs", command=self._load_gif_pool,
                  bg="#1abc9c", fg="#ffffff", activebackground="#48c9b0",
                  relief=tk.FLAT, cursor="hand2", font=("Helvetica", 8, "bold")).pack(side=tk.LEFT, padx=(0, 4))
        tk.Button(gfm_load_row, text="📁 Load Folder", command=self._load_gif_folder,
                  bg="#f39c12", fg="#1b1b1b", activebackground="#f5b041",
                  relief=tk.FLAT, cursor="hand2", font=("Helvetica", 8, "bold")).pack(side=tk.LEFT, padx=(0, 4))
        tk.Button(gfm_load_row, text="\U0001F504 Load & Resume", command=self._load_and_resume_gfm_gifs,
                  bg="#27ae60", fg="#ffffff", activebackground="#2ecc71",
                  relief=tk.FLAT, cursor="hand2", font=("Helvetica", 8, "bold")).pack(side=tk.LEFT, padx=(0, 4))
        tk.Button(gfm_load_row, text="✕", command=self._clear_gif_pool, width=2,
                  bg="#e74c3c", fg="#ffffff", activebackground="#c0392b",
                  relief=tk.FLAT, cursor="hand2", font=("Helvetica", 8, "bold")).pack(side=tk.LEFT)

        gfm_search_row = tk.Frame(gfm, bg=GFM_BG)
        gfm_search_row.pack(fill=tk.X, pady=(2, 4))
        tk.Button(gfm_search_row, text="\U0001F50D  Search GIFs", command=self._search_gfm_gifs,
                  bg="#e67e22", fg="#ffffff", activebackground="#f39c12",
                  relief=tk.RIDGE, bd=3, cursor="hand2",
                  font=("Helvetica", 10, "bold")).pack(fill=tk.X, ipady=4)

        gfm_auto_row = tk.Frame(gfm, bg=GFM_BG)
        gfm_auto_row.pack(fill=tk.X, pady=(4, 4))
        tk.Button(gfm_auto_row, text="\U0001F916  Automatic Search option", command=self._start_gfm_auto_search,
                  bg="#8e44ad", fg="#ffffff", activebackground="#a569bd",
                  relief=tk.RIDGE, bd=3, cursor="hand2",
                  font=("Helvetica", 10, "bold")).pack(fill=tk.X, ipady=4)

        gfm_auto_browsers_row = tk.Frame(gfm, bg=GFM_BG)
        gfm_auto_browsers_row.pack(fill=tk.X, pady=(2, 0))
        tk.Label(gfm_auto_browsers_row, text="Parallel browsers:", bg=GFM_BG, fg=GFM_FG,
                 font=("Helvetica", 8, "bold")).pack(side=tk.LEFT, padx=(0, 4))
        self.gfm_auto_browsers_var = tk.StringVar(value="6")
        gfm_auto_browsers_spin = tk.Spinbox(gfm_auto_browsers_row, from_=1, to=9999, width=4,
                                            textvariable=self.gfm_auto_browsers_var,
                                            justify=tk.CENTER)
        gfm_auto_browsers_spin.pack(side=tk.LEFT)
        bind_mousewheel_to_spinbox(gfm_auto_browsers_spin)

        # M3-166: GFM's counterpart to IFM's "Show browser windows"
        # checkbox above -- same self.auto_search_show_browser_var (it
        # already exists by the time this section is built, since IFM's
        # section is built first), so ticking either one ticks both and
        # they always agree, matching the fact that they control the same
        # underlying browser pool/cache.
        tk.Checkbutton(gfm, text="Show browser windows (instead of running headless)",
                       variable=self.auto_search_show_browser_var,
                       command=self._sync_auto_search_show_browser_flag,
                       bg=GFM_BG, fg=GFM_FG,
                       activebackground=GFM_BG, selectcolor=GFM_SELECT,
                       font=("Helvetica", 8), wraplength=280,
                       justify=tk.LEFT).pack(anchor="w", pady=(2, 0))

        gfm_auto_retries_row = tk.Frame(gfm, bg=GFM_BG)
        gfm_auto_retries_row.pack(fill=tk.X, pady=(2, 0))
        tk.Label(gfm_auto_retries_row, text="Retry passes:", bg=GFM_BG, fg=GFM_FG,
                 font=("Helvetica", 8, "bold")).pack(side=tk.LEFT, padx=(0, 4))
        self.gfm_auto_retries_var = tk.StringVar(value="4")
        gfm_auto_retries_spin = tk.Spinbox(gfm_auto_retries_row, from_=0, to=999, width=4,
                                           textvariable=self.gfm_auto_retries_var,
                                           justify=tk.CENTER)
        gfm_auto_retries_spin.pack(side=tk.LEFT)
        bind_mousewheel_to_spinbox(gfm_auto_retries_spin)

        self._gfm_browsers_prewarmed = False
        gfm_auto_prewarm_row = tk.Frame(gfm, bg=GFM_BG)
        gfm_auto_prewarm_row.pack(fill=tk.X, pady=(4, 0))
        self.gfm_prewarm_btn = tk.Button(
            gfm_auto_prewarm_row, text="\U0001F310  Open Browsers",
            command=self._toggle_gfm_prewarm_browsers,
            bg="#16a085", fg="#ffffff", activebackground="#1abc9c",
            relief=tk.RIDGE, bd=2, cursor="hand2", font=("Helvetica", 9, "bold"))
        self.gfm_prewarm_btn.pack(fill=tk.X, ipady=2)

        gfm_spinner_row = tk.Frame(gfm, bg=GFM_BG)
        gfm_spinner_row.pack(fill=tk.X, pady=(0, 2))
