        self.fng_total_qty_var.trace_add("write", self._on_fng_total_qty_changed)
        self.fng_inside_qty.trace_add("write", self._on_fng_inside_qty_edited)
        self.fng_line_qty_var.trace_add("write", self._on_fng_line_qty_edited)
        for _v in self.fng_edge_qty.values():
            _v.trace_add("write", self._on_fng_edge_changed)
        self.fng_selected_axis = "x"
