        def _var_spin_row(parent, label_text, var, from_val=0, to_val=3000, width=6,
                           row_bg=FNG_BG, row_fg=FNG_FG):
            row = tk.Frame(parent, bg=row_bg)
            row.pack(fill=tk.X, pady=(1, 1))
            tk.Label(row, text=label_text, bg=row_bg, fg=row_fg,
                     font=("Helvetica", 8), width=16, anchor="w").pack(side=tk.LEFT)
            spin = tk.Spinbox(row, from_=from_val, to=to_val, textvariable=var, width=width,
                              bg=self.colors["entry_bg"], fg="#000000",
                              font=("Consolas", 9), relief=tk.SOLID, bd=1)
            spin.pack(side=tk.LEFT)
            bind_mousewheel_to_spinbox(spin)
            return spin

        self.fng_dot_spacing_var = tk.IntVar(value=30)

        self.fng_origin_x_var = tk.IntVar(value=0)
        self.fng_origin_y_var = tk.IntVar(value=0)

        self.fng_img_width_var = tk.IntVar(value=300)
        self.fng_img_height_var = tk.IntVar(value=200)
        _var_spin_row(size_frame, "Image Width", self.fng_img_width_var, from_val=10, to_val=2000)
        _var_spin_row(size_frame, "Image Height", self.fng_img_height_var, from_val=10, to_val=2000)

