        # timer spinner): Windows/macOS fire <MouseWheel> with a signed
        # event.delta, X11/Linux instead fire <Button-4> (up) / <Button-5>
        # (down) with no delta at all.
        def _rxf_add_sheets_wheel(event):
            cur = self.rxf_add_sheets_count_var.get()
            if event.delta > 0:
                self.rxf_add_sheets_count_var.set(min(500, cur + 1))
            elif event.delta < 0:
                self.rxf_add_sheets_count_var.set(max(1, cur - 1))
            return "break"

        def _rxf_add_sheets_wheel_up(event):
            self.rxf_add_sheets_count_var.set(min(500, self.rxf_add_sheets_count_var.get() + 1))
            return "break"

        def _rxf_add_sheets_wheel_down(event):
            self.rxf_add_sheets_count_var.set(max(1, self.rxf_add_sheets_count_var.get() - 1))
