    def _update_structure_images_status(self):
        # M3-136: debug checkbox removed (it was only ever needed to
        # eyeball the M3-135 wrap fix without waiting through a real
        # large run) -- this now always shows the real counts. Numbers
        # are comma-formatted (f"{n:,}") so a run in the tens or hundreds
        # of thousands of images still reads cleanly rather than turning
        # into an unbroken run of digits; combined with the M3-135
        # wraplength/anchor fix on the label itself, this holds up all
        # the way through six-digit (100k+) counts.
        n = len(self.structure_images)
        if n == 0:
            self.structure_images_status_var.set("No images loaded")
            return
        run_n = getattr(self, "_ifm_auto_run_loaded_count", None)
        if run_n is not None:
            # A run is currently in progress -- show what it has actually
            # found so far as its own number, since n (the all-time pool
            # total) can include images left over from an earlier run or
            # from Load Images/Search Images, and comparing THAT against
            # this run's own "Searching nxt/total" progress is comparing
            # two unrelated counts (see M3-131).
            self.structure_images_status_var.set(
                f"{run_n:,} image(s) loaded this run ({n:,} total in pool) -- not yet placed on any node")
        else:
            self.structure_images_status_var.set(f"{n:,} image(s) loaded -- not yet placed on any node")

