    def _on_ifm_node_source_changed(self, *_args):
        """M3-141: fires whenever the "Search node names from" dropdown
        changes. Invalidates the last Automatic Search run's positional
        mapping -- it belongs to whichever source it was actually
        searched under, not to the newly selected one, and (per
        _ifm_get_positional_images_if_valid / _ifm_get_positional_
        images_for_text_if_valid) would otherwise only be caught by the
        source_path check IF that other fix is in place; this is a
        second, independent line of defense so a switch here can never
        pick up a stale mapping. Does NOT touch structure_images itself
        or ifm_auto_image_source -- those stay put (per-image source
        tagging is what keeps the CYCLING fallback correctly scoped; see
        _ifm_pool_images_for_source), and manually loaded images must
        stay available no matter which option is selected."""
        self.ifm_auto_search_positional_images = None
        self.ifm_auto_search_source_path = None
        self.ifm_auto_search_sheet_indices = None
        self.ifm_auto_search_replace_existing = None
        if hasattr(self, "structure_images_status_var"):
            self._update_structure_images_status()
        # M3-145: show/hide (and, the first time, build) the "Text Area
        # Sheets" checklist to match whichever source is now selected.
        if hasattr(self, "ifm_text_sheets_frame"):
            self._update_ifm_text_sheets_visibility()

    def _load_and_resume_ifm_images(self):
        """M3-138: recovers a previous Automatic Search run's progress
        after the app itself never got to finish it cleanly -- power
        loss, a crash, an accidental close, anything that killed the
        process before that run's own in-memory `positional` list (see
        _run_ifm_auto_search) ever got written anywhere durable. The
        only trace such a run leaves behind on disk is the temp folder
        of already-downloaded image files themselves, each one named
        "{index:03d}_{sanitized node name}_{...}.{fmt}" (see
        wie_download_and_convert) -- this reads that folder back and
        matches each file to a node in the CURRENTLY loaded .xmind file
        by BOTH its embedded index number AND its embedded node name,
        not the index alone. Matching on index alone would be wrong the
        moment anything about how that index maps to a node has
        changed since the interrupted run -- a different .xmind file
        entirely, a different "Sheets to search" selection, or a
        different "Replace existing images" setting all change which
        node index 47 (say) even IS -- so a file is only ever accepted
        if the node CURRENTLY at that index still has the same name the
        filename says it did.

        On success, stashes the recovered mapping in self.ifm_recovered_
        positional (plus a snapshot of the exact terms/sheets/setting it
        was matched against) for _start_ifm_auto_search to pick up and
        feed through as initial_positional the next time "Automatic
        Search" is pressed -- see that method and _run_ifm_auto_search's
        own initial_positional parameter. Also adds every recovered
        image straight into self.structure_images (same pool "Load
        Images"/"Load Folder" use), so the on-screen count and Preview/
        Export both already reflect them even before a single new
        search runs."""
        if not self.ifm_loaded_xmind_path:
            messagebox.showinfo(
                "No File Loaded",
                "Load the .xmind file in the IFM \U0001F4C2 AMX Section above first -- Load & "
                "Resume needs to know the exact node names/order the interrupted run was "
                "searching against, which comes from that file.")
            return
        folder = filedialog.askdirectory(
            title="Load & Resume -- Folder Of Previously Downloaded Images")
        if not folder:
            return

        sheet_indices = self._ifm_included_sheet_indices()
        replace_existing = self.ifm_replace_existing_var.get()
        dfs_nodes, terms, sheet_sizes = self._ifm_gather_multi_sheet_targets(
            self.ifm_loaded_xmind_path, sheet_indices, include_existing=replace_existing)
        if not terms:
            messagebox.showinfo(
                "Nothing To Match",
                "Every node in the checked sheet(s) already has an image (or no sheets are "
                "checked below) -- there's nothing for Load & Resume to match against.")
            return
        total = len(terms)

        try:
            filenames = os.listdir(folder)
        except Exception as e:
            messagebox.showerror("Can't Read Folder", str(e))
            return

        # Matches wie_download_and_convert's own naming: leading 3+ digit
        # index, an underscore, then the rest of the stem (sanitized node
        # name + a bit derived from the actual image URL, glued together
        # with an underscore -- see that function's own `stem` line), any
        # extension it might have been saved as.
        fname_re = re.compile(r'^(\d+)_(.+)\.(webp|jpg|jpeg|png)$', re.IGNORECASE)
        recovered: List[Optional[str]] = [None] * total
        matched_files = 0
        name_mismatch = 0
        dup_index_skipped = 0
        unmatched_files = 0

        for fname in sorted(filenames):
            m = fname_re.match(fname)
            if not m:
                unmatched_files += 1
                continue
            try:
                idx = int(m.group(1))
            except ValueError:
                unmatched_files += 1
                continue
            if idx < 1 or idx > total:
                name_mismatch += 1
                continue
            if recovered[idx - 1] is not None:
                dup_index_skipped += 1
                continue
            rest = m.group(2)
            # Same sanitizing regex _wie_search_and_download_one applies
            # to a search term before using it as this file's own
            # name_prefix -- reproduced here (not imported) since it's a
            # one-line local inside that function, not its own helper.
            expected_prefix = re.sub(r'[^A-Za-z0-9_\-]+', "_", terms[idx - 1])[:40].strip("_")
            if expected_prefix and rest.lower().startswith(expected_prefix.lower()):
                recovered[idx - 1] = os.path.join(folder, fname)
                matched_files += 1
            else:
                name_mismatch += 1

        if matched_files == 0:
            messagebox.showwarning(
                "Nothing Matched",
                "None of the files in that folder matched a node name in the currently loaded "
                ".xmind file, with the sheets currently checked and the current \"Replace "
                "existing images\" setting. Double check this is the same .xmind file, the same "
                "sheets, and the same setting the interrupted run used -- and that this is "
                "really the folder it was saving into (see \"Downloaded-image temp folder:\" "
                "near the top of that run's own .txt log file).")
            return

        existing_paths = set(self.structure_images)
        for p in recovered:
            if p and p not in existing_paths:
                existing_paths.add(p)
                self.structure_images.append(p)
                # M3-141: Load & Resume only ever runs against a loaded
                # AMX .xmind file (see the guard above), so every path it
                # recovers belongs to the "AMX Section" source -- tagged
                # the same way a live Automatic Search run's own results
                # are, so _ifm_pool_images_for_source keeps it out of a
                # Text Area build's fallback pool.
                self.ifm_auto_image_source[p] = "AMX Section"
        self._update_structure_images_status()

        self.ifm_recovered_positional = recovered
        self.ifm_recovered_terms = list(terms)
        self.ifm_recovered_sheet_indices = list(sheet_indices)
        self.ifm_recovered_replace_existing = replace_existing

        msg = f"Matched {matched_files}/{total} node(s) to an image already in that folder."
        details = []
        if name_mismatch:
            details.append(
                f"{name_mismatch} file(s) had a number whose node doesn't currently have that "
                f"name -- skipped (wrong file, or the .xmind file/sheets/\"Replace existing\" "
                f"setting changed since that run).")
        if dup_index_skipped:
            details.append(f"{dup_index_skipped} file(s) shared a number with one already "
                           f"matched -- only the first found was used.")
        if unmatched_files:
            details.append(f"{unmatched_files} file(s) in that folder didn't look like an "
                           f"Automatic Search download at all -- ignored.")
        if details:
            msg += "\n\n" + "\n".join(details)
        msg += (f"\n\nNext time you press Automatic Search (with these same sheets and setting "
               f"still checked), it will skip these {matched_files} node(s) and only search "
               f"the remaining {total - matched_files}.")
        messagebox.showinfo("Load & Resume", msg)
        self.status_var.set(f"Load & Resume: matched {matched_files}/{total} node(s) from folder.")

    # ── "🔍 Search Images" (M3-112): web search dialog feeding straight
    # into the same lists "Load Images" / "Load Folder" use. Images it
    # downloads live in a %TEMP%-based folder (see ImageSearchDialog.
    # _make_out_dir) that is tracked per-section below and deleted the
    # moment the user hits that section's "✕" button, or automatically
    # when the app exits (see _wie_cleanup_temp_dirs). Folders/files picked
    # via "Load Images" / "Load Folder" are the user's own and are never
    # touched by this cleanup. ──
    def _cleanup_search_temp_dirs(self, temp_dirs: List[str]):
        for d in temp_dirs:
            shutil.rmtree(d, ignore_errors=True)
            if d in _WIE_TEMP_DIRS:
                _WIE_TEMP_DIRS.remove(d)
        temp_dirs.clear()

    def _search_floating_images(self):
        def _on_ready(paths, temp_dir):
            for p in paths:
                if p not in self.floating_node_images:
                    self.floating_node_images.append(p)
            if temp_dir and temp_dir not in self._floating_search_temp_dirs:
                self._floating_search_temp_dirs.append(temp_dir)
            self._update_floating_images_status()
        ImageSearchDialog(self.root, _on_ready, dialog_title="F-Node Section")

    def _search_structure_images(self):
        def _on_ready(paths, temp_dir):
            for p in paths:
                if p not in self.structure_images:
                    self.structure_images.append(p)
            if temp_dir and temp_dir not in self._structure_search_temp_dirs:
                self._structure_search_temp_dirs.append(temp_dir)
            self._update_structure_images_status()
        ImageSearchDialog(self.root, _on_ready, dialog_title="IFM Section")

    # ── "\U0001F916 Automatic Search option" (M3-88): walks the IFM-loaded
    # .xmind file's nodes in the same order inject_images_into_xmind_nodes
    # pastes into, searches Google Images for each node's name one at a
    # time, and downloads the first usable image straight into
    # structure_images -- no browser window, no per-node clicking. Node
    # names that repeat elsewhere in the mindmap get qualified with their
    # parent (and grandparent, etc. as needed) so the search stays aimed at
    # the right node -- see _ifm_addressed_terms. ──
    def _ifm_dfs_targets(self, tree: Dict[str, Any],
                        include_existing: bool = False) -> List[Dict[str, Any]]:
        """Pre-order walk of an _xmind_extract_tree()-shaped dict, returning
        one entry per target node: {'title', 'ancestors'} where 'ancestors'
        is the chain of titles from the root down to (but not including)
        this node, nearest ancestor last. Order and the "skip nodes that
        already have an image" filter both match inject_images_into_xmind_
        nodes' own collect()/targets exactly (skip_nodes_with_image there
        mirrors include_existing here -- pass the same boolean, derived
        from the same "Replace existing images" checkbox, to both, or the
        two node counts can drift apart and desync image #k from target
        node #k), so image #k downloaded here lines up with target node #k
        when it's pasted back in later. include_existing=True (the
        "Replace existing images" checkbox) includes nodes that already
        have an image too, so Automatic Search can overwrite them instead
        of only filling in the ones still missing one."""
        out: List[Dict[str, Any]] = []

        def walk(node, ancestors):
            has_image = bool(node.get("_has_image"))
            if include_existing or not has_image:
                out.append({"title": node.get("title") or "", "ancestors": list(ancestors)})
            for child in (node.get("children") or []):
                walk(child, ancestors + [node.get("title") or ""])

        walk(tree, [])
        return out

    def _ifm_addressed_terms(self, dfs_nodes: List[Dict[str, Any]]) -> List[str]:
        """Builds one search term per node in dfs_nodes. A title that's
        unique across the whole tree is used as-is. A title that repeats
        elsewhere gets its nearest ancestor prefixed; if that's still not
        enough to tell it apart from the other node(s) sharing the same
        title (i.e. the parent name repeats too), the next ancestor up
        (grandparent, then great-grandparent, ...) is added as well, and so
        on until the address is unique or the root is reached.

        Disambiguation only ever needs to compare nodes that share the
        exact same title against each other -- nodes are grouped by title
        up front and each group is widened breadth-first (one bucketing
        pass per depth across the whole group at once) instead of, for
        every duplicate node individually, rescanning every other node in
        the entire mindmap at every depth. That per-node full-tree rescan
        is fine for a small hand-typed hierarchy but turns into a
        multi-minute UI freeze on a 5k-10k node mindmap with a handful of
        very common repeated labels ("Yes", "No", "Step 1", ...), since
        each of those labels' occurrences would otherwise each individually
        scan the whole tree at every depth.

        A node with no name of its own (blank/whitespace-only title) is
        never searched as the literal "(untitled)" placeholder -- instead
        it borrows its nearest NAMED ancestor's title outright (parent
        first; if the parent is also blank, grandparent; and so on up to
        the root) so the search still aims at something concrete instead
        of nothing. These borrowing nodes are kept out of the duplicate-
        title grouping/disambiguation above entirely, since "borrowed an
        ancestor's name" isn't the same situation as "two distinctly-named
        nodes happen to collide" -- folding it in would risk changing the
        disambiguating prefix a real, unrelated same-named node elsewhere
        gets. Only when every ancestor up to the root is also blank does
        this fall back to "(untitled)".

        M3-132: a single named ancestor can have a long CHAIN of these --
        10, 20 blank nodes nested one under the next, not siblings, all
        resolving to the very same borrowed name (a real mindmap showed
        this: a stack of nameless nodes under one named vegetable). Every
        one of them searching the literal identical query and leaning on
        wie_download_and_convert's run-wide seen_hashes dedup to force
        each to a DIFFERENT candidate works for the first several, but
        that dedup only skips ahead to the next result on the SAME
        results page -- so a chain of 15-20 forces mining deep into one
        query's results, and ordinary image searches reliably run out of
        genuinely on-topic photos well before position 15-20; what's left
        that far down a generic single-word query tends to be icons,
        clipart, and cartoons, not photos -- which is exactly the
        complaint this fixes. So each occurrence of the same borrowed
        name additionally gets a distinct, still-on-topic query variant
        (plain, then "<name> photo", "<name> picture", "<name> close up",
        ... cycling through _IFM_BORROW_QUERY_VARIANTS) instead of the
        bare name every time -- spreading the chain across several fresh,
        independently-ranked result pages instead of one page mined
        deeper and deeper. seen_hashes still applies on top of this as a
        safety net for whenever two variants happen to surface the exact
        same photo anyway."""
        def norm(s):
            return (s or "").strip().casefold()

        # Nearest-ancestor-first per node, computed once and reused across
        # every depth level instead of being rebuilt on every comparison.
        ancestors_nearest_first = [list(reversed(n["ancestors"])) for n in dfs_nodes]

        terms: List[Optional[str]] = [None] * len(dfs_nodes)

        named_indices: List[int] = []
        # M3-132: kept deliberately generic and photographic -- no
        # "illustration"/"icon"/"clipart"/"drawing"/"cartoon"/"vector"
        # style words, since those would bias results toward the exact
        # non-photo look this fix exists to avoid. Each occurrence of the
        # same borrowed name cycles to the next entry so a long chain of
        # blank descendants spreads across several fresh, independently-
        # ranked searches instead of mining one query's results ever
        # deeper (see the M3-132 docstring note above).
        borrow_occurrence: Dict[str, int] = {}
        for i, n in enumerate(dfs_nodes):
            if (n["title"] or "").strip():
                named_indices.append(i)
                continue
            borrowed = ""
            for anc in ancestors_nearest_first[i]:
                anc = (anc or "").strip()
                if anc:
                    borrowed = anc
                    break
            if not borrowed:
                terms[i] = "(untitled)"
                continue
            key = norm(borrowed)
            occ = borrow_occurrence.get(key, 0)
            borrow_occurrence[key] = occ + 1
            variant = self._IFM_BORROW_QUERY_VARIANTS[occ % len(self._IFM_BORROW_QUERY_VARIANTS)]
            terms[i] = f"{borrowed}{variant}"

        titles_norm = [norm(dfs_nodes[i]["title"]) for i in named_indices]
        groups: Dict[str, List[int]] = {}
        for pos, t in enumerate(titles_norm):
            groups.setdefault(t, []).append(named_indices[pos])

        for indices in groups.values():
            if len(indices) == 1:
                i = indices[0]
                terms[i] = (dfs_nodes[i]["title"] or "").strip() or "(untitled)"
                continue

            # This title repeats -- widen the address for this group only,
            # one depth level at a time, splitting nodes into buckets by
            # their (still-truncated) ancestor chain. A bucket that's down
            # to one node is unique and settles there; a bucket still
            # sharing an identical address keeps growing, unless a member
            # has run out of ancestors to add (reached the root), in which
            # case IT settles at its own max depth even if still ambiguous
            # -- matching the original per-node stopping rule exactly.
            remaining = list(indices)
            depth = 0
            resolved_depth: Dict[int, int] = {}
            while remaining:
                buckets: Dict[tuple, List[int]] = {}
                for i in remaining:
                    anc = ancestors_nearest_first[i][:depth]
                    key = tuple(norm(a) for a in reversed(anc))
                    buckets.setdefault(key, []).append(i)
                still_remaining: List[int] = []
                for idxs in buckets.values():
                    if len(idxs) == 1:
                        resolved_depth[idxs[0]] = depth
                        continue
                    growable = [i for i in idxs if depth < len(ancestors_nearest_first[i])]
                    maxed = [i for i in idxs if depth >= len(ancestors_nearest_first[i])]
                    for i in maxed:
                        resolved_depth[i] = depth
                    still_remaining.extend(growable)
                remaining = still_remaining
                depth += 1

            for i in indices:
                title = (dfs_nodes[i]["title"] or "").strip() or "(untitled)"
                d = resolved_depth[i]
                prefix_root_first = list(reversed(ancestors_nearest_first[i][:d]))
                terms[i] = " ".join([p for p in prefix_root_first if p] + [title])

        return terms

    # ── Green "busy" spinner + live status line in the IFM section, shown
    # while an automatic search is running. Shared by both this section's
    # own threaded button (_run_ifm_auto_search) and RXF's synchronous
    # "Automatic search" checkbox (_rxf_auto_fill_ifm_images) -- both are
    # the exact same underlying search, just triggered from different
    # places, so one indicator does for both. Safe to call from the main
    # thread only; the threaded flow marshals its calls through
    # self.root.after(0, ...). ──
    def _ifm_spinner_tick(self):
        try:
            c = self.ifm_spinner_canvas
            c.delete("all")
            self._ifm_spinner_angle = (self._ifm_spinner_angle + 30) % 360
            c.create_arc(2, 2, 16, 16, start=self._ifm_spinner_angle, extent=100,
                         outline="#2ecc71", width=3, style="arc")
        except tk.TclError:
            pass

    def _ifm_spinner_animate(self):
        if not self._ifm_spinner_active:
            return
        self._ifm_spinner_tick()
        self.root.after(80, self._ifm_spinner_animate)

    def _ifm_spinner_start(self, status: str = "Searching ..."):
        self._ifm_spinner_active = True
        try:
            self.ifm_auto_status_var.set(status)
        except tk.TclError:
            pass
        self._ifm_spinner_animate()

    def _ifm_spinner_stop(self, status: str = ""):
        self._ifm_spinner_active = False
        try:
            self.ifm_spinner_canvas.delete("all")
            self.ifm_auto_status_var.set(status)
        except tk.TclError:
            pass

    @staticmethod
    def _ifm_fmt_duration(seconds: float) -> str:
        seconds = max(0, int(seconds))
        h, rem = divmod(seconds, 3600)
        m, s = divmod(rem, 60)
        return f"{h}:{m:02d}:{s:02d}" if h else f"{m}:{s:02d}"

    def _ifm_auto_tick_timer(self, win: tk.Toplevel):
        """Ticks once a second while an Automatic Search is running,
        updating the popup's "Elapsed: .../Est. remaining: ..." line.
        Elapsed is wall-clock time since the whole run (all passes)
        started. Remaining is estimated from the average time-per-item
        seen so far (across every pass, not just this one -- retry
        passes tend to run slower per item since they're disproportionately
        made up of connection errors/timeouts, so folding them into the
        average keeps the estimate honest instead of assuming retries
        will be as fast as the initial pass) times however many items are
        still outstanding in whichever pass is currently running. Stops
        rescheduling itself once the run is no longer active -- the
        final elapsed time is left showing rather than reset.
        """
        try:
            if not win.winfo_exists():
                return
            elapsed = time.time() - self._ifm_auto_start_time
            with self._ifm_auto_progress_lock:
                processed = self._ifm_auto_total_processed
                remaining = self._ifm_auto_current_batch_remaining
            text = f"Elapsed: {self._ifm_fmt_duration(elapsed)}"
            if processed > 0 and remaining > 0:
                eta = (elapsed / processed) * remaining
                text += f"  |  Est. remaining: ~{self._ifm_fmt_duration(eta)}"
            win.timer_var.set(text)
        except tk.TclError:
            return
        if getattr(self, "_ifm_auto_search_running", False):
            self.root.after(1000, lambda: self._ifm_auto_tick_timer(win))

    def _ifm_get_max_retry_passes(self) -> int:
        """Reads the "Retry passes" spinbox, clamped to a sane non-negative
        integer (falling back to 10, the old hard-coded value, if the box
        is empty/garbage). Always call this from the main thread -- Tk
        StringVars aren't safe to read from a worker thread -- and pass the
        result down as a plain int to any background thread that needs it,
        the same way num_browsers already is."""
        try:
            n = int(self.ifm_auto_retries_var.get())
        except (ValueError, tk.TclError):
            n = 10
        n = max(0, n)
        self.ifm_auto_retries_var.set(str(n))
        return n

    def _toggle_ifm_prewarm_browsers(self):
        """"Open Browsers" / "Close Browsers" toggle for the pre-warmed
        pool (see wie_prewarm_auto_search_pool / wie_close_auto_search_pool
        / wie_get_prewarmed_contexts / wie_verify_auto_search_pool). Both
        directions run on a background thread since launching, verifying,
        or closing real Chromium processes can take a moment and must
        never freeze the UI; the button is disabled (showing "Opening..."/
        "Closing...") for that stretch so it can't be double-clicked
        mid-toggle.

        M3-119 fix: this used to special-case num_browsers == 1 by
        pre-warming the unrelated _wie_get_persistent_context cache
        instead of this pool -- which meant Automatic Search's actual
        num_browsers == 1 path (the default, and the only path RXF's
        "Automatic search" checkbox ever uses) never touched what this
        button opened at all. Now every count, including 1, goes through
        the same pool, and _wie_auto_search_download / _rxf_auto_fill_
        ifm_images both know to check it -- see run_batch inside
        _run_ifm_auto_search and search_one inside _rxf_auto_fill_ifm_
        images."""
        if getattr(self, "_ifm_auto_search_running", False):
            return  # button is disabled during a run anyway; belt-and-braces
        if getattr(self, "_ifm_browsers_prewarmed", False):
            self.ifm_prewarm_btn.config(state=tk.DISABLED, text="Closing browsers ...")

            def _do_close():
                wie_close_auto_search_pool(log=lambda m: print(f"[IFM Auto Search] {m}"))
                self.root.after(0, _finish_close)

            def _finish_close():
                self._ifm_browsers_prewarmed = False
                self.ifm_prewarm_btn.config(state=tk.NORMAL, text="\U0001F310  Open Browsers",
                                            bg="#16a085", activebackground="#1abc9c")

            threading.Thread(target=_do_close, daemon=True).start()
        else:
            try:
                num_browsers = max(1, int(self.ifm_auto_browsers_var.get()))
            except (ValueError, tk.TclError):
                num_browsers = 1
            self.ifm_prewarm_btn.config(state=tk.DISABLED, text="Opening browsers ...")

            def _do_open():
                try:
                    wie_prewarm_auto_search_pool(
                        num_browsers, log=lambda m: print(f"[IFM Auto Search] {m}"))
                    # Launching successfully doesn't mean still alive a
                    # moment later -- confirm each one can actually load a
                    # page before calling it "open" (see
                    # wie_verify_auto_search_pool's docstring for why).
                    verified = wie_verify_auto_search_pool(
                        log=lambda m: print(f"[IFM Auto Search] {m}"))
                except Exception as e:
                    print(f"[IFM Auto Search] Pre-launching browser(s) failed -- {e}")
                    verified = 0
                self.root.after(0, lambda: _finish_open(verified, num_browsers))

            def _finish_open(verified: int, requested: int):
                if verified >= 1:
                    self._ifm_browsers_prewarmed = True
                    label = (f"\U0001F310  Close Browsers ({verified})" if verified == requested
                             else f"\U0001F310  Close Browsers ({verified}/{requested} opened)")
                    self.ifm_prewarm_btn.config(state=tk.NORMAL, text=label,
                                                bg="#c0392b", activebackground="#e74c3c")
                    if verified < requested:
                        messagebox.showwarning(
                            "Some Browsers Failed To Open",
                            f"Only {verified} of {requested} browser(s) opened and passed their "
                            "startup check. Automatic Search can still use the "
                            f"{verified} that did -- but you asked for {requested} in the "
                            "\"Parallel browsers\" box above, so it'll fall back to launching "
                            "fresh ones for a full match if you start a search with that count.")
                else:
                    wie_close_auto_search_pool()
                    self._ifm_browsers_prewarmed = False
                    self.ifm_prewarm_btn.config(state=tk.NORMAL, text="\U0001F310  Open Browsers")
                    messagebox.showerror(
                        "Browser Launch Failed",
                        "Couldn't pre-launch the browser(s) -- make sure Playwright/Chromium is "
                        "installed (pip install playwright && playwright install chromium). "
                        "Check the terminal/console output for the exact error.")

            threading.Thread(target=_do_open, daemon=True).start()

    # M3-165: the two "Pick a random candidate" checkboxes' command=
    # callbacks. Each just mirrors its Tk variable onto the module-level
    # flag the search worker threads actually read (they can't touch a Tk
    # variable themselves). Called on every toggle AND again at the top of
    # each _start_*_auto_search, so a run always starts in sync even if the
    # checkbox was set before this build's widgets existed (Load & Resume,
    # restored settings, etc.).
    def _sync_ifm_random_candidate_flag(self):
        global WIE_RANDOM_CANDIDATE_PICK
        try:
            WIE_RANDOM_CANDIDATE_PICK = bool(self.ifm_random_candidate_var.get())
        except (AttributeError, tk.TclError):
            pass

    def _sync_gfm_random_candidate_flag(self):
        global GFM_RANDOM_CANDIDATE_PICK
        try:
            GFM_RANDOM_CANDIDATE_PICK = bool(self.gfm_random_candidate_var.get())
        except (AttributeError, tk.TclError):
            pass

    # M3-166: mirrors self.auto_search_show_browser_var (shared by IFM's
    # and GFM's "Show browser windows" checkboxes) onto the module-level
    # WIE_AUTO_SEARCH_SHOW_BROWSER flag the search worker threads actually
    # read -- same pattern, and same reason, as the random-candidate sync
    # methods above. Called on every toggle AND again at the top of each
    # _start_*_auto_search, so a run always starts in sync even if the
    # checkbox was set before this build's widgets existed.
    def _sync_auto_search_show_browser_flag(self):
        global WIE_AUTO_SEARCH_SHOW_BROWSER
        try:
            WIE_AUTO_SEARCH_SHOW_BROWSER = bool(self.auto_search_show_browser_var.get())
        except (AttributeError, tk.TclError):
            pass

    def _start_ifm_auto_search(self):
        if getattr(self, "_ifm_auto_search_running", False):
            messagebox.showinfo("Already Running", "An automatic search is already in progress.")
            return
        # M3-141: captured once, up front, before the background thread
        # starts -- this is the source _run_ifm_auto_search's own finally
        # block now stamps onto the run's results (instead of blindly
        # reading self.ifm_loaded_xmind_path there), so a Text Area run's
        # mapping stays correctly tagged even if an .xmind file happens
        # to also be loaded in the AMX Section. See _ifm_gather_search_
        # targets, which already branches on this same value.
        search_source = self.ifm_node_source_var.get() if hasattr(self, "ifm_node_source_var") else "AMX Section"
        self._sync_ifm_random_candidate_flag()  # M3-165
        self._sync_auto_search_show_browser_flag()  # M3-166
        replace_existing = self.ifm_replace_existing_var.get()
        gathered = self._ifm_gather_search_targets(include_existing=replace_existing)
        if gathered is None:
            # Already explained via a messagebox inside _ifm_gather_search_targets
            # (no AMX file loaded / text area empty / text area didn't parse).
            return
        dfs_nodes, terms, sheet_indices, sheet_sizes = gathered
        if not dfs_nodes:
            messagebox.showinfo("Nothing To Do",
                                 "Every node in the checked sheet(s) already has an image "
                                 "(or no sheets are checked below). Tick \"Replace images "
                                 "already in the file\" above to search for those too.")
            return
        try:
            # No fixed ceiling here anymore -- just needs to be a sane
            # positive integer. _run_ifm_auto_search still clamps this
            # down to however many terms there actually are, so typing
            # more browsers than there are nodes just falls back to one
            # browser per node instead of leaving idle browsers running.
            num_browsers = max(1, int(self.ifm_auto_browsers_var.get()))
        except (ValueError, tk.TclError):
            num_browsers = 1
        self.ifm_auto_browsers_var.set(str(num_browsers))
        max_retry_passes = self._ifm_get_max_retry_passes()

        # M3-138: a matching Load & Resume mapping (see _load_and_
        # resume_ifm_images) means this run doesn't have to start from
        # node 1 -- it can pick up right where an earlier, interrupted
        # run left off. Only trusted if it was matched against this
        # EXACT terms list (same file, same sheets, same "Replace
        # existing" setting) -- anything else and the index<->node
        # mapping it recorded can no longer be trusted, so it's ignored
        # rather than risking a mismatched apply.
        initial_positional = None
        recovered_count = 0
        if (getattr(self, "ifm_recovered_positional", None) is not None
                and getattr(self, "ifm_recovered_terms", None) == terms
                and getattr(self, "ifm_recovered_sheet_indices", None) == sheet_indices
                and getattr(self, "ifm_recovered_replace_existing", None) == replace_existing):
            initial_positional = list(self.ifm_recovered_positional)
            recovered_count = sum(1 for p in initial_positional if p)

        browser_desc = ("one at a time, using a hidden browser (no windows will pop up)"
                        if num_browsers == 1 else
                        f"using {num_browsers} hidden browsers running at once, to go faster")
        sheet_desc = (f" across the {len(sheet_indices)} checked sheets"
                     if len(sheet_indices) > 1 else "")
        recovered_desc = (f"\n\n{recovered_count} of these already have an image recovered via "
                          f"\"Load & Resume\" and won't be re-searched -- only the remaining "
                          f"{len(terms) - recovered_count} will actually be looked up."
                          if recovered_count else "")
        if not messagebox.askyesno(
                "Automatic Search",
                f"This will search Google Images for each of the {len(terms)} node name(s){sheet_desc} "
                f"below, {browser_desc}, and download the first usable image for each. Node names "
                "that repeat elsewhere in the mindmap are automatically qualified with their parent "
                "(and grandparent, etc. as needed) so each search stays aimed at the right node."
                f"{recovered_desc}\n\n"
                "This can take a while for a large mindmap. Continue?"):
            return

        if initial_positional is not None:
            # Consumed once -- don't let it silently reapply to some
            # later, unrelated run.
            self.ifm_recovered_positional = None
            self.ifm_recovered_terms = None
            self.ifm_recovered_sheet_indices = None
            self.ifm_recovered_replace_existing = None

        self._ifm_auto_stop_event = threading.Event()
        self._ifm_auto_search_running = True
        # Browsers a running search is using can't be safely yanked out
        # from under it via the toggle button -- see _toggle_ifm_prewarm_
        # browsers and this method's own worker thread's _finish() below,
        # which re-enables it once the run (and every retry pass) is over.
        self.ifm_prewarm_btn.config(state=tk.DISABLED)

        # M3-126: every Automatic Search run gets its own timestamped .txt
        # log file (independent of the on-screen log box, which is capped
        # at _IFM_AUTO_LOG_MAX_LINES and disappears once the popup is
        # closed) so a full record of what succeeded/failed -- and why --
        # survives the run and can be handed back for debugging. Lives
        # next to the existing persistent Chromium profile dirs (same
        # ~/.webpage_image_extractor convention as _WIE_PROFILE_DIR)
        # rather than in one of the tempfile.mkdtemp() image-output dirs,
        # since those get rmtree'd by _wie_cleanup_temp_dirs at exit.
        log_dir = os.path.join(os.path.expanduser("~"), ".webpage_image_extractor",
                               "ifm_auto_search_logs")
        try:
            os.makedirs(log_dir, exist_ok=True)
        except Exception:
            log_dir = tempfile.gettempdir()
        log_file_path = os.path.join(
            log_dir, f"ifm_auto_search_{time.strftime('%Y%m%d_%H%M%S')}.txt")

        win = self._build_ifm_auto_search_window(
            len(terms), log_file_path, num_browsers=num_browsers, terms=terms,
            sheet_indices=sheet_indices, replace_existing=replace_existing,
            max_retry_passes=max_retry_passes, search_source=search_source)
        threading.Thread(target=self._run_ifm_auto_search,
                         args=(terms, win, num_browsers, max_retry_passes, sheet_indices,
                               replace_existing, log_file_path),
                         kwargs={"initial_positional": initial_positional,
                                 "search_source": search_source},
                         daemon=True).start()

    def _build_ifm_auto_search_window(self, total: int, log_file_path: Optional[str] = None,
                                      num_browsers: int = 1, terms: Optional[List[str]] = None,
                                      sheet_indices: Optional[List[int]] = None,
                                      replace_existing: bool = False,
                                      max_retry_passes: Optional[int] = None,
                                      search_source: str = "AMX Section") -> tk.Toplevel:
        win = tk.Toplevel(self.root)
        win.title("Automatic Search -- IFM Section")
        win.configure(bg="#1e1e1e")
        win.geometry("560x420")
        win.protocol("WM_DELETE_WINDOW", lambda: None)  # only closable via "Close" once finished/stopped

        # M3-137: stashed on the window itself (rather than only living
        # as function-scope locals back in _start_ifm_auto_search) so the
        # Resume button below -- which can fire long after this window
        # was first built, on a click, not a call stack -- can still get
        # at the same terms/sheets/settings this run started with.
        win.ifm_terms = terms
        win.ifm_sheet_indices = sheet_indices
        win.ifm_replace_existing = replace_existing
        win.ifm_max_retry_passes = max_retry_passes
        # M3-141: so _resume_ifm_auto_search (which continues THIS run,
        # potentially long after the dropdown could have been changed)
        # keeps searching -- and tagging results -- against the same
        # source the original run started with, not whatever the
        # dropdown happens to show at the moment Resume is clicked.
        win.ifm_search_source = search_source

        tk.Label(win, text=f"Searching {total} node name(s) one by one ...", bg="#1e1e1e",
                 fg="#ffffff", font=("Helvetica", 10, "bold")).pack(anchor="w", padx=10, pady=(10, 4))

        win.timer_var = tk.StringVar(value="Elapsed: 0:00")
        tk.Label(win, textvariable=win.timer_var, bg="#1e1e1e", fg="#a0a0a0",
                 font=("Helvetica", 8)).pack(anchor="w", padx=10, pady=(0, 4))

        # M3-137: lets the "Parallel browsers" count be lowered WHILE a
        # search is running -- e.g. you opened 13 and now the CPU/RAM hit
        # is more than you want -- without having to hit Stop and lose
        # progress. Only shown for a genuinely parallel run; with a
        # single browser there's nothing to reduce. This can only ever
        # go DOWN, never back up past whatever it's already been lowered
        # to -- see _wie_run_auto_search_pool's active_limit_getter
        # docstring for exactly why (a retired worker has already closed
        # its own browser and its thread has already exited; there's no
        # live thread left to hand more work back to). One extra note
        # worth knowing: if these browsers were pre-opened via the "Open
        # Browsers" button, the browser processes themselves stay alive
        # either way -- this only stops MORE work from being handed to
        # the ones above the new count, it doesn't close them. To
        # actually free that RAM, use "Close Browsers" after this run
        # ends. For browsers this run launched itself (no pre-warmed
        # pool), each one really does close as soon as it retires.
        if num_browsers > 1:
            browsers_row = tk.Frame(win, bg="#1e1e1e")
            browsers_row.pack(fill=tk.X, padx=10, pady=(0, 4))
            tk.Label(browsers_row, text="Active browsers:", bg="#1e1e1e", fg="#a0a0a0",
                     font=("Helvetica", 8)).pack(side=tk.LEFT)
            win.active_browsers_var = tk.StringVar(value=str(num_browsers))
            browsers_spin = tk.Spinbox(browsers_row, from_=1, to=num_browsers, width=4,
                                       textvariable=win.active_browsers_var,
                                       font=("Helvetica", 8), justify=tk.CENTER)
            browsers_spin.pack(side=tk.LEFT, padx=(6, 6))

            def _apply_active_browsers():
                try:
                    requested = int(win.active_browsers_var.get())
                except (ValueError, tk.TclError):
                    requested = self._ifm_auto_active_browsers_limit[0]
                current = self._ifm_auto_active_browsers_limit[0]
                # One-way valve -- clamp between 1 and whatever it's
                # already been lowered to, never back up past that even
                # if the spinbox itself still shows a higher ceiling.
                clamped = max(1, min(requested, current))
                win.active_browsers_var.set(str(clamped))
                if clamped == current:
                    return
                self._ifm_auto_active_browsers_limit[0] = clamped
                msg = (f"Active browsers reduced to {clamped} -- browser(s) above that count "
                       f"will finish their current search, then stop picking up new ones.")
                self._ifm_auto_log(win, msg)
                print(f"[IFM Auto Search] {msg}")
                self._ifm_auto_file_log(f"-- {msg} --")

            tk.Button(browsers_row, text="Apply", command=_apply_active_browsers,
                     bg="#0984e3", fg="#ffffff", relief=tk.FLAT, cursor="hand2",
                     font=("Helvetica", 8)).pack(side=tk.LEFT)
            tk.Label(browsers_row, text="(can only be lowered, not raised back up)",
                     bg="#1e1e1e", fg="#636e72", font=("Helvetica", 7)).pack(side=tk.LEFT, padx=(8, 0))
            win.active_browsers_spin = browsers_spin

        # M3-126: shows where the full .txt log for this run is being
        # written, with an "Open Log File" button next to it (enabled
        # immediately -- the file is created with a header before the
        # search loop starts, see _run_ifm_auto_search) so the user can
        # jump straight to it, or copy the path, without hunting for it
        # in the filesystem after the fact.
        if log_file_path:
            log_path_row = tk.Frame(win, bg="#1e1e1e")
            log_path_row.pack(fill=tk.X, padx=10, pady=(0, 4))
            tk.Label(log_path_row, text="Log file:", bg="#1e1e1e", fg="#a0a0a0",
                     font=("Helvetica", 8)).pack(side=tk.LEFT)
            log_path_entry = tk.Entry(log_path_row, font=("Consolas", 8), fg="#dcdcdc",
                                      bg="#111111", relief=tk.FLAT, insertbackground="#dcdcdc")
            log_path_entry.insert(0, log_file_path)
            log_path_entry.configure(state="readonly", readonlybackground="#111111")
            log_path_entry.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=(6, 6))
            open_log_btn = tk.Button(log_path_row, text="Open Log File",
                                     command=lambda: self._open_file_external(log_file_path),
                                     bg="#0984e3", fg="#ffffff", relief=tk.FLAT, cursor="hand2",
                                     font=("Helvetica", 8))
            open_log_btn.pack(side=tk.RIGHT)
            win.log_path_entry = log_path_entry

        prog = ttk.Progressbar(win, maximum=max(total, 1), value=0)
        prog.pack(fill=tk.X, padx=10, pady=(0, 8))

        log_box = tk.Text(win, height=16, bg="#111111", fg="#dcdcdc", font=("Consolas", 9), wrap="word")
        log_box.pack(fill=tk.BOTH, expand=True, padx=10, pady=(0, 8))
        log_box.configure(state=tk.DISABLED)

        btn_row = tk.Frame(win, bg="#1e1e1e")
        btn_row.pack(fill=tk.X, padx=10, pady=(0, 10))
        stop_btn = tk.Button(btn_row, text="Stop", command=lambda: self._ifm_auto_stop_event.set(),
                             bg="#e74c3c", fg="#ffffff", relief=tk.FLAT, cursor="hand2")
        stop_btn.pack(side=tk.LEFT)
        # M3-137: disabled until the run currently in progress ends (see
        # the `finally` block in _run_ifm_auto_search, which enables this
        # only when at least one node is still without an image --
        # whether that's because Stop was pressed or because every
        # configured retry pass genuinely came up short). Clicking it
        # starts a brand-new run scoped to ONLY the still-missing nodes,
        # merging its results back into the same positional list rather
        # than starting the whole thing over from node 1.
        resume_btn = tk.Button(btn_row, text="Resume", state=tk.DISABLED,
                               command=lambda: self._resume_ifm_auto_search(win),
                               bg="#27ae60", fg="#ffffff", relief=tk.FLAT, cursor="hand2")
        resume_btn.pack(side=tk.LEFT, padx=(6, 0))
        close_btn = tk.Button(btn_row, text="Close", state=tk.DISABLED, command=win.destroy,
                              bg="#636e72", fg="#ffffff", relief=tk.FLAT, cursor="hand2")
        close_btn.pack(side=tk.RIGHT)

        win.progress = prog
        win.log_box = log_box
        win.stop_btn = stop_btn
        win.resume_btn = resume_btn
        win.close_btn = close_btn
        return win

    # Cap on how many lines the on-screen log box keeps -- a 5k-10k node
    # run logs one (or more, with retries) line per node, and letting a
    # Tk Text widget grow to that many lines makes every subsequent
    # insert()/see() call progressively slower. Everything is still
    # printed to the console unbounded (see the print() calls alongside
    # every _ifm_auto_log call) -- this only trims what's shown in the
    # popup window itself.
    _IFM_AUTO_LOG_MAX_LINES = 500

    def _ifm_auto_log(self, win: tk.Toplevel, msg: str):
        def _do():
            try:
                if not win.winfo_exists():
                    return
                win.log_box.configure(state=tk.NORMAL)
                win.log_box.insert(tk.END, msg + "\n")
                overflow = int(float(win.log_box.index(tk.END))) - 1 - self._IFM_AUTO_LOG_MAX_LINES
                if overflow > 0:
                    win.log_box.delete("1.0", f"{overflow + 1}.0")
                win.log_box.see(tk.END)
                win.log_box.configure(state=tk.DISABLED)
            except tk.TclError:
                pass
        self.root.after(0, _do)

    # M3-119: how many extra passes a node whose search comes back empty
    # gets retried (against just that leftover subset, not the whole
    # mindmap, and only after every other node has already had its turn)
    # before it's finally left without an image is now the "Retry passes"
    # spinbox (see _ifm_get_max_retry_passes), not a fixed number -- this
    # is just the fallback used if that spinbox is ever unreadable. A
    # single dropped connection or a search engine hiccup on node #4,312
    # out of 8,000 used to permanently skip that one node forever with too
    # few retries; now the user can dial in as many extra chances as they
    # want before giving up on it.
    _IFM_AUTO_SEARCH_MAX_RETRY_PASSES = 10

    # M3-132: cycled through by _ifm_addressed_terms for each successive
    # blank node borrowing the same named ancestor's title, so a long
    # chain of them spreads across several fresh, independently-ranked
    # searches instead of one query mined ever deeper (see that method's
    # own docstring note for the full reasoning). Deliberately generic
    # and photographic -- no "illustration"/"icon"/"clipart"/"drawing"/
    # "cartoon"/"vector" wording, since those would bias results toward
    # the exact non-photo look this exists to avoid.
    _IFM_BORROW_QUERY_VARIANTS = [
        "", " photo", " picture", " close up", " isolated", " fresh",
        " high resolution", " macro", " on white background", " ripe",
        " single", " whole",
    ]

    def _ifm_auto_file_log(self, msg: str, timestamp: bool = True):
        """Thread-safe append to this run's .txt log file (see
        _run_ifm_auto_search / _start_ifm_auto_search). Every worker
        thread in the num_browsers > 1 pool path can call this
        concurrently (same as _wie_run_auto_search_pool's on_result
        firing from multiple threads at once), so writes go through
        self._ifm_auto_log_file_lock rather than assuming the OS's
        append-mode write is atomic across processes/threads on every
        platform. Silently prints a one-line warning (not a dialog --
        this must never itself crash or block a running search) and gives
        up on logging for the rest of the run if the file becomes
        unwritable (disk full, permissions changed mid-run, etc.)."""
        if not getattr(self, "_ifm_auto_log_file_path", None) or \
                getattr(self, "_ifm_auto_log_file_broken", False):
            return
        now = time.time()
        line = (f"[{time.strftime('%H:%M:%S', time.localtime(now))}."
               f"{int((now % 1) * 1000):03d}] {msg}\n") if timestamp else (msg + "\n")
        try:
            with self._ifm_auto_log_file_lock:
                with open(self._ifm_auto_log_file_path, "a", encoding="utf-8") as f:
                    f.write(line)
        except Exception as e:
            self._ifm_auto_log_file_broken = True
            print(f"[IFM Auto Search] WARNING: log file write failed ({e}) -- "
                 "continuing without a log file for the rest of this run.")

    def _run_ifm_auto_search(self, terms: List[str], win: tk.Toplevel, num_browsers: int = 1,
                             max_retry_passes: Optional[int] = None,
                             sheet_indices: Optional[List[int]] = None,
                             replace_existing: bool = False,
                             log_file_path: Optional[str] = None,
                             initial_positional: Optional[List[Optional[str]]] = None,
                             search_source: str = "AMX Section"):
        # M3-137: `initial_positional`, when supplied by _resume_ifm_auto_
        # search, seeds `positional` (below) with an EARLIER run's
        # results instead of starting from all-None. Every node that
        # already has a path in it is treated as already resolved --
        # left completely out of the main pass and never searched again
        # -- while everything still None goes through the normal main
        # pass + retry passes exactly as a fresh run would. This is what
        # lets Resume mean "keep going from where it left off" instead
        # of "start over and re-download everything, including nodes
        # that already succeeded."
        #
        # M3-141: `search_source` is the "Search node names from" value
        # this run was actually started under ("AMX Section" or "Text
        # Area (Condensed Data)"), captured once by the caller before
        # this method's own background thread starts. It's what the
        # `finally` block below now uses to stamp ifm_auto_search_
        # source_path correctly -- None for a Text Area run, no matter
        # what self.ifm_loaded_xmind_path happens to hold -- and what
        # on_result uses to tag each newly downloaded image in
        # ifm_auto_image_source, so a later dropdown switch can't cycle
        # this run's images into a build made under the other source.
        self._ifm_auto_log_file_path = log_file_path
        self._ifm_auto_log_file_lock = threading.Lock()
        self._ifm_auto_log_file_broken = False
        if max_retry_passes is None:
            max_retry_passes = self._IFM_AUTO_SEARCH_MAX_RETRY_PASSES
        # Same defaults as ImageSearchDialog's own (fmt_var="webp",
        # min_size_var="150") -- IFM's Automatic Search has no separate
        # format/size controls of its own, it just feeds the same pool
        # "Search Images" / "Load Images" do.
        fmt = "webp"
        min_size = 150
        total = len(terms)
        out_dir = tempfile.mkdtemp(prefix="xmind_ifm_autosearch_")
        _WIE_TEMP_DIRS.append(out_dir)
        self._structure_search_temp_dirs.append(out_dir)

        num_browsers = max(1, min(int(num_browsers or 1), total if total else 1))

        # M3-137: mutable one-item container (not a plain int) so the
        # popup window's "Active browsers" control can lower it live
        # while this method's own background thread and every pool
        # worker thread all read the same up-to-date value -- see
        # _wie_run_auto_search_pool's active_limit_getter and
        # _build_ifm_auto_search_window's Apply button below. Starts at
        # the full requested count; can only ever be lowered (see
        # active_limit_getter's own docstring for why raising it back up
        # isn't possible once a worker's already retired).
        self._ifm_auto_active_browsers_limit = [num_browsers]
        self._ifm_auto_active_browsers_original = num_browsers

        # M3-119: look this up ONCE per run (not per pass/batch) so the
        # "borrow from the pool" decision -- and the confirmation the user
        # actually sees -- is made and shown a single time up front, not
        # silently re-decided on every retry pass. See wie_get_prewarmed_
        # contexts for the ">= " matching rule and run_batch below for how
        # this gets threaded through to whichever of the sequential/
        # parallel paths this run uses.
        prewarmed_ctxs = (wie_get_prewarmed_contexts(num_browsers)
                          if getattr(self, "_ifm_browsers_prewarmed", False) else None)
        if prewarmed_ctxs:
            rig_desc = (f"{len(prewarmed_ctxs)} pre-opened Chromium instance(s), headless -- "
                       "no cold-launch wait")
        else:
            rig_desc = "Chromium, headless" if num_browsers == 1 else \
                f"{num_browsers} independent Chromium instances, headless, running in parallel"
        print(f"[IFM Auto Search] Starting automatic search for {total} node name(s) ({rig_desc}) ...")
        self._ifm_auto_log(win, f"Starting search for {total} node name(s) using {rig_desc}.")
        if log_file_path:
            self._ifm_auto_log(win, f"Log file: {log_file_path}")

        # M3-126: write the log file's header up front (before the search
        # loop starts) rather than only at the end, so a run that's still
        # in progress -- or one that crashes/hangs partway through instead
        # of reaching the `finally` block below -- still leaves behind a
        # file with at least the run's parameters and whatever per-node
        # lines made it out before things stopped.
        header = "\n".join([
            "=" * 78,
            "IFM Automatic Search -- run log",
            f"Started:            {time.strftime('%Y-%m-%d %H:%M:%S')}",
            f"Node names to find: {total}",
            f"Browser rig:        {rig_desc}",
            f"Image format:       {fmt}   Min size: {min_size}px",
            f"Max retry passes:   {max_retry_passes}",
            f"Sheets included:    {sheet_indices if sheet_indices else [0]}",
            f"Replace existing:   {replace_existing}",
            f"Search node source: {search_source}",
            f"Source .xmind:      "
            f"{self.ifm_loaded_xmind_path if search_source != 'Text Area (Condensed Data)' else '(none -- searched from the Text Area hierarchy)'}",
            f"Downloaded-image temp folder: {out_dir}",
            "=" * 78,
            "",
        ])
        self._ifm_auto_file_log(header, timestamp=False)

        # Elapsed-time / ETA tracking for the popup's timer line (see
        # _ifm_auto_tick_timer). _ifm_auto_progress_lock guards the two
        # counters below since on_result fires from worker threads when
        # num_browsers > 1.
        self._ifm_auto_start_time = time.time()
        self._ifm_auto_progress_lock = threading.Lock()
        self._ifm_auto_total_processed = 0
        self._ifm_auto_current_batch_remaining = total
        # M3-131: how many images THIS run has actually downloaded and
        # added to the pool so far -- separate from len(self.structure_
        # images), which also includes whatever was already sitting in
        # the pool before this run started (earlier runs, manually loaded/
        # searched images, ...). _update_structure_images_status() shows
        # both while this is not None, so the on-screen count can never
        # look like it's outpacing "Searching nxt/total" the way the
        # all-time pool total could. Reset to None in the `finally` below
        # once the run ends, so the label goes back to a plain pool total.
        self._ifm_auto_run_loaded_count = 0
        self.root.after(0, lambda: self._ifm_auto_tick_timer(win))

        # positional[i-1] holds the final downloaded path for target node i
        # (1-based, same order _ifm_dfs_targets walked the tree in), or
        # None if node i never found a usable image even after every retry
        # pass below. This -- not a flat "append on success" list -- is
        # what Preview/Export actually paste back in afterwards (see
        # inject_images_into_xmind_nodes' positional_image_paths): a
        # skipped node just leaves its own slot empty instead of vanishing
        # from the list and shifting every later node's image over by one,
        # which is what used to put the wrong image on the wrong node
        # whenever even a single search failed partway through a run.
        #
        # M3-137: seeded from initial_positional on a resumed run instead
        # of starting all-None -- see this method's own docstring note
        # above initial_positional's parameter for why.
        if initial_positional is not None and len(initial_positional) == total:
            positional: List[Optional[str]] = list(initial_positional)
        else:
            positional: List[Optional[str]] = [None] * total
        carried_over_count = sum(1 for p in positional if p)

        # Most-recent failure reason per node index, kept across the main
        # pass and every retry pass -- cleared if a later attempt for that
        # same node succeeds -- so the final log summary (see the
        # `finally` block below) can tell the user *why* each still-
        # unimaged node failed, not just that it did.
        last_errors: Dict[int, str] = {}

        # M3-127: three more pieces of run-wide bookkeeping for the
        # detailed summary in the `finally` block below --
        #   attempts_count[index]     -- how many total attempts (main +
        #                                every retry) node `index` took
        #                                before it stopped being retried
        #                                (whether it ended in success or
        #                                gave up for good).
        #   pass_resolved[index]      -- which pass ("main", "retry 1",
        #                                "retry 2", ...) finally found an
        #                                image for node `index`. Absent
        #                                entirely if it never did.
        #   all_failure_categories    -- running total, across every
        #                                attempt of every node in the
        #                                whole run (not just the final
        #                                still-failed set), of how many
        #                                fell into each _ifm_categorize_
        #                                search_error() bucket. This is
        #                                what actually answers "was this
        #                                mostly Google rate-limiting, or
        #                                mostly genuinely-empty results?"
        #                                -- last_errors alone can't, since
        #                                it only keeps the LATEST reason
        #                                per node and most nodes that
        #                                failed early went on to succeed.
        attempts_count: Dict[int, int] = {}
        pass_resolved: Dict[int, str] = {}
        all_failure_categories: Dict[str, int] = {}

        # O(1) dedup for structure_images instead of "path not in list",
        # which turns into an O(n^2) scan once a run has a few thousand
        # nodes worth of downloaded paths in it.
        existing_image_paths = set(self.structure_images)

        # M3-131: shared for the WHOLE run (main pass + every retry pass,
        # sequential path and pool path alike) so the same downloaded
        # image can never land on two different nodes -- previously
        # nothing enforced this at all for Automatic Search (only the
        # manual Search Images dialog had its own, separate seen_hashes),
        # so several nodes searching the identical term -- most commonly
        # a blank-titled node borrowing a named ancestor's title running
        # alongside that ancestor, or several such blank descendants all
        # borrowing the same name (see _ifm_addressed_terms) -- would
        # routinely all just get the same top result. hash_lock also
        # makes the check-and-record step atomic across threads when
        # num_browsers > 1, so two workers can't both grab the same
        # candidate in the same instant either.
        run_seen_hashes: set = set()
        run_hash_lock = threading.Lock()

        def run_batch(term_items: List[Tuple[int, str]], on_result, item_delay: float = 0.0,
                     stagger: float = min(1.5, 0.4 * num_browsers),
                     min_request_interval: float = 0.35):
            """Runs term_items = [(index, term), ...] through whichever of
            the sequential/parallel paths this search was started with,
            calling on_result(index, term, path_or_None, error_or_None)
            exactly once per item. Shared by the initial full pass and
            every retry pass over the leftover subset that didn't find an
            image yet.

            `item_delay` waits that many seconds before each item (in the
            sequential path) / before every request after a worker's
            first (in the parallel pool path, see _wie_run_auto_search_
            pool) -- retry passes pass a small, attempt-scaled delay here,
            and (M3-128, see below) the main pass now passes a small flat
            delay too, because a term that just failed with
            ERR_CONNECTION_CLOSED almost always means Google's rate-
            limiting the browser(s) for hammering it with back-to-back
            requests, not that the term has no results; firing the very
            next request immediately just fails the same way again. A
            short pause gives that limit a chance to clear, and is what
            actually distinguishes a real second attempt from re-asking
            the same blocked question instantly.

            `stagger` (parallel pool path only) spaces out each worker's
            very first request by worker_id * stagger seconds. M3-127
            added this after real logs showed every worker's first
            request of a run failing with ERR_CONNECTION_CLOSED /
            ERR_SOCKET_NOT_CONNECTED at the exact same timestamp --
            num_browsers Chromium instances all opening a fresh
            connection to google.com in the same instant reads as a
            burst and gets some of those connections reset.

            M3-128: a flat 0.3s wasn't actually enough -- a real run
            with 6 pre-opened browsers still saw 3 of the 6 (every
            *other* worker: 1, 3, 5) get ERR_CONNECTION_CLOSED on their
            first request, all resolved a whole retry pass later purely
            by virtue of that pass's item_delay giving Google's limiter
            time to clear. `stagger` now scales with num_browsers instead
            of staying flat (capped at 1.5s/worker so a large pool
            doesn't stack up a silly amount of upfront wait) -- more
            parallel browsers means more simultaneous fresh connections
            to spread out, so the gap between them needs to grow too,
            not stay fixed. The main pass also now passes its own
            item_delay (see the call below) instead of leaving it at
            0.0, so a worker's *second* and later requests aren't
            hammering back-to-back the instant its first one lands,
            either -- the same reasoning that already applied to every
            retry pass, just applied one pass earlier so fewer terms
            need a retry pass to begin with."""
            if num_browsers <= 1:
                ctx0 = prewarmed_ctxs[0] if prewarmed_ctxs else None
                remaining = list(term_items)
                for pos, (index, term) in enumerate(remaining):
                    if self._ifm_auto_stop_event.is_set():
                        for j_index, j_term in remaining[pos:]:
                            on_result(j_index, j_term, None, RuntimeError("stopped by user"))
                        return
                    if item_delay > 0 and pos > 0:
                        self._ifm_auto_stop_event.wait(item_delay)
                        if self._ifm_auto_stop_event.is_set():
                            for j_index, j_term in remaining[pos:]:
                                on_result(j_index, j_term, None, RuntimeError("stopped by user"))
                            return
                    searching_msg = f"[{index}/{total}] Searching \"{term}\" ..."
                    self._ifm_auto_log(win, searching_msg)
                    print(f"[IFM Auto Search] {searching_msg}")
                    self._ifm_auto_file_log(f"[{index}/{total}] Searching \"{term}\" ...")

                    def _console(m, index=index):
                        print(f"[IFM Auto Search] [{index}/{total}] {m}")
                        self._ifm_auto_file_log(f"    [{index}/{total}] {m}")

                    try:
                        t0 = time.time()
                        path = _wie_auto_search_download(term, out_dir, fmt, index, min_size=min_size,
                                                         log=_console, prewarmed_context=ctx0,
                                                         seen_hashes=run_seen_hashes,
                                                         hash_lock=run_hash_lock)
                        on_result(index, term, path, None, elapsed=time.time() - t0, worker_id=0)
                    except Exception as e:
                        on_result(index, term, None, e, elapsed=time.time() - t0, worker_id=0)
            else:
                # M3-119: reuse the pre-warmed pool (Open Browsers button)
                # computed once above as prewarmed_ctxs -- falls back to
                # _wie_run_auto_search_pool's own launch-and-close-per-run
                # behavior when it's None (not open, or open with fewer
                # entries than this run needs).
                def _pool_log(m):
                    print(f"[IFM Auto Search] {m}")
                    self._ifm_auto_file_log(f"    {m}")
                # M3-137: each retry pass is its own fresh call to
                # _wie_run_auto_search_pool -- a brand-new batch of worker
                # threads gets spun up every time, separate from whichever
                # threads the previous pass's workers were (those already
                # exited when their own batch finished). Without reading
                # the live limit again here, a reduction made during the
                # main pass would only hold for the main pass itself --
                # the very next retry pass would launch a fresh full-size
                # `num_browsers` batch right back at the original count,
                # undoing the reduction. Using the CURRENT limit as the
                # count for this new batch (while still passing
                # active_limit_getter so a further reduction mid-batch
                # keeps working too) makes a reduction stick for the rest
                # of the run, not just the one pass it was made during.
                current_num_browsers = max(1, min(
                    num_browsers, self._ifm_auto_active_browsers_limit[0]))
                _wie_run_auto_search_pool(
                    list(term_items), num_browsers=current_num_browsers, out_dir=out_dir, fmt=fmt,
                    min_size=min_size, timeout=25, stop_event=self._ifm_auto_stop_event,
                    on_result=on_result, log=_pool_log,
                    prewarmed_contexts=prewarmed_ctxs, stagger=stagger, item_delay=item_delay,
                    min_request_interval=min_request_interval,
                    seen_hashes=run_seen_hashes, hash_lock=run_hash_lock,
                    active_limit_getter=lambda: self._ifm_auto_active_browsers_limit[0])

        def make_dispatcher(batch_items: List[Tuple[int, str]], is_main: bool, label: str = "",
                            pass_name: str = "main"):
            """Builds the on_result callback for one batch (the initial
            pass, or one retry pass). Applies results to `positional` and
            self.structure_images immediately and thread-safely (so a
            later retry pass or the final Preview/Export always sees
            correct data no matter timing), and separately flushes the
            log/progress-bar updates to the dialog in the batch's own
            order -- not raw node-index order, since a retry batch's
            indices are a scattered subset of 1..total -- so the window
            reads top-to-bottom even with several browsers racing.

            `pass_name` (M3-127) is the plain "main" / "retry N" tag used
            for the pass_resolved bookkeeping below -- kept separate from
            `label` (which has its own on-screen/log formatting, trailing
            spaces and all) so the run-summary breakdown can group by it
            cleanly.

            M3-161 fix (log window would go quiet for a minute-plus at a
            time even though downloads were still landing on disk): this
            used to buffer every result in `pending` and only ever log the
            NEXT UN-FLUSHED index in strict order (flush_ready), so the
            window "read top to bottom" -- but that means one slow
            straggler (a single candidate whose direct download hangs on
            a slow-draining response for 60-90s, well past the point the
            other browsers in the pool have already finished several more
            items each) silently held up the on-screen/log-file lines for
            every already-finished LATER item too, until the straggler
            itself finally resolved -- at which point they'd all dump out
            at once. The run was never actually stuck; only its own
            display was. Fixed by logging each result the moment it
            arrives instead of waiting for its turn -- still labeled with
            its own true "[N/total]", just no longer gated on every
            earlier index having reported first. The progress bar/status
            line now advance off a monotonically-increasing high-water
            mark (the largest index seen so far) rather than the literal
            index of whichever result just came in, so out-of-order
            arrivals can't make it visibly jump backward, and a resumed
            run (whose first items can start well past index 1) still
            starts the bar at the right position."""
            total_batch = len(batch_items)
            handled: set = set()
            lock = threading.Lock()
            items_by_index = dict(batch_items)
            high_water = [0]

            def on_result(index, term, path, err, elapsed=None, worker_id=None):
                with lock:
                    if index in handled:
                        return
                    handled.add(index)
                    attempts_count[index] = attempts_count.get(index, 0) + 1
                    if path:
                        positional[index - 1] = path
                        last_errors.pop(index, None)
                        pass_resolved[index] = pass_name
                        if path not in existing_image_paths:
                            existing_image_paths.add(path)
                            self.structure_images.append(path)
                            # M3-141: tag with the source this run was
                            # actually searching against, so a later
                            # dropdown switch's cycling fallback (see
                            # _ifm_pool_images_for_source) can't pick this
                            # image up for the OTHER source's build.
                            self.ifm_auto_image_source[path] = search_source
                    elif err is not None:
                        last_errors[index] = str(err)
                        category = _ifm_categorize_search_error(str(err))
                        all_failure_categories[category] = all_failure_categories.get(category, 0) + 1
                    remaining_in_batch = total_batch - len(handled)
                    if index > high_water[0]:
                        high_water[0] = index
                    display_index = high_water[0]
                with self._ifm_auto_progress_lock:
                    self._ifm_auto_total_processed += 1
                    self._ifm_auto_current_batch_remaining = remaining_in_batch
                    if path:
                        self._ifm_auto_run_loaded_count += 1

                def _flush(index=index, path=path, err=err, elapsed=elapsed,
                          worker_id=worker_id, display_index=display_index):
                    term_for_index = items_by_index.get(index, "?")
                    tag = f" (browser {worker_id})" if worker_id else ""
                    timing = f" [{elapsed:.2f}s]" if elapsed is not None else ""
                    if err is not None:
                        self._ifm_auto_log(win, f"{label}[{index}/{total}] Skipped -- {err}")
                        print(f"[IFM Auto Search] {label}[{index}/{total}] Skipped -- {err}")
                        self._ifm_auto_file_log(
                            f"{label}[{index}/{total}] FAILED  \"{term_for_index}\"{tag}{timing} "
                            f"-- {err}")
                    elif path:
                        self._ifm_auto_log(win, f"{label}[{index}/{total}] Saved {os.path.basename(path)}")
                        print(f"[IFM Auto Search] {label}[{index}/{total}] Found it -- downloaded "
                              f"{os.path.basename(path)}")
                        self._ifm_auto_file_log(
                            f"{label}[{index}/{total}] SUCCESS \"{term_for_index}\"{tag}{timing} "
                            f"-- saved {os.path.basename(path)}")
                        self._update_structure_images_status()
                    if is_main:
                        try:
                            if win.winfo_exists():
                                win.progress["value"] = display_index
                        except tk.TclError:
                            pass
                        nxt = min(display_index + 1, total)
                        self.ifm_auto_status_var.set(
                            f"Searching {nxt}/{total} ..." if display_index < total else "Finishing up ...")

                self.root.after(0, _flush)

            return on_result

        try:
            # ---- Pass 1: every node, in order ----
            # M3-128: item_delay=0.4 here (previously left at run_batch's
            # 0.0 default) so a worker's second-and-later requests get the
            # same small breathing room retry passes already gave theirs --
            # see run_batch's docstring above for why the main pass used to
            # skip this and why that turned out not to be enough on its own.
            #
            # M3-133 fix (retry passes silently never running at all):
            # every per-node failure inside run_batch already gets caught
            # and funneled through on_result (see the sequential loop and
            # the pool worker() above) -- but the call to run_batch itself
            # had no guard at all. Anything raised above the per-item level
            # (a worker/browser-pool thread failing before its own
            # try/except even starts, an unexpected error inside
            # _wie_run_auto_search_pool itself outside its per-item loop,
            # etc.) used to propagate straight out of this `try`, skipping
            # over the ENTIRE `for attempt in range(...)` retry loop below
            # and landing directly in `finally` -- which still prints a
            # normal-looking "Done -- X/Y downloaded" summary, so the run
            # silently looked complete after only the main pass, with no
            # error shown anywhere the user could see it (this method runs
            # on a daemon background thread with no exception handler of
            # its own, so the traceback only ever reached stderr --
            # invisible in a windowed/frozen build). Catching it here means
            # such a failure now gets logged loudly (on-screen, stdout, and
            # the run-log file) as its own explicit reason the main pass
            # came up short, AND leaves `positional` exactly as it was
            # (whatever succeeded before the failure keeps its image;
            # everything else stays None) so the retry loop immediately
            # below still runs against it instead of being skipped
            # entirely.
            # M3-137: on a resumed run, main_items only covers whatever
            # `positional` doesn't already have a path for -- a node
            # that's already resolved (from the earlier run this is
            # resuming) is skipped entirely, never re-searched, and never
            # even shows up in the "Searching ..." log. On a fresh run
            # (initial_positional was None) every slot starts empty so
            # this is just every node, same as before.
            main_items = [(i, t) for i, t in enumerate(terms, start=1) if positional[i - 1] is None]
            if carried_over_count:
                carry_msg = (f"Resuming -- {carried_over_count}/{total} node(s) already have an "
                             f"image from the earlier run and won't be re-searched.")
                self._ifm_auto_log(win, carry_msg)
                print(f"[IFM Auto Search] {carry_msg}")
                self._ifm_auto_file_log(f"-- {carry_msg} --")
            try:
                run_batch(main_items, make_dispatcher(main_items, is_main=True), item_delay=0.4)
            except Exception as e:
                main_pass_err_msg = (
                    f"Main pass hit an unexpected error and stopped early ({e}) -- "
                    f"whatever wasn't found yet will still go through the normal "
                    f"retry passes below instead of the run just quietly ending here.")
                self._ifm_auto_log(win, main_pass_err_msg)
                print(f"[IFM Auto Search] {main_pass_err_msg}")
                self._ifm_auto_file_log(f"-- {main_pass_err_msg} --")
                self.root.after(0, lambda m=main_pass_err_msg: self.ifm_auto_status_var.set(m))

            # ---- Retry passes: only nodes that never found an image, and
            # only if the user didn't ask to stop -- a search that failed
            # because of a timeout, a transient network hiccup, or nothing
            # usable turning up on that attempt is worth trying again;
            # one that "failed" because the user hit Stop is not. ----
            for attempt in range(1, max_retry_passes + 1):
                if self._ifm_auto_stop_event.is_set():
                    break
                retry_indices = [i for i in range(1, total + 1) if positional[i - 1] is None]
                if not retry_indices:
                    break
                # M3-130 used to add a "wait a bit longer, then retry the
                # blocked ones" cooldown here, and then M3-130's own
                # follow-up added a mass-block heuristic on top of it:
                # if >=50% of a batch's failures looked like a Google
                # block page, the ENTIRE retry loop aborted right then,
                # before ever making another request -- the reasoning
                # being that grinding through more passes at an
                # already-flagged IP just prolongs the block rather than
                # waiting it out.
                #
                # M3-134 fix (retries not actually running the configured
                # number of passes): a real run showed this abort firing
                # on attempt 1 itself -- 33/34 failed nodes were
                # categorized as blocked right after the main pass, so
                # the 50% threshold tripped immediately and zero retry
                # attempts were ever made, no matter what the "Retry
                # passes" spinbox said. That leaves the spinbox's value
                # meaningless whenever a run gets hit hard by blocks,
                # which is exactly the situation retries exist for.
                # Removed the abort entirely -- the "Retry passes" count
                # the user sets is now authoritative: every configured
                # pass runs regardless of how many looked like Google
                # blocks last time. The cooldown-before-retrying-blocked-
                # nodes behavior right below is kept, since spacing
                # requests out before hitting an already-rate-limited
                # connection again is still a reasonable, purely additive
                # precaution -- it delays a retry pass, it never skips one.
                blocked_now = [i for i in retry_indices
                              if _ifm_categorize_search_error(last_errors.get(i, "")) ==
                              "blocked by Google (verification/CAPTCHA page)"]
                if blocked_now and attempt > 1:
                    cooldown = min(60.0, 15.0 * attempt)
                    cooldown_msg = (f"{len(blocked_now)} node(s) were blocked by Google last "
                                    f"attempt -- waiting {cooldown:.0f}s before retrying them ...")
                    self._ifm_auto_log(win, cooldown_msg)
                    print(f"[IFM Auto Search] {cooldown_msg}")
                    self._ifm_auto_file_log(f"-- {cooldown_msg} --")
                    self.root.after(0, lambda m=cooldown_msg: self.ifm_auto_status_var.set(m))
                    if self._ifm_auto_stop_event.wait(cooldown):
                        break
                retry_items = [(i, terms[i - 1]) for i in retry_indices]
                retry_msg = (f"Retrying {len(retry_items)} node(s) that didn't find an image yet "
                             f"(attempt {attempt}/{max_retry_passes}) ...")
                self._ifm_auto_log(win, retry_msg)
                print(f"[IFM Auto Search] {retry_msg}")
                self._ifm_auto_file_log(f"-- {retry_msg} --")
                self.root.after(0, lambda m=retry_msg: self.ifm_auto_status_var.set(m))
                with self._ifm_auto_progress_lock:
                    self._ifm_auto_current_batch_remaining = len(retry_items)
                # Backs off a little further with each successive attempt
                # (2s, 4s, 6s, ... capped at 10s) since a term still
                # failing after a few retries is more likely stuck behind
                # rate-limiting than a one-off hiccup.
                retry_delay = min(10.0, 2.0 * attempt)
                # M3-129: the shared cross-browser floor backs off right
                # alongside item_delay -- a node still failing after a few
                # retries is more likely sitting behind Google's rate
                # limit than genuinely short on results, so later passes
                # keep the whole pool's combined request rate lower too,
                # not just this one item's own per-worker spacing.
                retry_min_interval = min(2.0, 0.35 + 0.25 * attempt)
                run_batch(retry_items, make_dispatcher(
                    retry_items, is_main=False, label=f"retry {attempt}/"
                    f"{max_retry_passes} ", pass_name=f"retry {attempt}"), item_delay=retry_delay,
                    min_request_interval=retry_min_interval)
        finally:
            self._ifm_auto_search_running = False
            self._ifm_auto_run_loaded_count = None
            self.root.after(0, self._update_structure_images_status)
            saved = sum(1 for p in positional if p)
            # This positional mapping -- not the plain structure_images
            # pool -- is what Preview/Export paste back in, so a skipped
            # node stays skipped instead of quietly borrowing whatever
            # image ended up next in the flat pool. See
            # inject_images_into_xmind_nodes' positional_image_paths and
            # _ifm_get_positional_images_if_valid.
            self.ifm_auto_search_positional_images = positional
            # M3-141: stamped from the run's ACTUAL search source, not
            # blindly from self.ifm_loaded_xmind_path -- a Text Area run
            # must record None here even if an .xmind file also happens
            # to be loaded in the AMX Section, or _ifm_get_positional_
            # images_for_text_if_valid wrongly treats this mapping as
            # belonging to that unrelated file and discards it (see this
            # method's docstring and _ifm_get_positional_images_for_
            # text_if_valid's own docstring for why None is what marks a
            # Text Area mapping as such).
            self.ifm_auto_search_source_path = (
                None if search_source == "Text Area (Condensed Data)" else self.ifm_loaded_xmind_path)
            self.ifm_auto_search_sheet_indices = list(sheet_indices) if sheet_indices else [0]
            self.ifm_auto_search_replace_existing = replace_existing
            # M3-137: kept on the window itself too (not just on self.,
            # which the NEXT unrelated run would overwrite) so Resume can
            # always find exactly the positional array and browser count
            # this specific window's own run last left off with, even if
            # some other run happened in between.
            win.ifm_last_positional = list(positional)
            win.ifm_last_num_browsers = self._ifm_auto_active_browsers_limit[0]
            done_msg = f"Done -- {saved}/{total} image(s) downloaded and added to IFM's image pool."
            if saved < total:
                done_msg += f" {total - saved} node(s) never found a usable image and will be left unimaged."
            self._ifm_auto_log(win, done_msg)
            print(f"[IFM Auto Search] {done_msg}")
            if log_file_path:
                self._ifm_auto_log(win, f"Full log saved to: {log_file_path}")
            self.root.after(0, lambda: self._ifm_spinner_stop(
                f"Done -- {saved}/{total} downloaded."))
            total_elapsed = time.time() - self._ifm_auto_start_time
            self.root.after(0, lambda: win.timer_var.set(
                f"Finished in {self._ifm_fmt_duration(total_elapsed)}") if win.winfo_exists() else None)

            # M3-126/M3-127: closing summary block -- top-level counts, a
            # "resolved by pass" breakdown (how many nodes needed 0 vs 1
            # vs 2+ retries -- the real signal for whether retries are
            # pulling their weight or whether the underlying success rate
            # itself is the problem), a failure-category breakdown across
            # EVERY attempt of the whole run (not just the final still-
            # failed set -- see all_failure_categories' own comment above
            # for why last_errors alone can't answer "was this mostly
            # rate-limiting?"), and a "Failed node names" section for
            # whatever's still unimaged at the very end. Stopped-by-user
            # runs get a clear note instead of being reported the same as
            # a genuine failure.
            failed_indices = [i for i in range(1, total + 1) if positional[i - 1] is None]
            stopped_early = self._ifm_auto_stop_event.is_set()
            total_attempts = sum(attempts_count.values())
            total_failed_attempts = sum(all_failure_categories.values())
            resolved_counts: Dict[str, int] = {}
            for v in pass_resolved.values():
                resolved_counts[v] = resolved_counts.get(v, 0) + 1
            summary_lines = [
                "",
                "-" * 78,
                f"Finished:  {time.strftime('%Y-%m-%d %H:%M:%S')}  "
                f"(elapsed {self._ifm_fmt_duration(total_elapsed)})",
                f"Stopped by user: {stopped_early}",
                f"Succeeded: {saved}/{total}",
                f"Failed:    {len(failed_indices)}/{total}",
                f"Total search attempts made (main pass + every retry): {total_attempts}",
                f"Total failed attempts (includes ones later fixed by a retry): "
                f"{total_failed_attempts}",
            ]
            if carried_over_count:
                summary_lines.insert(4, f"Carried over from earlier run (not re-searched): "
                                        f"{carried_over_count}/{total}")
            if resolved_counts:
                summary_lines.append("")
                summary_lines.append("Resolved on:")
                summary_lines.append(f"  main pass:  {resolved_counts.get('main', 0)}")
                for attempt_n in range(1, max_retry_passes + 1):
                    key = f"retry {attempt_n}"
                    if key in resolved_counts:
                        summary_lines.append(f"  {key}:    {resolved_counts[key]}")
            if all_failure_categories:
                summary_lines.append("")
                summary_lines.append("Failure categories (every attempt, whole run -- includes "
                                     "ones later fixed by a retry):")
                for cat, cnt in sorted(all_failure_categories.items(), key=lambda kv: -kv[1]):
                    summary_lines.append(f"  {cat}: {cnt}")
            if failed_indices:
                summary_lines.append("")
                summary_lines.append("Failed node names (still unimaged at the end of this run):")
                for i in failed_indices:
                    reason = last_errors.get(i, "stopped by user" if stopped_early else "unknown reason")
                    attempts_made = attempts_count.get(i, 0)
                    summary_lines.append(
                        f"  [{i}/{total}] \"{terms[i - 1]}\" -- {attempts_made} attempt(s) -- {reason}")
            summary_lines.append("-" * 78)
            self._ifm_auto_file_log("\n".join(summary_lines), timestamp=False)

            def _finish():
                try:
                    if win.winfo_exists():
                        win.stop_btn.config(state=tk.DISABLED)
                        win.close_btn.config(state=tk.NORMAL)
                        # M3-137: Resume only makes sense when something's
                        # actually still missing -- a fully successful run
                        # (or one resumed all the way to completion) has
                        # nothing left for it to do.
                        if failed_indices:
                            win.resume_btn.config(state=tk.NORMAL)
                        else:
                            win.resume_btn.config(state=tk.DISABLED)
                        win.protocol("WM_DELETE_WINDOW", win.destroy)
                except tk.TclError:
                    pass
                # Safe to let the Open/Close Browsers button be used again
                # now that this run (including every retry pass) is done --
                # see the matching .config(state=tk.DISABLED) in
                # _start_ifm_auto_search.
                try:
                    self.ifm_prewarm_btn.config(state=tk.NORMAL)
                except tk.TclError:
                    pass
            self.root.after(0, _finish)

    def _resume_ifm_auto_search(self, win: tk.Toplevel):
        """M3-137: handler for the popup window's "Resume" button (only
        ever enabled once a run has ended -- Stopped or naturally out of
        retries -- with at least one node still unimaged; see _finish()
        inside _run_ifm_auto_search). Starts a brand-new search scoped to
        ONLY those still-missing nodes, using the exact same terms/
        sheets/settings this window's original run used (stashed on
        `win` itself back in _build_ifm_auto_search_window), and feeds
        the previous run's own results in as initial_positional so they
        get merged into the same positional array rather than being
        thrown away and re-downloaded. Reuses this same window rather
        than opening a new one, so the on-screen log/timer/log-file link
        all carry on in the one place instead of scattering across
        several popups for what the user thinks of as one ongoing job."""
        if getattr(self, "_ifm_auto_search_running", False):
            messagebox.showinfo("Already Running", "An automatic search is already in progress.")
            return
        previous_positional = getattr(win, "ifm_last_positional", None)
        terms = getattr(win, "ifm_terms", None)
        if not terms or previous_positional is None or len(previous_positional) != len(terms):
            messagebox.showerror("Can't Resume",
                                 "This window's run details are no longer available -- start a "
                                 "new Automatic Search instead.")
            return
        missing = sum(1 for p in previous_positional if not p)
        if missing == 0:
            messagebox.showinfo("Nothing To Resume", "Every node already has an image.")
            try:
                win.resume_btn.config(state=tk.DISABLED)
            except tk.TclError:
                pass
            return
        num_browsers = max(1, int(getattr(win, "ifm_last_num_browsers", 1) or 1))
        max_retry_passes = getattr(win, "ifm_max_retry_passes", None)
        sheet_indices = getattr(win, "ifm_sheet_indices", None)
        replace_existing = getattr(win, "ifm_replace_existing", False)
        # M3-141: reuse the ORIGINAL run's source (stashed on the window
        # back in _build_ifm_auto_search_window), not whatever the
        # dropdown currently shows -- Resume continues the same run, so
        # its results must keep being tagged the same way the run they're
        # extending already was.
        search_source = getattr(win, "ifm_search_source", "AMX Section")

        self._ifm_auto_stop_event = threading.Event()
        self._ifm_auto_search_running = True
        self.ifm_prewarm_btn.config(state=tk.DISABLED)

        try:
            if win.winfo_exists():
                win.stop_btn.config(state=tk.NORMAL)
                win.resume_btn.config(state=tk.DISABLED)
                win.close_btn.config(state=tk.DISABLED)
                win.protocol("WM_DELETE_WINDOW", lambda: None)
                win.progress["value"] = len(terms) - missing
                # M3-137: the "Active browsers" spinbox's own ceiling was
                # last set to wherever the previous run's live limit
                # ended up -- a fresh run here gets a brand-new pool of
                # threads, so it's allowed to go back up to the count
                # this resume is starting with (still one-way FROM
                # THERE, same as any other run -- see _wie_run_auto_
                # search_pool's active_limit_getter docstring).
                if hasattr(win, "active_browsers_spin"):
                    win.active_browsers_var.set(str(num_browsers))
                    win.active_browsers_spin.config(to=num_browsers)
        except tk.TclError:
            pass

        resume_msg = f"Resuming -- {missing}/{len(terms)} node(s) still need an image."
        self._ifm_auto_log(win, resume_msg)
        print(f"[IFM Auto Search] {resume_msg}")

        log_dir = os.path.join(os.path.expanduser("~"), ".webpage_image_extractor",
                               "ifm_auto_search_logs")
        try:
            os.makedirs(log_dir, exist_ok=True)
        except Exception:
            log_dir = tempfile.gettempdir()
        log_file_path = os.path.join(
            log_dir, f"ifm_auto_search_{time.strftime('%Y%m%d_%H%M%S')}_resumed.txt")
        if hasattr(win, "log_path_entry"):
            try:
                win.log_path_entry.configure(state="normal")
                win.log_path_entry.delete(0, tk.END)
                win.log_path_entry.insert(0, log_file_path)
                win.log_path_entry.configure(state="readonly")
            except tk.TclError:
                pass

        threading.Thread(target=self._run_ifm_auto_search,
                         args=(terms, win, num_browsers, max_retry_passes, sheet_indices,
                               replace_existing, log_file_path),
                         kwargs={"initial_positional": previous_positional,
                                 "search_source": search_source},
                         daemon=True).start()

    # ── IFM's own AMX Section (separate from the F-Node AMX Section) ──

    # NOTE: like _refresh_amx_level_counts/_refresh_ifm_level_counts above,
    # IFM_BG/IFM_FG/IFM_SELECT/IFM_MUTED are local variables inside the
    # panel-building method and not visible here -- their literal values
    # (same ones defined there) are used directly instead of the names.
    def _rebuild_ifm_sheet_checklist(self, sheets: List[str]):
        """Rebuilds the per-sheet checklist in IFM's AMX Section for
        whatever .xmind file is currently loaded there -- every sheet
        starts checked (included) for both output and search. Called by
        _load_ifm_xmind on a fresh load, and by _clear_ifm_xmind with
        sheets=[] when the file's cleared. See _ifm_included_sheet_indices
        (search) / _ifm_included_output_sheet_indices (output) for how the
        checked state gets read back."""
        IFM_BG, IFM_FG, IFM_MUTED, IFM_SELECT = "#0d2b4e", "#ffffff", "#9fc4e8", "#3498db"
        for w in self.ifm_sheets_frame.winfo_children():
            w.destroy()
        self.ifm_loaded_xmind_sheets = list(sheets)
        self.ifm_sheet_output_vars = []
        self.ifm_sheet_include_vars = []
        self.ifm_sheet_search_checks = []
        if not sheets:
            tk.Label(self.ifm_sheets_frame, text="(load a file above)",
                     bg=IFM_BG, fg=IFM_MUTED, font=("Helvetica", 8, "italic")).pack(anchor="w")
            return
        # A single-sheet file has nothing to actually drop from the output
        # (that would just produce an empty file), so its "Include" box
        # stays permanently checked/disabled -- same as the old one-box
        # behavior. Its "Search" box, though, is still a real choice (skip
        # searching your one sheet and paste from the manual pool instead),
        # so it stays interactive even here.
        only_one = len(sheets) == 1
        for i, name in enumerate(sheets):
            row = tk.Frame(self.ifm_sheets_frame, bg=IFM_BG)
            row.pack(fill=tk.X, anchor="w")
            out_var = tk.BooleanVar(value=True)
            search_var = tk.BooleanVar(value=True)
            self.ifm_sheet_output_vars.append(out_var)
            self.ifm_sheet_include_vars.append(search_var)
            out_cb = tk.Checkbutton(row, text="\U0001F4C4", variable=out_var,
                           state=(tk.DISABLED if only_one else tk.NORMAL),
                           bg=IFM_BG, fg=IFM_FG, activebackground=IFM_BG,
                           selectcolor=IFM_SELECT, font=("Helvetica", 8))
            out_cb.pack(side=tk.LEFT)
            search_cb = tk.Checkbutton(row, text="\U0001F50D", variable=search_var,
                           command=self._refresh_ifm_level_counts,
                           bg=IFM_BG, fg=IFM_FG, activebackground=IFM_BG,
                           selectcolor=IFM_SELECT, font=("Helvetica", 8))
            search_cb.pack(side=tk.LEFT)
            self.ifm_sheet_search_checks.append(search_cb)
            tk.Label(row, text=name, bg=IFM_BG, fg=IFM_FG, font=("Helvetica", 8),
                     wraplength=210, justify=tk.LEFT).pack(side=tk.LEFT, anchor="w")
            out_var.trace_add("write", lambda *_a, i=i: self._on_ifm_sheet_output_toggle(i))

    def _on_ifm_sheet_output_toggle(self, i: int):
        """A sheet unchecked for "Include in output" can't be searched
        either -- its Search box is force-unchecked and disabled the
        moment Include is unchecked, and re-enabled (re-checked) the
        moment Include is re-checked, since there'd be nothing for a
        search result to land in on a sheet that's about to be dropped
        from the file entirely."""
        if i >= len(self.ifm_sheet_output_vars):
            return
        included = self.ifm_sheet_output_vars[i].get()
        search_var = self.ifm_sheet_include_vars[i]
        search_cb = self.ifm_sheet_search_checks[i]
        if not included:
            search_var.set(False)
            search_cb.config(state=tk.DISABLED)
        else:
            search_cb.config(state=tk.NORMAL)
            search_var.set(True)
        self._refresh_ifm_level_counts()

    def _ifm_included_sheet_indices(self) -> List[int]:
        """Reads the "Search for images" checkboxes back into a list of
        sheet indices -- the sheets Automatic Search reads node names from
        and Preview/Export paste images into. A sheet unchecked for
        "Include in output" is excluded here too even if its Search box is
        somehow still checked (belt-and-braces on top of
        _on_ifm_sheet_output_toggle already enforcing this in the UI).
        Falls back to the first output-included sheet if every box somehow
        ended up unchecked, since searching/counting zero sheets isn't a
        useful state for anything that calls this -- never falls back to a
        sheet that's excluded from the output, since a search result would
        have nowhere to land."""
        output_included = set(self._ifm_included_output_sheet_indices())
        included = [i for i, v in enumerate(self.ifm_sheet_include_vars)
                    if v.get() and i in output_included]
        if included:
            return included
        first_output = self._ifm_included_output_sheet_indices()
        return [first_output[0]] if first_output else [0]

    def _ifm_included_output_sheet_indices(self) -> List[int]:
        """Reads the "Include in output" checkboxes back into a list of
        sheet indices, in original file order -- the sheets that actually
        end up in the previewed/exported .xmind file (see
        _xmind_filter_sheets). Falls back to [0] the same belt-and-braces
        way as above, since a file with zero sheets isn't something
        Preview/Export can produce."""
        included = [i for i, v in enumerate(self.ifm_sheet_output_vars) if v.get()]
        return included or [0]

    # ── IFM's own "Text Area Sheets" checklist (M3-145) ──────────────
    # Mirrors ifm_sheets_frame above, but for the multi-sheet hierarchy
    # EDITOR's own sheets (self.sheets -- the "+"/tab strip above the
    # editor) rather than a loaded .xmind file's real sheets. Only
    # shown while "Search node names from" is set to "Text Area
    # (Condensed Data)" -- see _update_ifm_text_sheets_visibility.
    def _rebuild_ifm_text_sheet_checklist(self, sheets: List[str]):
        """Rebuilds the checklist. M3-146: now carries the SAME two
        independent checkboxes as the AMX Section's own "Sheets to
        search" checklist (_rebuild_ifm_sheet_checklist) instead of one
        combined box -- a sheet's own file-icon "Include in output" box
        (ifm_text_sheet_output_vars) decides whether it lands in the
        freshly-built .xmind at all, and its magnifying-glass "Search
        for images" box (ifm_text_sheet_vars) decides whether Automatic
        Search reads its node names / Preview-Export pastes images into
        it. Unchecking Include force-unchecks and disables that row's
        Search box, same as _on_ifm_sheet_output_toggle does for the AMX
        checklist -- there'd be nothing for a search result to land in
        on a sheet about to be dropped from the output entirely. A
        single-sheet editor has nothing to actually drop (that would
        just build an empty file), so its Include box stays permanently
        checked/disabled the same way the AMX checklist's does, while
        its Search box stays interactive. See
        _ifm_included_text_output_sheet_indices (output) /
        _ifm_included_text_sheet_indices (search) for how the checked
        state gets read back.

        Each row also carries the SAME right-click-to-delete
        (_on_sheet_tab_right_click) and click-and-hold-to-drag-reorder
        (_on_ifm_text_sheet_row_press/_motion/_release -> _reorder_
        sheet) gestures as the editor's own sheet tab strip above the
        main text box -- these operate on the real self.sheets list,
        not a separate copy, so deleting/reordering a sheet from here
        is exactly the same action as doing it from the tab strip, and
        _on_sheets_changed keeps both views in sync afterward."""
        IFM_BG, IFM_FG, IFM_MUTED, IFM_SELECT = "#0d2b4e", "#ffffff", "#9fc4e8", "#3498db"
        for w in self.ifm_text_sheets_frame.winfo_children():
            w.destroy()
        self._ifm_text_sheet_names_at_last_build = list(sheets)
        self.ifm_text_sheet_vars = []
        self.ifm_text_sheet_output_vars = []
        self.ifm_text_sheet_search_checks = []
        if not sheets:
            tk.Label(self.ifm_text_sheets_frame, text="(no sheets)",
                     bg=IFM_BG, fg=IFM_MUTED, font=("Helvetica", 8, "italic")).pack(anchor="w")
            return
        only_one = len(sheets) == 1
        for i, name in enumerate(sheets):
            row = tk.Frame(self.ifm_text_sheets_frame, bg=IFM_BG)
            row.pack(fill=tk.X, anchor="w")
            row._ifm_text_sheet_idx = i
            out_var = tk.BooleanVar(value=True)
            var = tk.BooleanVar(value=True)
            self.ifm_text_sheet_output_vars.append(out_var)
            self.ifm_text_sheet_vars.append(var)
            out_cb = tk.Checkbutton(row, text="\U0001F4C4", variable=out_var,
                           state=(tk.DISABLED if only_one else tk.NORMAL),
                           bg=IFM_BG, fg=IFM_FG, activebackground=IFM_BG,
                           selectcolor=IFM_SELECT, font=("Helvetica", 8))
            out_cb.pack(side=tk.LEFT)
            search_cb = tk.Checkbutton(row, text="\U0001F50D", variable=var,
                                bg=IFM_BG, fg=IFM_FG, activebackground=IFM_BG,
                                selectcolor=IFM_SELECT, font=("Helvetica", 8))
            search_cb.pack(side=tk.LEFT)
            self.ifm_text_sheet_search_checks.append(search_cb)
            lbl = tk.Label(row, text=self._sheet_tab_display_text(name), bg=IFM_BG, fg=IFM_FG,
                          font=("Helvetica", 8), wraplength=200, justify=tk.LEFT, anchor="w",
                          cursor="hand2")
            lbl.pack(side=tk.LEFT, fill=tk.X, expand=True)
            row._ifm_text_sheet_lbl = lbl
            out_var.trace_add("write", lambda *_a, i=i: self._on_ifm_text_sheet_output_toggle(i))
            # Right-click anywhere on the row -- reuses the editor tab
            # strip's own "Delete sheet" menu/guard (refuses on the last
            # remaining sheet).
            row.bind("<Button-3>", lambda e, i=i: self._on_sheet_tab_right_click(e, i))
            lbl.bind("<Button-3>", lambda e, i=i: self._on_sheet_tab_right_click(e, i))
            # Click-and-hold-then-move on the row's label drags it to a
            # new position (Y-based, since these rows stack vertically --
            # the tab strip's own gesture is X-based). A plain click
            # (no meaningful movement) does nothing extra here; checking/
            # unchecking is via the checkboxes, not the row.
            lbl.bind("<Button-1>", lambda e, i=i: self._on_ifm_text_sheet_row_press(e, i))
            lbl.bind("<B1-Motion>", self._on_ifm_text_sheet_row_motion)
            lbl.bind("<ButtonRelease-1>", self._on_ifm_text_sheet_row_release)

    def _on_ifm_text_sheet_output_toggle(self, i: int):
        """Mirrors _on_ifm_sheet_output_toggle for the Text Area
        checklist: a sheet unchecked for "Include in output" can't be
        searched either, since there'd be nothing for a search result
        to land in on a sheet that's about to be left out of the
        freshly-built .xmind entirely."""
        if i >= len(self.ifm_text_sheet_output_vars):
            return
        included = self.ifm_text_sheet_output_vars[i].get()
        search_var = self.ifm_text_sheet_vars[i]
        search_cb = self.ifm_text_sheet_search_checks[i]
        if not included:
            search_var.set(False)
            search_cb.config(state=tk.DISABLED)
        else:
            search_cb.config(state=tk.NORMAL)
            search_var.set(True)

    def _on_ifm_text_sheet_row_press(self, event, idx):
        if self.eq_adjust_frame is not None:
            # Eq Adjuster is holding onto sheet-index snapshots -- same
            # guard as _on_sheet_tab_press; just don't let a drag start.
            self._ifm_text_sheet_drag = None
            return
        self._ifm_text_sheet_drag = {"start_idx": idx, "target_idx": idx,
                                     "start_y": event.y_root, "moved": False}

    def _on_ifm_text_sheet_row_motion(self, event):
        drag = self._ifm_text_sheet_drag
        if not drag:
            return
        if not drag["moved"] and abs(event.y_root - drag["start_y"]) < self._SHEET_DRAG_THRESHOLD:
            return
        drag["moved"] = True
        target = self._ifm_text_sheet_row_index_at_y(event.y_root)
        if target is not None:
            drag["target_idx"] = target
        name = self._sheet_tab_display_text(self.sheets[drag["start_idx"]])
        self.status_var.set(f"Drop to move \"{name}\" to position {drag['target_idx'] + 1}")

    def _on_ifm_text_sheet_row_release(self, event):
        drag = self._ifm_text_sheet_drag
        self._ifm_text_sheet_drag = None
        if not drag:
            return
        if drag["moved"]:
            self._reorder_sheet(drag["start_idx"], drag["target_idx"])

    def _ifm_text_sheet_row_index_at_y(self, y_root: int) -> Optional[int]:
        """Which checklist row a screen y-coordinate is currently over
        (or, if between/past rows, closest to) -- same role as the tab
        strip's own _sheet_tab_index_at_x, just along the other axis."""
        best_idx, best_dist = None, None
        for w in self.ifm_text_sheets_frame.winfo_children():
            idx = getattr(w, "_ifm_text_sheet_idx", None)
            if idx is None:
                continue
            top = w.winfo_rooty()
            bottom = top + w.winfo_height()
            if top <= y_root <= bottom:
                return idx
            center = (top + bottom) / 2
            dist = abs(y_root - center)
            if best_dist is None or dist < best_dist:
                best_dist, best_idx = dist, idx
        return best_idx

    def _update_ifm_text_sheets_visibility(self, *_args):
        """Shows/hides (and rebuilds when stale) the "Text Area Sheets"
        checklist depending on the "Search node names from" dropdown --
        only relevant while "Text Area (Condensed Data)" is selected,
        since "AMX Section" has its own separate checklist
        (ifm_sheets_frame) for a loaded .xmind file's real sheets
        instead. Packed with before=self._ifm_amx_frame_ref so it
        always sits in the same slot in the panel regardless of when
        it's (re)packed.

        Called from three places: once at panel-build time (initial
        hidden state), from the dropdown's own trace
        (_on_ifm_node_source_changed), and from _on_sheets_changed
        whenever self.sheets' names/order/count change (add, close,
        drag-reorder, or a tab's name changing because its lvl1[1] root
        title changed) -- so the checklist shown here can never drift
        out of sync with the real sheet tab strip above the editor."""
        source = self.ifm_node_source_var.get() if hasattr(self, "ifm_node_source_var") else "AMX Section"
        if source != "Text Area (Condensed Data)":
            self.ifm_text_sheets_frame.pack_forget()
            return
        if list(self.sheets) != self._ifm_text_sheet_names_at_last_build:
            self._rebuild_ifm_text_sheet_checklist(list(self.sheets))
        self.ifm_text_sheets_frame.pack(fill=tk.X, pady=(0, 8), before=self._ifm_amx_frame_ref)

    def _ifm_included_text_output_sheet_indices(self) -> List[int]:
        """Reads the Text Area checklist's "Include in output" (\U0001F4C4)
        checkboxes back into a list of indices into self.sheets -- the
        sheets that actually end up built into the fresh multi-sheet
        .xmind (see _ifm_build_and_paste_text_xmind). Mirrors
        _ifm_included_output_sheet_indices for the AMX checklist. Falls
        back to every sheet the same way _ifm_included_text_sheet_
        indices does, and to [0] if every box is somehow unchecked."""
        if (not self.ifm_text_sheet_output_vars
                or len(self.ifm_text_sheet_output_vars) != len(self.sheets)):
            return list(range(len(self.sheets)))
        included = [i for i, v in enumerate(self.ifm_text_sheet_output_vars) if v.get()]
        return included or [0]

    def _ifm_included_text_sheet_indices(self) -> List[int]:
        """Reads the Text Area checklist's "Search for images" (\U0001F50D)
        checkboxes back into a list of indices into self.sheets -- the
        editor's own sheets Automatic Search reads node names from, and
        Preview/Export paste images into, whenever "Search node names
        from" is set to "Text Area (Condensed Data)". A sheet unchecked
        for "Include in output" is excluded here too even if its Search
        box is somehow still checked -- belt-and-braces on top of
        _on_ifm_text_sheet_output_toggle already enforcing this in the
        UI, mirroring _ifm_included_sheet_indices for the AMX checklist.
        Falls back to every OUTPUT-included sheet (the checklist just
        hasn't been built yet for the current self.sheets -- e.g. it's
        still showing "AMX Section" and hasn't been switched to yet) and
        to the first output-included sheet if every search box is
        somehow unchecked."""
        output_included = set(self._ifm_included_text_output_sheet_indices())
        if (not self.ifm_text_sheet_vars
                or len(self.ifm_text_sheet_vars) != len(self.sheets)):
            return list(range(len(self.sheets)))
        included = [i for i, v in enumerate(self.ifm_text_sheet_vars)
                    if v.get() and i in output_included]
        if included:
            return included
        first_output = self._ifm_included_text_output_sheet_indices()
        return [first_output[0]] if first_output else [0]

    def _ifm_gather_text_multi_sheet_targets(self, sheet_indices: List[int],
                                             include_existing: bool = False
                                             ) -> Tuple[List[Dict[str, Any]], List[str], List[int]]:
        """Text Area counterpart of _ifm_gather_multi_sheet_targets:
        walks every CHECKED editor sheet (see
        _ifm_included_text_sheet_indices) instead of every checked
        sheet of a loaded AMX .xmind file, parsing each with
        HierarchyParser (the raw hierarchy tree, same as the old
        single-sheet-only code used) rather than re-reading it back out
        of a built .xmind file. A sheet that's empty or fails to parse
        contributes 0 target nodes rather than raising, so one bad
        sheet can't block the others -- exactly mirroring what
        build_xmind_bytes_multi_sheet does when actually building, so
        the sheet_sizes this returns line up with that file's sheets.

        Returns (dfs_nodes, terms, sheet_sizes) -- see
        _ifm_gather_multi_sheet_targets' docstring for what each means."""
        all_sheet_texts = self._get_all_sheet_texts()
        all_dfs: List[Dict[str, Any]] = []
        all_terms: List[str] = []
        sheet_sizes: List[int] = []
        for idx in sheet_indices:
            text = all_sheet_texts[idx][1] if 0 <= idx < len(all_sheet_texts) else ""
            tree = None
            if text and text.strip():
                try:
                    tree = HierarchyParser(text).build_tree()
                except Exception:
                    tree = None
            dfs_nodes = self._ifm_dfs_targets(tree, include_existing=include_existing) if tree else []
            terms = self._ifm_addressed_terms(dfs_nodes) if dfs_nodes else []
            all_dfs.extend(dfs_nodes)
            all_terms.extend(terms)
            sheet_sizes.append(len(dfs_nodes))
        return all_dfs, all_terms, sheet_sizes

    def _ifm_gather_multi_sheet_targets(self, path: str, sheet_indices: List[int],
                                        include_existing: bool = False
                                        ) -> Tuple[List[Dict[str, Any]], List[str], List[int]]:
        """Walks every included sheet of `path` (see the "Sheets to search"
        checklist / _ifm_included_sheet_indices) the same way the old
        single-sheet code always walked just sheet 0, and concatenates the
        results sheet by sheet in the given order. Search-term
        disambiguation (_ifm_addressed_terms) is run separately per sheet,
        not across the concatenated whole, so a title repeated on two
        different sheets doesn't pick up a needless qualifier the way two
        genuinely-repeated siblings within the same sheet would.
        include_existing is passed straight through to _ifm_dfs_targets --
        see its docstring ("Replace existing images" checkbox).

        Returns (dfs_nodes, terms, sheet_sizes) where dfs_nodes/terms are
        the concatenation across every included sheet and sheet_sizes[i] is
        how many of them came from sheet_indices[i] -- the boundary
        _ifm_inject_multi_sheet needs to know which slice of a positional
        results list belongs to which sheet."""
        all_dfs: List[Dict[str, Any]] = []
        all_terms: List[str] = []
        sheet_sizes: List[int] = []
        for idx in sheet_indices:
            tree = self._xmind_extract_tree(path, idx)
            dfs_nodes = self._ifm_dfs_targets(tree, include_existing=include_existing) if tree else []
            terms = self._ifm_addressed_terms(dfs_nodes) if dfs_nodes else []
            all_dfs.extend(dfs_nodes)
            all_terms.extend(terms)
            sheet_sizes.append(len(dfs_nodes))
        return all_dfs, all_terms, sheet_sizes

    def _ifm_gather_search_targets(self, include_existing: bool = False
                                   ) -> Optional[Tuple[List[Dict[str, Any]], List[str],
                                                        List[int], List[int]]]:
        """M3-139: the single place Automatic Search asks "which nodes /
        search terms am I working with?" -- branches on the "Search node
        names from" dropdown at the top of the IFM section
        (self.ifm_node_source_var):

          - "AMX Section" (default, unchanged from before this dropdown
            existed): walks the loaded IFM AMX .xmind file's checked
            sheets via _ifm_gather_multi_sheet_targets, exactly as
            Automatic Search always has.
          - "Text Area (Condensed Data)": walks every sheet CHECKED in
            the "Text Area Sheets" checklist (self.sheets -- the same
            multi-sheet hierarchy editor the "+"/tab strip above the
            main text box manages) via _ifm_gather_text_multi_sheet_
            targets, each parsed with HierarchyParser the same way the
            AMX case parses each of ITS checked sheets -- so node names
            can be searched straight from one or more draft mind maps
            that haven't been exported/loaded as an .xmind file yet.
            M3-145: previously hardcoded to a single sheet
            (self.input_text only, sheet_indices=[0]) even though the
            checklist UI already existed -- now genuinely spans every
            checked sheet, same as the AMX case always has.
            include_existing has no effect here since a freshly-parsed
            tree never has "_has_image" set on any node -- there's
            nothing IFM has pasted into it yet.

        Returns None if the chosen source has nothing usable to search --
        callers should just return, since a messagebox already explained
        why. Otherwise returns (dfs_nodes, terms, sheet_indices,
        sheet_sizes); dfs_nodes/terms CAN legitimately still be empty in
        the AMX case (e.g. every node already has an image) -- that's
        deliberately not pre-messaged here, since existing callers already
        show their own "Nothing To Do" message tailored to that
        situation."""
        source = self.ifm_node_source_var.get() if hasattr(self, "ifm_node_source_var") else "AMX Section"

        if source == "Text Area (Condensed Data)":
            # M3-145: now walks every sheet CHECKED in the "Text Area
            # Sheets" checklist (see _ifm_included_text_sheet_indices),
            # not just whichever one sheet happened to be active in
            # self.input_text -- that checklist's UI existed since
            # M3-144 but was never actually wired into a search until
            # now.
            sheet_indices = self._ifm_included_text_sheet_indices()
            all_sheet_texts = self._get_all_sheet_texts()
            any_content = any(
                (all_sheet_texts[i][1] or "").strip()
                for i in sheet_indices if 0 <= i < len(all_sheet_texts))
            if not any_content:
                messagebox.showinfo(
                    "Nothing To Search",
                    "The checked Text Area sheet(s) are empty -- paste or write your "
                    "hierarchy text there first, check a sheet that has content above, or "
                    "switch the dropdown above to \"AMX Section\".")
                return None
            dfs_nodes, terms, sheet_sizes = self._ifm_gather_text_multi_sheet_targets(
                sheet_indices, include_existing=include_existing)
            if not dfs_nodes and not any(sheet_sizes):
                # Every checked sheet had content but none of it parsed
                # into a valid hierarchy (or produced any target nodes) --
                # let the caller's own "Nothing To Do" message explain
                # the rest, same as the AMX case already does.
                pass
            return dfs_nodes, terms, sheet_indices, sheet_sizes

        # "AMX Section" (default / fallback for any unrecognized value)
        if not self.ifm_loaded_xmind_path:
            messagebox.showinfo(
                "No File Loaded",
                "Load an .xmind file in the IFM \U0001F4C2 AMX Section above first -- "
                "Automatic Search reads that file's node names to know what to look up. "
                "Or switch the \"Search node names from\" dropdown above to \"Text Area "
                "(Condensed Data)\" to search the node names in the main hierarchy text "
                "box instead.")
            return None
        sheet_indices = self._ifm_included_sheet_indices()
        dfs_nodes, terms, sheet_sizes = self._ifm_gather_multi_sheet_targets(
            self.ifm_loaded_xmind_path, sheet_indices, include_existing=include_existing)
        return dfs_nodes, terms, sheet_indices, sheet_sizes

    def _ifm_inject_multi_sheet(self, source_path: str, output_path: str,
                                sheet_indices: List[int], sheet_sizes: List[int],
                                image_paths: List[str],
                                positional_image_paths: Optional[List[Optional[str]]] = None,
                                **kwargs) -> Tuple[str, int]:
        """inject_images_into_xmind_nodes only ever pastes into one sheet
        per call -- when more than one sheet is checked in "Sheets to
        search", this calls it once per included sheet, slicing
        positional_image_paths at the boundaries _ifm_gather_multi_sheet_
        targets recorded (sheet_sizes), and chains each call's output file
        into the next call's input so `output_path` ends up with every
        included sheet's images pasted into a single file. A sheet with no
        target nodes, or (in positional mode) no successful result for any
        of its target nodes, is skipped entirely rather than raising --
        that's a normal outcome for "this sheet had nothing to search for
        left", not a failure."""
        current_source = source_path
        total_placed = 0
        cursor = 0
        tmp_paths: List[str] = []
        try:
            for i, (sheet_idx, size) in enumerate(zip(sheet_indices, sheet_sizes)):
                is_last = (i == len(sheet_indices) - 1)
                this_positional = None
                if positional_image_paths is not None:
                    this_positional = positional_image_paths[cursor:cursor + size]
                    cursor += size
                if size == 0 or (this_positional is not None and not any(this_positional)):
                    continue
                this_out = output_path if is_last else (tempfile.mktemp(suffix=".xmind"))
                if not is_last:
                    tmp_paths.append(this_out)
                result_path, placed = inject_images_into_xmind_nodes(
                    current_source, this_out, image_paths, sheet_index=sheet_idx,
                    positional_image_paths=this_positional, **kwargs)
                total_placed += placed
                current_source = result_path
            def _same_file(a, b):
                # os.path.samefile compares by device+inode (Windows: by
                # file index), so it correctly says True for two path
                # strings that only differ in slash direction/case/drive-
                # mapping but land on the identical file -- exactly the
                # 'F:\...' vs 'F:/...' case shutil.copyfile's own
                # SameFileError was raising on, uncaught, as a raw "Export
                # Failed" popup that aborted before Open-after-export ran.
                try:
                    return os.path.exists(a) and os.path.exists(b) and os.path.samefile(a, b)
                except OSError:
                    return False

            if current_source != output_path and not _same_file(current_source, output_path):
                shutil.copyfile(current_source, output_path)
            elif (total_placed == 0 and current_source == source_path
                  and not _same_file(source_path, output_path)):
                # Nothing was ever pasted into anything (every included
                # sheet skipped) -- still produce output_path so callers
                # that immediately open/save it don't hit a missing file.
                # Skipped when source_path and output_path already are the
                # same file (see _same_file above): there's nothing to
                # copy, output_path already has the desired content, and
                # copying a file onto itself would just raise.
                shutil.copyfile(source_path, output_path)
            return output_path, total_placed
        finally:
            for p in tmp_paths:
                try:
                    os.remove(p)
                except Exception:
                    pass

    def _load_ifm_xmind(self):
        path = filedialog.askopenfilename(
            title="Load an .xmind File to Paste Images Into",
            filetypes=[("XMind", "*.xmind"), ("All", "*.*")])
        if not path:
            return
        try:
            sheets = list_xmind_sheets(path)
        except Exception as e:
            messagebox.showerror("Load Failed", str(e))
            return
        if not sheets:
            messagebox.showerror("Load Failed", "That .xmind file has no sheets.")
            return
        self.ifm_loaded_xmind_path = path
        # A previous Automatic Search's result mapping was searched against
        # whatever file was loaded before -- it can't be trusted against a
        # newly (re)loaded file, even if it's the same filename, so drop it
        # rather than risk pasting stale results onto the wrong nodes.
        self.ifm_auto_search_positional_images = None
        self.ifm_auto_search_source_path = None
        self.ifm_auto_search_sheet_indices = None
        self.ifm_auto_search_replace_existing = None
        # M3-138: a Load & Resume mapping was matched against whatever
        # file was loaded before too -- same reasoning as the block
        # right above.
        self.ifm_recovered_positional = None
        self.ifm_recovered_terms = None
        self.ifm_recovered_sheet_indices = None
        self.ifm_recovered_replace_existing = None
        # M3-120: every sheet starts checked in "Sheets to search" -- see
        # _rebuild_ifm_sheet_checklist / _ifm_included_sheet_indices.
        self._rebuild_ifm_sheet_checklist(sheets)
        sheet_note = (f"{len(sheets)} sheets found -- all checked below." if len(sheets) > 1
                      else "1 sheet.")
        self.ifm_loaded_xmind_status_var.set(
            f"Loaded: {os.path.basename(path)} ({sheet_note})")
        self.status_var.set(f"Loaded {os.path.basename(path)} for IFM image pasting")
        self._refresh_ifm_level_counts()

    def _clear_ifm_xmind(self):
        self.ifm_loaded_xmind_path = None
        self.ifm_auto_search_positional_images = None
        self.ifm_auto_search_source_path = None
        self.ifm_auto_search_sheet_indices = None
        self.ifm_auto_search_replace_existing = None
        self.ifm_recovered_positional = None
        self.ifm_recovered_terms = None
        self.ifm_recovered_sheet_indices = None
        self.ifm_recovered_replace_existing = None
        self._rebuild_ifm_sheet_checklist([])
        self.ifm_loaded_xmind_status_var.set(
            "No file loaded -- load the .xmind app you want images pasted into.")
        self.status_var.set("Cleared IFM's loaded .xmind file")
        self._refresh_ifm_level_counts()

    # ── RXF's own loaded-file per-sheet "Include \U0001F4C4 / Apply
    #    changes \U0001F3A8" checklist -- built fresh by _load_rxf_xmind on
    #    every load (and cleared by _clear_rxf_xmind), same call pattern as
    #    IFM's own _rebuild_ifm_sheet_checklist. See the widget-creation
    #    comment above (in the RXF section builder) for what the two boxes
    #    actually mean; read back via _rxf_loaded_included_indices /
    #    _rxf_loaded_styled_indices, consumed by _rxf_build. ────────────
    def _rebuild_rxf_loaded_sheet_checklist(self, sheets: List[str]):
        RXF_BG, RXF_FG, RXF_MUTED, RXF_SELECT = "#3a1458", "#ffffff", "#c9a3e0", "#9b59b6"
        for w in self.rxf_loaded_sheets_frame.winfo_children():
            w.destroy()
        self.rxf_loaded_sheet_include_vars = []
        self.rxf_loaded_sheet_style_vars = []
        self.rxf_loaded_sheet_style_checks = []
        if not sheets:
            tk.Label(self.rxf_loaded_sheets_frame, text="(load a file above)",
                     bg=RXF_BG, fg=RXF_MUTED, font=("Helvetica", 8, "italic")).pack(anchor="w")
            return
        # A single-sheet file has nothing to actually drop from the
        # rebuild (that would just produce an empty file), so its Include
        # box stays permanently checked/disabled -- same reasoning as
        # IFM's own checklist. Its Apply-changes box stays interactive
        # even here, since that's still a real choice.
        only_one = len(sheets) == 1
        for i, name in enumerate(sheets):
            row = tk.Frame(self.rxf_loaded_sheets_frame, bg=RXF_BG)
            row.pack(fill=tk.X, anchor="w")
            inc_var = tk.BooleanVar(value=True)
            # Defaults to CHECKED here (unlike the text-area append
            # checklist's Apply-changes box, which defaults to unchecked)
            # -- before this checklist existed, every sheet of a loaded
            # file was always run through whichever of Strip Properties /
            # Level Design / Color Capacity were ticked, with no "leave it
            # raw" option. Defaulting to checked preserves that: loading a
            # file and hitting Preview/Export without touching this
            # checklist still restyles every sheet exactly as before.
            style_var = tk.BooleanVar(value=True)
            self.rxf_loaded_sheet_include_vars.append(inc_var)
            self.rxf_loaded_sheet_style_vars.append(style_var)
            inc_cb = tk.Checkbutton(row, text="\U0001F4C4", variable=inc_var,
                           state=(tk.DISABLED if only_one else tk.NORMAL),
                           bg=RXF_BG, fg=RXF_FG, activebackground=RXF_BG,
                           selectcolor=RXF_SELECT, font=("Helvetica", 8))
            inc_cb.pack(side=tk.LEFT)
            style_cb = tk.Checkbutton(row, text="\U0001F3A8", variable=style_var,
                           bg=RXF_BG, fg=RXF_FG, activebackground=RXF_BG,
                           selectcolor=RXF_SELECT, font=("Helvetica", 8))
            style_cb.pack(side=tk.LEFT)
            self.rxf_loaded_sheet_style_checks.append(style_cb)
            tk.Label(row, text=name, bg=RXF_BG, fg=RXF_FG, font=("Helvetica", 8),
                     wraplength=210, justify=tk.LEFT).pack(side=tk.LEFT, anchor="w")
            inc_var.trace_add("write", lambda *_a, i=i: self._on_rxf_loaded_sheet_include_toggle(i))

    def _on_rxf_loaded_sheet_include_toggle(self, i: int):
        """Unchecking a row's \U0001F4C4 Include force-unchecks and
        disables that row's \U0001F3A8 Apply-changes box too -- nothing to
        style on a sheet that's about to be dropped from the rebuild
        entirely. Re-checking Include re-enables (but does not
        re-check -- matches its own original default) Apply-changes."""
        if i >= len(self.rxf_loaded_sheet_include_vars):
            return
        included = self.rxf_loaded_sheet_include_vars[i].get()
        style_var = self.rxf_loaded_sheet_style_vars[i]
        style_cb = self.rxf_loaded_sheet_style_checks[i]
        if not included:
            style_var.set(False)
            style_cb.config(state=tk.DISABLED)
        else:
            style_cb.config(state=tk.NORMAL)

    def _rxf_loaded_included_indices(self) -> List[int]:
        """Reads the \U0001F4C4 Include boxes back into a list of sheet
        indices to keep in the rebuilt output. Falls back to "every
        sheet" if the checklist is empty (nothing loaded yet, or the
        checklist hasn't been built for the current rxf_loaded_xmind_
        sheets for some reason) so a missing checklist never silently
        drops content."""
        if not self.rxf_loaded_sheet_include_vars:
            return list(range(len(self.rxf_loaded_xmind_sheets)))
        return [i for i, v in enumerate(self.rxf_loaded_sheet_include_vars) if v.get()]

    def _rxf_loaded_styled_indices(self) -> List[int]:
        """Reads the \U0001F3A8 Apply-changes boxes back into a list of
        sheet indices that should be run through RXF's own current Strip
        Properties / Level Design / Color Capacity settings -- every
        other included sheet is carried through unchanged. A sheet whose
        \U0001F4C4 Include box is unchecked is excluded here too (see
        _on_rxf_loaded_sheet_include_toggle, belt-and-braces)."""
        if not self.rxf_loaded_sheet_style_vars:
            return []
        included = set(self._rxf_loaded_included_indices())
        return [i for i, v in enumerate(self.rxf_loaded_sheet_style_vars)
                if v.get() and i in included]

    # ── RXF's own source-file loader (separate from the F-Node AMX and
    #    IFM AMX loaders -- this is the file RXF rebuilds from, if any) ──
    def _load_rxf_xmind(self):
        path = filedialog.askopenfilename(
            title="Load an .xmind File for RXF to Rebuild From",
            filetypes=[("XMind", "*.xmind"), ("All", "*.*")])
        if not path:
            return
        try:
            sheets = list_xmind_sheets(path)
        except Exception as e:
            messagebox.showerror("Load Failed", str(e))
            return
        if not sheets:
            messagebox.showerror("Load Failed", "That .xmind file has no sheets.")
            return
        self.rxf_loaded_xmind_path = path
        self.rxf_loaded_xmind_sheets = sheets
        # Every sheet starts checked for BOTH boxes -- so simply loading a
        # file and hitting Preview/Export without ever touching this
        # checklist still includes and restyles/strips every sheet exactly
        # like before this checklist existed (see _rxf_build).
        self._rebuild_rxf_loaded_sheet_checklist(sheets)

        sheet_note = f"{len(sheets)} sheets found -- all checked below." if len(sheets) > 1 else "1 sheet."
        self.rxf_loaded_xmind_status_var.set(f"Loaded: {os.path.basename(path)} ({sheet_note})")
        self.status_var.set(f"Loaded {os.path.basename(path)} for RXF rebuild")
        self._refresh_rxf_level_counts()

    def _clear_rxf_xmind(self):
        self.rxf_loaded_xmind_path = None
        self.rxf_loaded_xmind_sheets = []
        self._rebuild_rxf_loaded_sheet_checklist([])
        self.rxf_loaded_xmind_status_var.set(
            "No file loaded -- rebuild falls back to the F-Node AMX file (if any), then the hierarchy text.")
        self.status_var.set("Cleared RXF's loaded .xmind file")
        self._refresh_rxf_level_counts()

    def _ifm_pool_images_for_source(self, source: Optional[str] = None) -> List[str]:
        """M3-141: the cycling-fallback pool Preview/Export use whenever
        no valid positional mapping applies (see the two callers of
        _ifm_get_positional_images_if_valid / _ifm_get_positional_
        images_for_text_if_valid below) -- filters self.structure_images
        down to only images that are safe to cycle for `source` (the
        current "Search node names from" dropdown value; defaults to
        whatever it's currently set to).

        An image gets excluded only if ifm_auto_image_source explicitly
        tags it as belonging to a DIFFERENT source -- i.e. it was
        downloaded by an Automatic Search run (or recovered by Load &
        Resume) against the other dropdown option. Everything else --
        untagged images from "Load Images"/"Load Folder"/"Search
        Images", plus any Automatic-Search image that matches the
        CURRENT source -- passes through exactly as it always has.

        This is what stops switching the dropdown after a run from
        silently pasting that run's own images into a build made under
        the other source."""
        if source is None:
            source = self.ifm_node_source_var.get() if hasattr(self, "ifm_node_source_var") else "AMX Section"
        tags = getattr(self, "ifm_auto_image_source", None) or {}
        return [p for p in self.structure_images
                if tags.get(p, source) == source]

    def _ifm_get_positional_images_if_valid(self) -> Optional[List[Optional[str]]]:
        """Returns the last Automatic Search run's positional result
        mapping (see _run_ifm_auto_search) if it's still trustworthy for
        whatever's currently loaded in the IFM AMX Section, else None.
        "Trustworthy" means: it was searched against this exact file (not
        a file that has since been reloaded/replaced), against the same
        set of checked sheets (see "Sheets to search" -- unchecking or
        re-checking a sheet since the search ran invalidates it, since
        entry i would no longer line up with the same target node), and
        that sheet set's node-needing-an-image count hasn't changed since
        either, and the "Replace images already in the file" checkbox is
        still in the same state it was when the search ran (toggling it
        changes which nodes count as targets -- see _ifm_dfs_targets'
        include_existing). Preview/Export prefer this mapping over cycling
        through the plain structure_images pool, since it's the only way a
        search that skipped a few nodes can't end up shifting every later
        node's image onto the wrong one."""
        mapping = self.ifm_auto_search_positional_images
        if not mapping or _norm_path(self.ifm_auto_search_source_path) != _norm_path(self.ifm_loaded_xmind_path):
            return None
        sheet_indices = self._ifm_included_sheet_indices()
        if self.ifm_auto_search_sheet_indices != sheet_indices:
            return None
        replace_existing = self.ifm_replace_existing_var.get()
        if self.ifm_auto_search_replace_existing != replace_existing:
            return None
        dfs_nodes, _terms, _sizes = self._ifm_gather_multi_sheet_targets(
            self.ifm_loaded_xmind_path, sheet_indices, include_existing=replace_existing)
        if len(dfs_nodes) != len(mapping):
            return None
        return mapping

    def _ifm_get_positional_images_for_text_if_valid(
            self, sheet_indices: List[int], replace_existing: bool) -> Optional[List[Optional[str]]]:
        """Text-area counterpart of _ifm_get_positional_images_if_valid,
        used by IFM's own Preview/Export buttons (see
        _ifm_build_and_paste_text_xmind) when the \"Search node names
        from\" dropdown is set to \"Text Area (Condensed Data)\" instead of
        a loaded AMX .xmind file. The text box has no loaded-file identity
        of its own to compare against, so instead of the AMX-file
        version's path check, a stored mapping is trusted here only when
        it actually came from an Automatic Search run whose node source
        was that same \"Text Area (Condensed Data)\" setting -- the only
        situation where ifm_auto_search_source_path ends up None, since
        the AMX-file source always records a real loaded path there
        instead. Still re-validated the same way the AMX version is
        otherwise: the checked "Text Area Sheets" set (`sheet_indices`,
        see _ifm_included_text_sheet_indices -- M3-145: no longer
        hardcoded to [0], now the actual checked-sheet list, exactly
        like the AMX-file version's own sheet-checklist check) and the
        \"Replace images already in the file\" setting must both match
        what they were when the search ran, and those checked sheets
        must still walk down to exactly as many target nodes, combined,
        as the mapping has entries for."""
        mapping = self.ifm_auto_search_positional_images
        # M3-143: this whole method silently returning None used to be a
        # black box -- the caller (_ifm_build_and_paste_text_xmind) just
        # fell back to cycling the flat structure_images pool with no clue
        # WHY the positional mapping (which is what keeps a node that
        # Automatic Search never found anything for correctly unimaged)
        # got discarded. A run that legitimately left some nodes unfound
        # would then have those nodes silently backfilled with OTHER
        # nodes' successfully-downloaded images once the fallback pool
        # cycled around to them -- reading exactly like "the first node
        # has an image it shouldn't." Printing the specific reason here
        # turns that into something diagnosable from the console instead
        # of having to guess.
        if not mapping:
            print("[IFM Text Area] positional mapping unavailable -- no Automatic Search run has "
                  "completed for this text yet; falling back to the flat image pool.")
            return None
        if self.ifm_auto_search_source_path is not None:
            print("[IFM Text Area] positional mapping discarded -- it belongs to an AMX Section "
                  f"file ({self.ifm_auto_search_source_path!r}), not the Text Area; falling back "
                  "to the flat image pool.")
            return None
        if self.ifm_auto_search_sheet_indices != sheet_indices:
            print("[IFM Text Area] positional mapping discarded -- its recorded checked sheets "
                  f"{self.ifm_auto_search_sheet_indices!r} != the currently checked "
                  f"{sheet_indices!r} (a sheet was added/removed/checked/unchecked/reordered "
                  "since the search ran); falling back to the flat image pool.")
            return None
        if self.ifm_auto_search_replace_existing != replace_existing:
            print("[IFM Text Area] positional mapping discarded -- it was searched with "
                  f"\"Replace existing images\"={self.ifm_auto_search_replace_existing!r}, current "
                  f"checkbox is {replace_existing!r}; falling back to the flat image pool.")
            return None
        dfs_nodes, _terms, _sizes = self._ifm_gather_text_multi_sheet_targets(
            sheet_indices, include_existing=replace_existing)
        if len(dfs_nodes) != len(mapping):
            print(f"[IFM Text Area] positional mapping discarded -- it has {len(mapping)} entries "
                  f"but the checked sheet(s) now walk to {len(dfs_nodes)} target node(s) combined; "
                  "the text (or something feeding into node count, e.g. equations) changed since "
                  "the search ran. Falling back to the flat image pool -- THIS is the case that "
                  "can make an already-failed node look like it picked up an image, since the "
                  "fallback pool cycles in first-downloaded order, not per-node order.")
            return None
        found = sum(1 for p in mapping if p)
        print(f"[IFM Text Area] positional mapping OK -- using it as-is "
              f"({found}/{len(mapping)} node(s) have an image, the rest stay unimaged).")
        return mapping

    def _ifm_build_and_paste_text_xmind(self, output_path: str) -> Tuple[str, int]:
        """IFM's own Preview/Export, for the \"Text Area (Condensed Data)\"
        node source: builds a fresh .xmind straight from every sheet
        CHECKED in the "Text Area Sheets" checklist (see
        _ifm_included_text_sheet_indices -- M3-145: previously only ever
        read self.input_text, i.e. whichever ONE sheet happened to be
        active), each landing as its own real sheet/page in the output
        file via build_xmind_bytes_multi_sheet -- running every checked
        sheet's text through the same config Preview/Export always use
        (level colors/layout, map background, note heading/bold,
        equation format/design, via _get_config) but deliberately
        WITHOUT F-Nodes or RXF, since those only ever apply to an
        already-built .xmind file elsewhere in the app -- then pastes
        IFM's downloaded/loaded images into that fresh file, one checked
        sheet at a time (_ifm_inject_multi_sheet), exactly like the
        AMX-file flow does for a loaded multi-sheet .xmind. Written to
        `output_path` directly (a temp file for Preview, the user's
        chosen save path for Export).

        Prefers the last Automatic Search run's positional mapping when
        it's still valid for the current checked sheets (see
        _ifm_get_positional_images_for_text_if_valid), and otherwise
        falls back to cycling through the plain structure_images pool
        (manually loaded images). Raises ValueError with a clear message
        on any failure (every checked sheet empty/unparseable, no images
        available) -- callers should catch and show it, the same way the
        AMX-file flow's own errors are shown.

        Returns (output_path, placed).
        """
        # M3-146: output_indices (\U0001F4C4 "Include in output") decides
        # which sheets get BUILT into the fresh .xmind; search_indices
        # (\U0001F50D "Search for images", always a subset of output_indices --
        # see _ifm_included_text_sheet_indices) decides which of those
        # built sheets actually get images pasted into them. A sheet
        # that's output-included but not search-included still lands in
        # the file, just with no images pasted into its nodes -- mirrors
        # how the AMX-file flow can build/keep a sheet while leaving it
        # out of the search.
        output_indices = self._ifm_included_text_output_sheet_indices()
        search_indices = set(self._ifm_included_text_sheet_indices())
        all_sheet_texts = self._get_all_sheet_texts()
        # Only the output-included sheets, pre-filtered to ones that
        # actually have content -- build_xmind_bytes_multi_sheet skips
        # empty/unparseable sheets too, but filtering here first keeps
        # this method's own `selected` list (used below for sheet_sizes)
        # in exact 1:1 order with the sheets that really end up in the
        # built file, which _ifm_inject_multi_sheet's positional slicing
        # depends on. Each entry keeps its ORIGINAL self.sheets index so
        # sheet_sizes can tell which built sheets were also search-checked.
        selected = [(orig_i, all_sheet_texts[orig_i]) for orig_i in output_indices
                   if 0 <= orig_i < len(all_sheet_texts) and (all_sheet_texts[orig_i][1] or "").strip()]
        if not selected:
            raise ValueError(
                "The checked Text Area sheet(s) are empty -- paste your hierarchy text there "
                "first, or check a sheet that has content in the \"Text Area Sheets\" list above.")
        (level_colors, color_mode, layout, map_bg, note_heading, note_bold,
         eq_fmt, eq_override_flags, eq_design) = self._get_config()
        tagged = [(name, self._apply_heading_tags(text)) for _orig_i, (name, text) in selected]
        xmind_bytes = build_xmind_bytes_multi_sheet(
            tagged, layout=layout, level_colors=level_colors, color_mode=color_mode,
            map_bg=map_bg, note_heading=note_heading, default_img_fmt=eq_fmt,
            eq_override_flags=eq_override_flags, eq_design=eq_design)
        out_dir = os.path.dirname(os.path.abspath(output_path))
        if out_dir:
            os.makedirs(out_dir, exist_ok=True)
        with open(output_path, "wb") as f:
            f.write(xmind_bytes)

        replace_existing = self.ifm_replace_existing_var.get()
        # Source of truth for each built sheet's target-node count is the
        # file we just actually built (same as the AMX-file flow reads it
        # from the loaded .xmind), not a separate re-parse of the raw
        # text -- see _ifm_get_positional_images_for_text_if_valid's
        # docstring for why that distinction matters. A built sheet whose
        # ORIGINAL sheet wasn't search-checked gets size 0 here so
        # _ifm_inject_multi_sheet skips pasting into it entirely, without
        # dropping it from the built file.
        sheet_sizes = []
        for pos, (orig_i, _text) in enumerate(selected):
            if orig_i not in search_indices:
                sheet_sizes.append(0)
                continue
            built_tree = self._xmind_extract_tree(output_path, pos)
            dfs = self._ifm_dfs_targets(built_tree, include_existing=replace_existing) if built_tree else []
            sheet_sizes.append(len(dfs))

        positional = self._ifm_get_positional_images_for_text_if_valid(
            sorted(search_indices), replace_existing)
        # M3-141: filtered so an Automatic Search run downloaded against
        # the "AMX Section" source (or recovered by Load & Resume, which
        # is always AMX-only) can't get cycled onto this Text Area build.
        image_paths = ([] if positional is not None
                        else self._ifm_pool_images_for_source("Text Area (Condensed Data)"))
        if positional is None:
            # M3-143: pairs with the diagnostic prints added to
            # _ifm_get_positional_images_for_text_if_valid above -- once
            # that method has already explained (or will explain, if
            # `mapping` was simply empty) WHY the positional mapping isn't
            # being used, this makes clear what's about to happen instead:
            # up to len(image_paths) of the target nodes get one of THOSE
            # images each, in target order, regardless of which specific
            # node any given image was originally downloaded for.
            print(f"[IFM Text Area] no positional mapping in use -- placing from the flat pool "
                  f"({len(image_paths)} image(s) available, allow_cycling=False, so each is used "
                  "on at most one node and in target-node order, not necessarily the node it was "
                  "originally downloaded for).")
        if positional is None and not image_paths:
            raise ValueError(
                "No images loaded -- run \U0001F916 Automatic Search above (with this dropdown set to "
                "\"Text Area (Condensed Data)\"), or load images via \U0001F5BC Load Images / "
                "\U0001F4C1 Load Folder, first.")
        # The built file's own sheets are sequential 0..len(tagged)-1, in
        # the same order as `tagged`/`selected`/`sheet_sizes` above --
        # NOT the original self.sheets indices in `sheet_indices` (those
        # may be sparse/reordered; only the CHECKED, non-empty ones made
        # it into the file at all, and they're renumbered from 0 there).
        built_sheet_positions = list(range(len(tagged)))
        result_path, placed = self._ifm_inject_multi_sheet(
            output_path, output_path, built_sheet_positions, sheet_sizes, image_paths,
            positional_image_paths=positional,
            img_width=self.ifm_img_width_var.get(),
            img_height=self.ifm_img_height_var.get(),
            skip_nodes_with_image=not replace_existing,
            size_assignment=(list(self.ifm_size_assignment)
                              if positional is None and self.ifm_random_size_var.get()
                              and self.ifm_size_assignment else None),
            # M3-142: Text Area never cycles/duplicates -- if the
            # positional mapping's gone stale and this falls back to the
            # flat pool above, each image in it is still only ever used
            # on one node. 20 images downloaded means at most 20 of the
            # 50 nodes needing one actually get one; the other 30 stay
            # unimaged rather than reusing one of the 20 a second (or
            # third, ...) time. See inject_images_into_xmind_nodes'
            # allow_cycling docstring.
            allow_cycling=False)
        return result_path, placed

    def _ifm_guard(self) -> bool:
        """Shared precondition check for both IFM Preview and Export.
        Branches on the \"Search node names from\" dropdown: \"Text Area
        (Condensed Data)\" pastes into a mindmap built fresh from every
        sheet CHECKED in the "Text Area Sheets" checklist (see
        _ifm_build_and_paste_text_xmind / _ifm_included_text_sheet_
        indices -- M3-145: previously only ever checked self.input_text,
        i.e. whichever one sheet happened to be active) and so never
        needs an AMX file loaded; \"AMX Section\" (the default) keeps the
        original behavior of requiring one."""
        if not self.ifm_enabled_var.get():
            messagebox.showwarning("IFM Disabled",
                                    "Enable the IFM switch at the top of the Images for Mindmap section first.")
            return False
        source = self.ifm_node_source_var.get() if hasattr(self, "ifm_node_source_var") else "AMX Section"
        if source == "Text Area (Condensed Data)":
            # M3-146: content is checked against the \U0001F4C4 "Include in
            # output" set (what actually gets built), while the target-node/
            # search-image checks below use the \U0001F50D "Search for images"
            # set (a subset) -- mirrors the split now used throughout the
            # Text Area flow (see _ifm_included_text_output_sheet_indices /
            # _ifm_included_text_sheet_indices).
            output_indices = self._ifm_included_text_output_sheet_indices()
            search_indices = self._ifm_included_text_sheet_indices()
            all_sheet_texts = self._get_all_sheet_texts()
            any_content = any(
                (all_sheet_texts[i][1] or "").strip()
                for i in output_indices if 0 <= i < len(all_sheet_texts))
            if not any_content:
                messagebox.showinfo("Nothing To Do",
                                     "The checked Text Area sheet(s) are empty -- paste or write your "
                                     "hierarchy text there first, or check a sheet that has content "
                                     "in the \"Text Area Sheets\" list above.")
                return False
            replace_existing = self.ifm_replace_existing_var.get()
            dfs_nodes, _terms, _sizes = self._ifm_gather_text_multi_sheet_targets(
                search_indices, include_existing=replace_existing)
            if not dfs_nodes:
                messagebox.showinfo("Nothing To Do",
                                     "The sheet(s) checked for \U0001F50D Search don't contain a valid "
                                     "hierarchy yet -- each one's first entry must start with lvl1[1].")
                return False
            positional = self._ifm_get_positional_images_for_text_if_valid(search_indices, replace_existing)
            if not self._ifm_pool_images_for_source("Text Area (Condensed Data)") and not positional:
                messagebox.showinfo("No Images Loaded",
                                     "Run \U0001F916 Automatic Search above first (with this dropdown set to "
                                     "\"Text Area (Condensed Data)\"), or load images via \U0001F5BC Load "
                                     "Images / \U0001F4C1 Load Folder.")
                return False
            return True
        if not self.ifm_loaded_xmind_path:
            messagebox.showinfo("No File Loaded",
                                 "Load an .xmind file in the IFM \U0001F4C2 AMX Section above first -- "
                                 "that's the app whose nodes the images below get pasted into. Or switch "
                                 "the \"Search node names from\" dropdown above to \"Text Area (Condensed "
                                 "Data)\" to paste straight into the main hierarchy text box instead.")
            return False
        if not self._ifm_pool_images_for_source("AMX Section") and not self._ifm_get_positional_images_if_valid():
            messagebox.showinfo("No Images Loaded",
                                 "Load at least one image (\U0001F5BC Load Images / \U0001F4C1 Load Folder), "
                                 "or run \U0001F916 Automatic Search option, above first.")
            return False
        return True

    def _ifm_filter_output_sheets(self, result_path: str, output_indices: List[int]) -> str:
        """Drops every sheet not checked for "Include in output" from
        result_path in place (a temp-then-replace dance, same pattern
        _rxf_build uses, so a mid-write failure never leaves result_path
        half-rewritten). No-op (returns result_path unchanged) when every
        sheet is still included, to avoid an unnecessary rewrite on the
        common case."""
        if len(output_indices) >= len(self.ifm_loaded_xmind_sheets):
            return result_path
        tmp_path = result_path + ".ifm_sheets_tmp"
        os.replace(result_path, tmp_path)
        try:
            return _xmind_filter_sheets(tmp_path, result_path, output_indices)
        finally:
            try:
                os.remove(tmp_path)
            except OSError:
                pass

    def _ifm_preview(self):
        if not self._ifm_guard():
            return
        source = self.ifm_node_source_var.get() if hasattr(self, "ifm_node_source_var") else "AMX Section"
        if source == "Text Area (Condensed Data)":
            path = os.path.join(tempfile.gettempdir(), f"mindmap_preview_{uuid.uuid4().hex}.xmind")
            try:
                result_path, placed = self._ifm_build_and_paste_text_xmind(path)
            except Exception as e:
                messagebox.showerror("Preview Failed", str(e))
                return
            if not self._open_and_autodelete(result_path, self._ifm_delay.seconds):
                return
            self.status_var.set(f"IFM preview opened: pasted {placed} image(s) into nodes")
            return
        positional = self._ifm_get_positional_images_if_valid()
        sheet_indices = self._ifm_included_sheet_indices()
        replace_existing = self.ifm_replace_existing_var.get()
        # include_existing here must match skip_nodes_with_image below (the
        # same "Replace images already in the file" checkbox), or a sheet
        # that's entirely already-imaged would come back with sheet_size 0
        # under the old "skip existing" counting and get skipped outright
        # by _ifm_inject_multi_sheet instead of having its images replaced.
        _dfs, _terms, sheet_sizes = self._ifm_gather_multi_sheet_targets(
            self.ifm_loaded_xmind_path, sheet_indices, include_existing=replace_existing)
        path = os.path.join(tempfile.gettempdir(), f"mindmap_preview_{uuid.uuid4().hex}.xmind")
        try:
            result_path, placed = self._ifm_inject_multi_sheet(
                self.ifm_loaded_xmind_path, path, sheet_indices, sheet_sizes,
                # M3-141: filtered so a Text Area run's images (or none of
                # this file's own AMX-tagged ones after a stale mapping)
                # can't get cycled onto this AMX Section build.
                [] if positional is not None else self._ifm_pool_images_for_source("AMX Section"),
                positional_image_paths=positional,
                img_width=self.ifm_img_width_var.get(),
                img_height=self.ifm_img_height_var.get(),
                skip_nodes_with_image=not replace_existing,
                size_assignment=(list(self.ifm_size_assignment)
                                  if positional is None and self.ifm_random_size_var.get()
                                  and self.ifm_size_assignment else None))
            # "Include in output" runs last, after images are pasted, since
            # it drops sheets by their *original* index -- see
            # _xmind_filter_sheets.
            result_path = self._ifm_filter_output_sheets(
                result_path, self._ifm_included_output_sheet_indices())
        except Exception as e:
            messagebox.showerror("Preview Failed", str(e))
            return
        if not self._open_and_autodelete(result_path, self._ifm_delay.seconds):
            return
        self.status_var.set(f"IFM preview opened: pasted {placed} image(s) into nodes")

    def _ifm_export(self):
        if not self._ifm_guard():
            return
        source = self.ifm_node_source_var.get() if hasattr(self, "ifm_node_source_var") else "AMX Section"
        if source == "Text Area (Condensed Data)":
            initial_name = "mindmap_with_images.xmind"
            try:
                # M3-146: the suggested filename comes from the first
                # \U0001F4C4 "Include in output" sheet's root title now (that's
                # the set Export actually builds via
                # _ifm_build_and_paste_text_xmind below), not always
                # whichever sheet happens to be active or just the
                # \U0001F50D "Search for images" subset.
                output_indices = self._ifm_included_text_output_sheet_indices()
                all_sheet_texts = self._get_all_sheet_texts()
                first_idx = next((i for i in output_indices
                                  if 0 <= i < len(all_sheet_texts) and (all_sheet_texts[i][1] or "").strip()),
                                 None)
                raw = all_sheet_texts[first_idx][1] if first_idx is not None else ""
                root_node = HierarchyParser(raw).build_tree() if raw.strip() else None
                if root_node and root_node.get("title"):
                    initial_name = root_node["title"] + "_with_images.xmind"
            except Exception:
                pass
            out_path = filedialog.asksaveasfilename(
                title="Save Mindmap with Pasted Images As",
                defaultextension=".xmind",
                filetypes=[("XMind", "*.xmind"), ("All", "*.*")],
                initialfile=initial_name)
            if not out_path:
                return
            try:
                result_path, placed = self._ifm_build_and_paste_text_xmind(out_path)
            except Exception as e:
                messagebox.showerror("Export Failed", str(e))
                return
            self.status_var.set(
                f"IFM: exported {placed} image(s) pasted into nodes -- {os.path.basename(result_path)}")
            if self.ifm_open_after_export_var.get():
                self._open_file_external(result_path)
            return
        out_path = filedialog.asksaveasfilename(
            title="Save Mindmap with Pasted Images As",
            defaultextension=".xmind",
            filetypes=[("XMind", "*.xmind"), ("All", "*.*")],
            initialfile=os.path.splitext(os.path.basename(self.ifm_loaded_xmind_path))[0] + "_with_images.xmind")
        if not out_path:
            return
        positional = self._ifm_get_positional_images_if_valid()
        sheet_indices = self._ifm_included_sheet_indices()
        replace_existing = self.ifm_replace_existing_var.get()
        # See _ifm_preview's comment on why include_existing here must
        # match skip_nodes_with_image below.
        _dfs, _terms, sheet_sizes = self._ifm_gather_multi_sheet_targets(
            self.ifm_loaded_xmind_path, sheet_indices, include_existing=replace_existing)
        try:
            result_path, placed = self._ifm_inject_multi_sheet(
                self.ifm_loaded_xmind_path, out_path, sheet_indices, sheet_sizes,
                # M3-141: see the matching comment in _ifm_preview above.
                [] if positional is not None else self._ifm_pool_images_for_source("AMX Section"),
                positional_image_paths=positional,
                img_width=self.ifm_img_width_var.get(),
                img_height=self.ifm_img_height_var.get(),
                skip_nodes_with_image=not replace_existing,
                size_assignment=(list(self.ifm_size_assignment)
                                  if positional is None and self.ifm_random_size_var.get()
                                  and self.ifm_size_assignment else None))
            result_path = self._ifm_filter_output_sheets(
                result_path, self._ifm_included_output_sheet_indices())
        except Exception as e:
            messagebox.showerror("Export Failed", str(e))
            return
        self.status_var.set(f"IFM: exported {placed} image(s) pasted into nodes -- {os.path.basename(result_path)}")
        if self.ifm_open_after_export_var.get():
            self._open_file_external(result_path)

    # ================================================================
    # GFM (GIF for Mindmap) -- Phase 3 methods (M3-145)
    # ================================================================
    # Mirrors every IFM method above 1:1, adapted for GIFs: no format
    # conversion anywhere (GIFs are always kept exactly as downloaded/
    # loaded -- re-encoding would flatten animation), and an extra
    # "Search engine" choice threaded through the search/download calls
    # since GFM offers google/pinterest/google_pinterest and IFM doesn't.
    # _ifm_dfs_targets / _ifm_addressed_terms / _ifm_inject_multi_sheet /
    # inject_images_into_xmind_nodes / _cleanup_search_temp_dirs /
    # _ifm_fmt_duration are all genuinely generic (no ifm-specific state)
    # and are reused directly rather than duplicated -- see each call
    # site below.

    _GFM_AUTO_SEARCH_MAX_RETRY_PASSES = 10
    _GFM_AUTO_LOG_MAX_LINES = 500

    def _gfm_engine_key(self) -> str:
        """Reads the "Search engine" dropdown (which shows the friendly
        label, e.g. "Pinterest GIF") back into the engine key
        _GFM_ENGINE_FUNCS/_gfm_search_and_download_one expect (e.g.
        "pinterest"). Falls back to "google" if the label doesn't match
        anything (shouldn't happen -- the dropdown only ever offers
        _GFM_ENGINE_LABELS' own values)."""
        label = self.gfm_engine_var.get() if hasattr(self, "gfm_engine_var") else _GFM_ENGINE_LABELS["google"]
        for key, lbl in _GFM_ENGINE_LABELS.items():
            if lbl == label:
                return key
        return "google"

    def _gfm_shrink_and_format_args(self):
        """Reads the "GFM Download Size / Format" controls into the
        (shrink_to, output_format) pair wie_download_gif expects.
        shrink_to is None when the shrink checkbox is off (download
        stays at whatever size the source served); otherwise it's the
        current GIF Width/Height spinboxes -- the same box the GIF is
        actually displayed at, so shrinking to it loses no visible
        detail. output_format is "webp" only when that option is
        selected in the dropdown; "gif" (unchanged bytes, unless
        shrink_to also applies) otherwise."""
        shrink_to = None
        if getattr(self, "gfm_shrink_downloads_var", None) and self.gfm_shrink_downloads_var.get():
            try:
                w = max(10, int(self.gfm_img_width_var.get()))
                h = max(10, int(self.gfm_img_height_var.get()))
                shrink_to = (w, h)
            except Exception:
                shrink_to = None
        output_format = "gif"
        if getattr(self, "gfm_output_format_var", None) and \
                self.gfm_output_format_var.get().startswith("WebP"):
            output_format = "webp"
        return shrink_to, output_format

    # ── Manual pool: Load GIFs / Load Folder / Clear -- mirrors
    # _load_structure_images / _load_structure_folder / _clear_structure_
    # images one-for-one, against gfm_gif_pool instead of
    # structure_images. GIF-only filetypes (unlike IFM's multi-format
    # filter) since re-encoding to another format would flatten
    # animation. ──
    def _update_gif_pool_status(self):
        n = len(self.gfm_gif_pool)
        if n == 0:
            self.gfm_gif_pool_status_var.set("No GIFs loaded")
            return
        run_n = getattr(self, "_gfm_auto_run_loaded_count", None)
        if run_n is not None:
            self.gfm_gif_pool_status_var.set(
                f"{run_n:,} GIF(s) loaded this run ({n:,} total in pool) -- not yet placed on any node")
        else:
            self.gfm_gif_pool_status_var.set(f"{n:,} GIF(s) loaded -- not yet placed on any node")

    def _load_gif_pool(self):
        paths = filedialog.askopenfilenames(
            title="Load GIFs for Mindmap Structure",
            filetypes=[("GIF/WebP", "*.gif *.webp"), ("All", "*.*")])
        for p in paths:
            if p not in self.gfm_gif_pool:
                self.gfm_gif_pool.append(p)
        self._update_gif_pool_status()

    def _load_gif_folder(self):
        folder = filedialog.askdirectory(title="Load Folder of GIFs for Mindmap Structure")
        if not folder:
            return
        for fname in sorted(os.listdir(folder)):
            if fname.lower().endswith((".gif", ".webp")):
                full = os.path.join(folder, fname)
                if full not in self.gfm_gif_pool:
                    self.gfm_gif_pool.append(full)
        self._update_gif_pool_status()

    def _clear_gif_pool(self):
        self.gfm_gif_pool.clear()
        self.gfm_auto_gif_source.clear()
        self._cleanup_search_temp_dirs(self._gfm_search_temp_dirs)
        self.gfm_auto_search_positional_gifs = None
        self.gfm_auto_search_source_path = None
        self.gfm_auto_search_sheet_indices = None
        self.gfm_auto_search_replace_existing = None
        self.gfm_recovered_positional = None
        self.gfm_recovered_terms = None
        self.gfm_recovered_sheet_indices = None
        self.gfm_recovered_replace_existing = None
        self._update_gif_pool_status()

    def _on_gfm_node_source_changed(self, *_args):
        """GFM's counterpart to _on_ifm_node_source_changed -- fires
        whenever GFM's own "Search node names from" dropdown changes.
        Invalidates the last Automatic Search run's positional mapping;
        does NOT touch gfm_gif_pool or gfm_auto_gif_source (per-GIF
        source tagging is what keeps the cycling fallback correctly
        scoped -- see _gfm_pool_images_for_source)."""
        self.gfm_auto_search_positional_gifs = None
        self.gfm_auto_search_source_path = None
        self.gfm_auto_search_sheet_indices = None
        self.gfm_auto_search_replace_existing = None
        if hasattr(self, "gfm_gif_pool_status_var"):
            self._update_gif_pool_status()

    def _load_and_resume_gfm_gifs(self):
        """GFM's counterpart to _load_and_resume_ifm_images -- recovers a
        previous GFM Automatic Search run's progress from its temp folder
        of already-downloaded GIF files, each named
        "{index:03d}_{sanitized node name}_{...}.gif" (see
        _gfm_search_and_download_one). Matches each file to a node in the
        CURRENTLY loaded GFM .xmind file by both its embedded index AND
        its embedded node name -- see _load_and_resume_ifm_images'
        docstring for the full reasoning, identical here."""
        if not self.gfm_loaded_xmind_path:
            messagebox.showinfo(
                "No File Loaded",
                "Load the .xmind file in the GFM \U0001F4C2 AMX Section above first -- Load & "
                "Resume needs to know the exact node names/order the interrupted run was "
                "searching against, which comes from that file.")
            return
        folder = filedialog.askdirectory(
            title="Load & Resume -- Folder Of Previously Downloaded GIFs")
        if not folder:
            return

        sheet_indices = self._gfm_included_sheet_indices()
        replace_existing = self.gfm_replace_existing_var.get()
        dfs_nodes, terms, sheet_sizes = self._gfm_gather_multi_sheet_targets(
            self.gfm_loaded_xmind_path, sheet_indices, include_existing=replace_existing)
        if not terms:
            messagebox.showinfo(
                "Nothing To Match",
                "Every node in the checked sheet(s) already has an image (or no sheets are "
                "checked below) -- there's nothing for Load & Resume to match against.")
            return
        total = len(terms)

        try:
            filenames = os.listdir(folder)
        except Exception as e:
            messagebox.showerror("Can't Read Folder", str(e))
            return

        fname_re = re.compile(r'^(\d+)_(.+)\.(?:gif|webp)$', re.IGNORECASE)
        recovered: List[Optional[str]] = [None] * total
        matched_files = 0
        name_mismatch = 0
        dup_index_skipped = 0
        unmatched_files = 0

        for fname in sorted(filenames):
            m = fname_re.match(fname)
            if not m:
                unmatched_files += 1
                continue
            try:
                idx = int(m.group(1))
            except ValueError:
                unmatched_files += 1
                continue
            if idx < 1 or idx > total:
                name_mismatch += 1
                continue
            if recovered[idx - 1] is not None:
                dup_index_skipped += 1
                continue
            rest = m.group(2)
            expected_prefix = re.sub(r'[^A-Za-z0-9_\-]+', "_", terms[idx - 1])[:40].strip("_")
            if expected_prefix and rest.lower().startswith(expected_prefix.lower()):
                recovered[idx - 1] = os.path.join(folder, fname)
                matched_files += 1
            else:
                name_mismatch += 1

        if matched_files == 0:
            messagebox.showwarning(
                "Nothing Matched",
                "None of the files in that folder matched a node name in the currently loaded "
                ".xmind file, with the sheets currently checked and the current \"Replace "
                "existing images\" setting. Double check this is the same .xmind file, the same "
                "sheets, and the same setting the interrupted run used -- and that this is "
                "really the folder it was saving into (see \"Downloaded-GIF temp folder:\" "
                "near the top of that run's own .txt log file).")
            return

        existing_paths = set(self.gfm_gif_pool)
        for p in recovered:
            if p and p not in existing_paths:
                existing_paths.add(p)
                self.gfm_gif_pool.append(p)
                self.gfm_auto_gif_source[p] = "AMX Section"
        self._update_gif_pool_status()

        self.gfm_recovered_positional = recovered
        self.gfm_recovered_terms = list(terms)
        self.gfm_recovered_sheet_indices = list(sheet_indices)
        self.gfm_recovered_replace_existing = replace_existing

        msg = f"Matched {matched_files}/{total} node(s) to a GIF already in that folder."
        details = []
        if name_mismatch:
            details.append(
                f"{name_mismatch} file(s) had a number whose node doesn't currently have that "
                f"name -- skipped (wrong file, or the .xmind file/sheets/\"Replace existing\" "
                f"setting changed since that run).")
        if dup_index_skipped:
            details.append(f"{dup_index_skipped} file(s) shared a number with one already "
                           f"matched -- only the first found was used.")
        if unmatched_files:
            details.append(f"{unmatched_files} file(s) in that folder didn't look like a GFM "
                           f"Automatic Search download at all -- ignored.")
        if details:
            msg += "\n\n" + "\n".join(details)
        msg += (f"\n\nNext time you press Automatic Search (with these same sheets and setting "
               f"still checked), it will skip these {matched_files} node(s) and only search "
               f"the remaining {total - matched_files}.")
        messagebox.showinfo("Load & Resume", msg)
        self.status_var.set(f"Load & Resume: matched {matched_files}/{total} node(s) from folder.")

    # ── "🔍 Search GIFs" -- GFM's counterpart to IFM's own "🔍 Search
    # Images" button: opens GifSearchDialog, the real visible-browser
    # "Open Browser & Search There" flow (mini-browser session, injected
    # in-page "Extract images" button, thumbnail preview grid) that
    # ImageSearchDialog already gives IFM, just engine-picking (google /
    # pinterest / google_pinterest) instead of website-picking and
    # downloading via wie_download_gif (raw bytes, no PIL re-encode)
    # instead of wie_download_and_convert -- see GifSearchDialog's own
    # docstring/comment block just above its class definition. ──
    def _search_gfm_gifs(self):
        def _on_ready(paths, temp_dir):
            added = 0
            for p in paths:
                if p not in self.gfm_gif_pool:
                    self.gfm_gif_pool.append(p)
                    added += 1
            if temp_dir and temp_dir not in self._gfm_search_temp_dirs:
                self._gfm_search_temp_dirs.append(temp_dir)
            self._update_gif_pool_status()
            self.status_var.set(f"Added {added} GIF(s) from search to the GFM pool.")
        GifSearchDialog(self.root, _on_ready, dialog_title="GFM Section")

    # ── Sheet checklist -- mirrors _rebuild_ifm_sheet_checklist /
    # _on_ifm_sheet_output_toggle / _ifm_included_sheet_indices /
    # _ifm_included_output_sheet_indices one-for-one, against GFM's own
    # AMX Section fields. ──
    def _rebuild_gfm_sheet_checklist(self, sheets: List[str]):
        GFM_BG, GFM_FG, GFM_MUTED, GFM_SELECT = "#3d1e4e", "#ffffff", "#d9b3f0", "#9b59b6"
        for w in self.gfm_sheets_frame.winfo_children():
            w.destroy()
        self.gfm_loaded_xmind_sheets = list(sheets)
        self.gfm_sheet_output_vars = []
        self.gfm_sheet_include_vars = []
        self.gfm_sheet_search_checks = []
        if not sheets:
            tk.Label(self.gfm_sheets_frame, text="(load a file above)",
                     bg=GFM_BG, fg=GFM_MUTED, font=("Helvetica", 8, "italic")).pack(anchor="w")
            return
        only_one = len(sheets) == 1
        for i, name in enumerate(sheets):
            row = tk.Frame(self.gfm_sheets_frame, bg=GFM_BG)
            row.pack(fill=tk.X, anchor="w")
            out_var = tk.BooleanVar(value=True)
            search_var = tk.BooleanVar(value=True)
            self.gfm_sheet_output_vars.append(out_var)
            self.gfm_sheet_include_vars.append(search_var)
            out_cb = tk.Checkbutton(row, text="\U0001F4C4", variable=out_var,
                           state=(tk.DISABLED if only_one else tk.NORMAL),
                           bg=GFM_BG, fg=GFM_FG, activebackground=GFM_BG,
                           selectcolor=GFM_SELECT, font=("Helvetica", 8))
            out_cb.pack(side=tk.LEFT)
            search_cb = tk.Checkbutton(row, text="\U0001F50D", variable=search_var,
                           command=self._refresh_gfm_level_counts,
                           bg=GFM_BG, fg=GFM_FG, activebackground=GFM_BG,
                           selectcolor=GFM_SELECT, font=("Helvetica", 8))
            search_cb.pack(side=tk.LEFT)
            self.gfm_sheet_search_checks.append(search_cb)
            tk.Label(row, text=name, bg=GFM_BG, fg=GFM_FG, font=("Helvetica", 8),
                     wraplength=210, justify=tk.LEFT).pack(side=tk.LEFT, anchor="w")
            out_var.trace_add("write", lambda *_a, i=i: self._on_gfm_sheet_output_toggle(i))

    def _on_gfm_sheet_output_toggle(self, i: int):
        if i >= len(self.gfm_sheet_output_vars):
            return
        included = self.gfm_sheet_output_vars[i].get()
        search_var = self.gfm_sheet_include_vars[i]
        search_cb = self.gfm_sheet_search_checks[i]
        if not included:
            search_var.set(False)
            search_cb.config(state=tk.DISABLED)
        else:
            search_cb.config(state=tk.NORMAL)
            search_var.set(True)
        self._refresh_gfm_level_counts()

    def _gfm_included_sheet_indices(self) -> List[int]:
        output_included = set(self._gfm_included_output_sheet_indices())
        included = [i for i, v in enumerate(self.gfm_sheet_include_vars)
                    if v.get() and i in output_included]
        if included:
            return included
        first_output = self._gfm_included_output_sheet_indices()
        return [first_output[0]] if first_output else [0]

    def _gfm_included_output_sheet_indices(self) -> List[int]:
        included = [i for i, v in enumerate(self.gfm_sheet_output_vars) if v.get()]
        return included or [0]

    def _refresh_gfm_level_counts(self):
        total, level_counts = 0, {}
        if self.gfm_loaded_xmind_path:
            total, level_counts = self._xmind_file_level_counts(
                self.gfm_loaded_xmind_path, self._gfm_included_sheet_indices())
        self._update_xmind_level_counts_widget(
            self.gfm_level_counts_frame, self.gfm_level_count_labels,
            self.gfm_total_nodes_var, "#3d1e4e", "#d9b3f0", total, level_counts)

    def _gfm_gather_multi_sheet_targets(self, path: str, sheet_indices: List[int],
                                        include_existing: bool = False
                                        ) -> Tuple[List[Dict[str, Any]], List[str], List[int]]:
        """GFM's counterpart to _ifm_gather_multi_sheet_targets -- reuses
        _ifm_dfs_targets / _ifm_addressed_terms directly since both are
        already fully generic (no ifm-specific state)."""
        all_dfs: List[Dict[str, Any]] = []
        all_terms: List[str] = []
        sheet_sizes: List[int] = []
        for idx in sheet_indices:
            tree = self._xmind_extract_tree(path, idx)
            dfs_nodes = self._ifm_dfs_targets(tree, include_existing=include_existing) if tree else []
            terms = self._ifm_addressed_terms(dfs_nodes) if dfs_nodes else []
            all_dfs.extend(dfs_nodes)
            all_terms.extend(terms)
            sheet_sizes.append(len(dfs_nodes))
        return all_dfs, all_terms, sheet_sizes

    def _gfm_gather_search_targets(self, include_existing: bool = False
                                   ) -> Optional[Tuple[List[Dict[str, Any]], List[str],
                                                        List[int], List[int]]]:
        """GFM's counterpart to _ifm_gather_search_targets -- same
        AMX Section / Text Area (Condensed Data) branch, against GFM's
        own dropdown and AMX state."""
        source = self.gfm_node_source_var.get() if hasattr(self, "gfm_node_source_var") else "AMX Section"

        if source == "Text Area (Condensed Data)":
            raw = self.input_text.get("1.0", tk.END).strip()
            if not raw:
                messagebox.showinfo(
                    "Nothing To Search",
                    "The text area is empty -- paste or write your hierarchy text there "
                    "first, or switch the dropdown above to \"AMX Section\".")
                return None
            try:
                tree = HierarchyParser(raw).build_tree()
            except Exception as e:
                messagebox.showerror(
                    "Can't Parse Text Area",
                    f"The text area's hierarchy text couldn't be parsed: {e}")
                return None
            if not tree:
                messagebox.showinfo(
                    "Nothing To Search",
                    "The text area doesn't contain a valid hierarchy yet -- it must start "
                    "with lvl1[1].")
                return None
            dfs_nodes = self._ifm_dfs_targets(tree, include_existing=include_existing)
            terms = self._ifm_addressed_terms(dfs_nodes) if dfs_nodes else []
            return dfs_nodes, terms, [0], [len(dfs_nodes)]

        if not self.gfm_loaded_xmind_path:
            messagebox.showinfo(
                "No File Loaded",
                "Load an .xmind file in the GFM \U0001F4C2 AMX Section above first -- "
                "Automatic Search reads that file's node names to know what to look up. "
                "Or switch the \"Search node names from\" dropdown above to \"Text Area "
                "(Condensed Data)\" to search the node names in the main hierarchy text "
                "box instead.")
            return None
        sheet_indices = self._gfm_included_sheet_indices()
        dfs_nodes, terms, sheet_sizes = self._gfm_gather_multi_sheet_targets(
            self.gfm_loaded_xmind_path, sheet_indices, include_existing=include_existing)
        return dfs_nodes, terms, sheet_indices, sheet_sizes

    def _load_gfm_xmind(self):
        path = filedialog.askopenfilename(
            title="Load an .xmind File to Paste GIFs Into",
            filetypes=[("XMind", "*.xmind"), ("All", "*.*")])
        if not path:
            return
        try:
            sheets = list_xmind_sheets(path)
        except Exception as e:
            messagebox.showerror("Load Failed", str(e))
            return
        if not sheets:
            messagebox.showerror("Load Failed", "That .xmind file has no sheets.")
            return
        self.gfm_loaded_xmind_path = path
        self.gfm_auto_search_positional_gifs = None
        self.gfm_auto_search_source_path = None
        self.gfm_auto_search_sheet_indices = None
        self.gfm_auto_search_replace_existing = None
        self.gfm_recovered_positional = None
        self.gfm_recovered_terms = None
        self.gfm_recovered_sheet_indices = None
        self.gfm_recovered_replace_existing = None
        self._rebuild_gfm_sheet_checklist(sheets)
        sheet_note = (f"{len(sheets)} sheets found -- all checked below." if len(sheets) > 1
                      else "1 sheet.")
        self.gfm_loaded_xmind_status_var.set(
            f"Loaded: {os.path.basename(path)} ({sheet_note})")
        self.status_var.set(f"Loaded {os.path.basename(path)} for GFM GIF pasting")
        self._refresh_gfm_level_counts()

    def _clear_gfm_xmind(self):
        self.gfm_loaded_xmind_path = None
        self.gfm_auto_search_positional_gifs = None
        self.gfm_auto_search_source_path = None
        self.gfm_auto_search_sheet_indices = None
        self.gfm_auto_search_replace_existing = None
        self.gfm_recovered_positional = None
        self.gfm_recovered_terms = None
        self.gfm_recovered_sheet_indices = None
        self.gfm_recovered_replace_existing = None
        self._rebuild_gfm_sheet_checklist([])
        self.gfm_loaded_xmind_status_var.set(
            "No file loaded -- load the .xmind app you want GIFs pasted into.")
        self.status_var.set("Cleared GFM's loaded .xmind file")
        self._refresh_gfm_level_counts()

    def _gfm_pool_images_for_source(self, source: Optional[str] = None) -> List[str]:
        """GFM's counterpart to _ifm_pool_images_for_source."""
        if source is None:
            source = self.gfm_node_source_var.get() if hasattr(self, "gfm_node_source_var") else "AMX Section"
        tags = getattr(self, "gfm_auto_gif_source", None) or {}
        return [p for p in self.gfm_gif_pool
                if tags.get(p, source) == source]

    def _gfm_get_positional_gifs_if_valid(self) -> Optional[List[Optional[str]]]:
        """GFM's counterpart to _ifm_get_positional_images_if_valid."""
        mapping = self.gfm_auto_search_positional_gifs
        if not mapping or _norm_path(self.gfm_auto_search_source_path) != _norm_path(self.gfm_loaded_xmind_path):
            return None
        sheet_indices = self._gfm_included_sheet_indices()
        if self.gfm_auto_search_sheet_indices != sheet_indices:
            return None
        replace_existing = self.gfm_replace_existing_var.get()
        if self.gfm_auto_search_replace_existing != replace_existing:
            return None
        dfs_nodes, _terms, _sizes = self._gfm_gather_multi_sheet_targets(
            self.gfm_loaded_xmind_path, sheet_indices, include_existing=replace_existing)
        if len(dfs_nodes) != len(mapping):
            return None
        return mapping

    def _gfm_get_positional_gifs_for_text_if_valid(
            self, tree: Dict[str, Any], replace_existing: bool) -> Optional[List[Optional[str]]]:
        """GFM's counterpart to _ifm_get_positional_images_for_text_if_valid."""
        mapping = self.gfm_auto_search_positional_gifs
        if not mapping:
            print("[GFM Text Area] positional mapping unavailable -- no Automatic Search run has "
                  "completed for this text yet; falling back to the flat GIF pool.")
            return None
        if self.gfm_auto_search_source_path is not None:
            print("[GFM Text Area] positional mapping discarded -- it belongs to an AMX Section "
                  f"file ({self.gfm_auto_search_source_path!r}), not the Text Area; falling back "
                  "to the flat GIF pool.")
            return None
        if self.gfm_auto_search_sheet_indices != [0]:
            print("[GFM Text Area] positional mapping discarded -- its recorded sheet indices "
                  f"{self.gfm_auto_search_sheet_indices!r} != [0]; falling back to the flat GIF "
                  "pool.")
            return None
        if self.gfm_auto_search_replace_existing != replace_existing:
            print("[GFM Text Area] positional mapping discarded -- it was searched with "
                  f"\"Replace existing images\"={self.gfm_auto_search_replace_existing!r}, current "
                  f"checkbox is {replace_existing!r}; falling back to the flat GIF pool.")
            return None
        dfs_nodes = self._ifm_dfs_targets(tree, include_existing=replace_existing)
        if len(dfs_nodes) != len(mapping):
            print(f"[GFM Text Area] positional mapping discarded -- it has {len(mapping)} entries "
                  f"but the current text now walks to {len(dfs_nodes)} target node(s); falling "
                  "back to the flat GIF pool.")
            return None
        found = sum(1 for p in mapping if p)
        print(f"[GFM Text Area] positional mapping OK -- using it as-is "
              f"({found}/{len(mapping)} node(s) have a GIF, the rest stay unimaged).")
        return mapping

    def _gfm_build_and_paste_text_xmind(self, output_path: str) -> Tuple[str, int]:
        """GFM's counterpart to _ifm_build_and_paste_text_xmind."""
        raw = self.input_text.get("1.0", tk.END)
        if not raw.strip():
            raise ValueError("The text area is empty -- paste your hierarchy text there first.")
        raw = self._apply_heading_tags(raw)
        (level_colors, color_mode, layout, map_bg, note_heading, note_bold,
         eq_fmt, eq_override_flags, eq_design) = self._get_config()
        xmind_bytes = build_xmind_bytes(raw, layout=layout, level_colors=level_colors,
                                        color_mode=color_mode, map_bg=map_bg, note_heading=note_heading,
                                        default_img_fmt=eq_fmt, eq_override_flags=eq_override_flags,
                                        eq_design=eq_design, floating_config=None)
        out_dir = os.path.dirname(os.path.abspath(output_path))
        if out_dir:
            os.makedirs(out_dir, exist_ok=True)
        with open(output_path, "wb") as f:
            f.write(xmind_bytes)

        tree = self._xmind_extract_tree(output_path, 0)
        if not tree:
            raise ValueError("Could not read back the mindmap just built from the text area.")
        replace_existing = self.gfm_replace_existing_var.get()
        positional = self._gfm_get_positional_gifs_for_text_if_valid(tree, replace_existing)
        image_paths = ([] if positional is not None
                        else self._gfm_pool_images_for_source("Text Area (Condensed Data)"))
        if positional is None:
            print(f"[GFM Text Area] no positional mapping in use -- placing from the flat pool "
                  f"({len(image_paths)} GIF(s) available, allow_cycling=False, so each is used "
                  "on at most one node and in target-node order, not necessarily the node it was "
                  "originally downloaded for).")
        if positional is None and not image_paths:
            raise ValueError(
                "No GIFs loaded -- run \U0001F916 Automatic Search above (with this dropdown set to "
                "\"Text Area (Condensed Data)\"), or load GIFs via \U0001F39E Load GIFs / "
                "\U0001F4C1 Load Folder, first.")
        result_path, placed = inject_images_into_xmind_nodes(
            output_path, output_path, image_paths, sheet_index=0,
            positional_image_paths=positional,
            img_width=self.gfm_img_width_var.get(),
            img_height=self.gfm_img_height_var.get(),
            skip_nodes_with_image=not replace_existing,
            size_assignment=(list(self.gfm_size_assignment)
                              if positional is None and self.gfm_random_size_var.get()
                              and self.gfm_size_assignment else None),
            allow_cycling=False)
        return result_path, placed

    def _gfm_guard(self) -> bool:
        """GFM's counterpart to _ifm_guard."""
        if not self.gfm_enabled_var.get():
            messagebox.showwarning("GFM Disabled",
                                    "Enable the GFM switch at the top of the GIF for Mindmap section first.")
            return False
        source = self.gfm_node_source_var.get() if hasattr(self, "gfm_node_source_var") else "AMX Section"
        if source == "Text Area (Condensed Data)":
            raw = self.input_text.get("1.0", tk.END).strip()
            if not raw:
                messagebox.showinfo("Nothing To Do",
                                     "The text area is empty -- paste or write your hierarchy text there first.")
                return False
            try:
                tree = HierarchyParser(raw).build_tree()
            except Exception as e:
                messagebox.showerror("Can't Parse Text Area",
                                      f"The text area's hierarchy text couldn't be parsed: {e}")
                return False
            if not tree:
                messagebox.showinfo("Nothing To Do",
                                     "The text area doesn't contain a valid hierarchy yet -- it must start "
                                     "with lvl1[1].")
                return False
            replace_existing = self.gfm_replace_existing_var.get()
            positional = self._gfm_get_positional_gifs_for_text_if_valid(tree, replace_existing)
            if not self._gfm_pool_images_for_source("Text Area (Condensed Data)") and not positional:
                messagebox.showinfo("No GIFs Loaded",
                                     "Run \U0001F916 Automatic Search above first (with this dropdown set to "
                                     "\"Text Area (Condensed Data)\"), or load GIFs via \U0001F39E Load "
                                     "GIFs / \U0001F4C1 Load Folder.")
                return False
            return True
        if not self.gfm_loaded_xmind_path:
            messagebox.showinfo("No File Loaded",
                                 "Load an .xmind file in the GFM \U0001F4C2 AMX Section above first -- "
                                 "that's the app whose nodes the GIFs below get pasted into. Or switch "
                                 "the \"Search node names from\" dropdown above to \"Text Area (Condensed "
                                 "Data)\" to paste straight into the main hierarchy text box instead.")
            return False
        if not self._gfm_pool_images_for_source("AMX Section") and not self._gfm_get_positional_gifs_if_valid():
            messagebox.showinfo("No GIFs Loaded",
                                 "Load at least one GIF (\U0001F39E Load GIFs / \U0001F4C1 Load Folder), "
                                 "or run \U0001F916 Automatic Search option, above first.")
            return False
        return True

    def _gfm_filter_output_sheets(self, result_path: str, output_indices: List[int]) -> str:
        """GFM's counterpart to _ifm_filter_output_sheets."""
        if len(output_indices) >= len(self.gfm_loaded_xmind_sheets):
            return result_path
        tmp_path = result_path + ".gfm_sheets_tmp"
        os.replace(result_path, tmp_path)
        try:
            return _xmind_filter_sheets(tmp_path, result_path, output_indices)
        finally:
            try:
                os.remove(tmp_path)
            except OSError:
                pass

    def _gfm_preview(self):
        if not self._gfm_guard():
            return
        source = self.gfm_node_source_var.get() if hasattr(self, "gfm_node_source_var") else "AMX Section"
        if source == "Text Area (Condensed Data)":
            path = os.path.join(tempfile.gettempdir(), f"mindmap_preview_{uuid.uuid4().hex}.xmind")
            try:
                result_path, placed = self._gfm_build_and_paste_text_xmind(path)
            except Exception as e:
                messagebox.showerror("Preview Failed", str(e))
                return
            if not self._open_and_autodelete(result_path, self._gfm_delay.seconds):
                return
            self.status_var.set(f"GFM preview opened: pasted {placed} GIF(s) into nodes")
            return
        positional = self._gfm_get_positional_gifs_if_valid()
        sheet_indices = self._gfm_included_sheet_indices()
        replace_existing = self.gfm_replace_existing_var.get()
        _dfs, _terms, sheet_sizes = self._gfm_gather_multi_sheet_targets(
            self.gfm_loaded_xmind_path, sheet_indices, include_existing=replace_existing)
        path = os.path.join(tempfile.gettempdir(), f"mindmap_preview_{uuid.uuid4().hex}.xmind")
        try:
            result_path, placed = self._ifm_inject_multi_sheet(
                self.gfm_loaded_xmind_path, path, sheet_indices, sheet_sizes,
                [] if positional is not None else self._gfm_pool_images_for_source("AMX Section"),
                positional_image_paths=positional,
                img_width=self.gfm_img_width_var.get(),
                img_height=self.gfm_img_height_var.get(),
                skip_nodes_with_image=not replace_existing,
                size_assignment=(list(self.gfm_size_assignment)
                                  if positional is None and self.gfm_random_size_var.get()
                                  and self.gfm_size_assignment else None))
            result_path = self._gfm_filter_output_sheets(
                result_path, self._gfm_included_output_sheet_indices())
        except Exception as e:
            messagebox.showerror("Preview Failed", str(e))
            return
        if not self._open_and_autodelete(result_path, self._gfm_delay.seconds):
            return
        self.status_var.set(f"GFM preview opened: pasted {placed} GIF(s) into nodes")

    def _gfm_export(self):
        if not self._gfm_guard():
            return
        source = self.gfm_node_source_var.get() if hasattr(self, "gfm_node_source_var") else "AMX Section"
        if source == "Text Area (Condensed Data)":
            initial_name = "mindmap_with_gifs.xmind"
            try:
                raw = self.input_text.get("1.0", tk.END)
                root_node = HierarchyParser(raw).build_tree()
                if root_node and root_node.get("title"):
                    initial_name = root_node["title"] + "_with_gifs.xmind"
            except Exception:
                pass
            out_path = filedialog.asksaveasfilename(
                title="Save Mindmap with Pasted GIFs As",
                defaultextension=".xmind",
                filetypes=[("XMind", "*.xmind"), ("All", "*.*")],
                initialfile=initial_name)
            if not out_path:
                return
            try:
                result_path, placed = self._gfm_build_and_paste_text_xmind(out_path)
            except Exception as e:
                messagebox.showerror("Export Failed", str(e))
                return
            self.status_var.set(
                f"GFM: exported {placed} GIF(s) pasted into nodes -- {os.path.basename(result_path)}")
            if self.gfm_open_after_export_var.get():
                self._open_file_external(result_path)
            return
        out_path = filedialog.asksaveasfilename(
            title="Save Mindmap with Pasted GIFs As",
            defaultextension=".xmind",
            filetypes=[("XMind", "*.xmind"), ("All", "*.*")],
            initialfile=os.path.splitext(os.path.basename(self.gfm_loaded_xmind_path))[0] + "_with_gifs.xmind")
        if not out_path:
            return
        positional = self._gfm_get_positional_gifs_if_valid()
        sheet_indices = self._gfm_included_sheet_indices()
        replace_existing = self.gfm_replace_existing_var.get()
        _dfs, _terms, sheet_sizes = self._gfm_gather_multi_sheet_targets(
            self.gfm_loaded_xmind_path, sheet_indices, include_existing=replace_existing)
        try:
            result_path, placed = self._ifm_inject_multi_sheet(
                self.gfm_loaded_xmind_path, out_path, sheet_indices, sheet_sizes,
                [] if positional is not None else self._gfm_pool_images_for_source("AMX Section"),
                positional_image_paths=positional,
                img_width=self.gfm_img_width_var.get(),
                img_height=self.gfm_img_height_var.get(),
                skip_nodes_with_image=not replace_existing,
                size_assignment=(list(self.gfm_size_assignment)
                                  if positional is None and self.gfm_random_size_var.get()
                                  and self.gfm_size_assignment else None))
            result_path = self._gfm_filter_output_sheets(
                result_path, self._gfm_included_output_sheet_indices())
        except Exception as e:
            messagebox.showerror("Export Failed", str(e))
            return
        self.status_var.set(f"GFM: exported {placed} GIF(s) pasted into nodes -- {os.path.basename(result_path)}")
        if self.gfm_open_after_export_var.get():
            self._open_file_external(result_path)

    def _randomize_gfm_sizes(self):
        total = max(1, len(self.gfm_gif_pool))
        max_w = max(100, self.gfm_img_width_var.get())
        max_h = max(50, self.gfm_img_height_var.get())
        self.gfm_size_assignment = [
            (random.randint(100, max_w), random.randint(50, max_h)) for _ in range(total)
        ]
        self.gfm_random_size_var.set(True)
        self.status_var.set(f"GFM GIF sizes randomized ({total}): 100-{max_w}w \u00d7 50-{max_h}h")

    # ── Green "busy" spinner + live status line -- mirrors
    # _ifm_spinner_tick/_animate/_start/_stop one-for-one against GFM's
    # own canvas/status var. _ifm_fmt_duration is reused directly
    # (it's a @staticmethod with no ifm-specific state). ──
    def _gfm_spinner_tick(self):
        try:
            c = self.gfm_spinner_canvas
            c.delete("all")
            self._gfm_spinner_angle = (self._gfm_spinner_angle + 30) % 360
            c.create_arc(2, 2, 16, 16, start=self._gfm_spinner_angle, extent=100,
                         outline="#2ecc71", width=3, style="arc")
        except tk.TclError:
            pass

    def _gfm_spinner_animate(self):
        if not self._gfm_spinner_active:
            return
        self._gfm_spinner_tick()
        self.root.after(80, self._gfm_spinner_animate)

    def _gfm_spinner_start(self, status: str = "Searching ..."):
        self._gfm_spinner_active = True
        try:
            self.gfm_auto_status_var.set(status)
        except tk.TclError:
            pass
        self._gfm_spinner_animate()

    def _gfm_spinner_stop(self, status: str = ""):
        self._gfm_spinner_active = False
        try:
            self.gfm_spinner_canvas.delete("all")
            self.gfm_auto_status_var.set(status)
        except tk.TclError:
            pass

    def _gfm_auto_tick_timer(self, win: tk.Toplevel):
        try:
            if not win.winfo_exists():
                return
            elapsed = time.time() - self._gfm_auto_start_time
            with self._gfm_auto_progress_lock:
                processed = self._gfm_auto_total_processed
                remaining = self._gfm_auto_current_batch_remaining
            text = f"Elapsed: {self._ifm_fmt_duration(elapsed)}"
            if processed > 0 and remaining > 0:
                eta = (elapsed / processed) * remaining
                text += f"  |  Est. remaining: ~{self._ifm_fmt_duration(eta)}"
            win.timer_var.set(text)
        except tk.TclError:
            return
        if getattr(self, "_gfm_auto_search_running", False):
            self.root.after(1000, lambda: self._gfm_auto_tick_timer(win))

    def _gfm_get_max_retry_passes(self) -> int:
        try:
            n = int(self.gfm_auto_retries_var.get())
        except (ValueError, tk.TclError):
            n = 10
        n = max(0, n)
        self.gfm_auto_retries_var.set(str(n))
        return n

    def _gfm_auto_log(self, win: tk.Toplevel, msg: str):
        def _do():
            try:
                if not win.winfo_exists():
                    return
                win.log_box.configure(state=tk.NORMAL)
                win.log_box.insert(tk.END, msg + "\n")
                overflow = int(float(win.log_box.index(tk.END))) - 1 - self._GFM_AUTO_LOG_MAX_LINES
                if overflow > 0:
                    win.log_box.delete("1.0", f"{overflow + 1}.0")
                win.log_box.see(tk.END)
                win.log_box.configure(state=tk.DISABLED)
            except tk.TclError:
                pass
        self.root.after(0, _do)

    def _gfm_auto_file_log(self, msg: str, timestamp: bool = True):
        if not getattr(self, "_gfm_auto_log_file_path", None) or \
                getattr(self, "_gfm_auto_log_file_broken", False):
            return
        now = time.time()
        line = (f"[{time.strftime('%H:%M:%S', time.localtime(now))}."
               f"{int((now % 1) * 1000):03d}] {msg}\n") if timestamp else (msg + "\n")
        try:
            with self._gfm_auto_log_file_lock:
                with open(self._gfm_auto_log_file_path, "a", encoding="utf-8") as f:
                    f.write(line)
        except Exception as e:
            self._gfm_auto_log_file_broken = True
            print(f"[GFM Auto Search] WARNING: log file write failed ({e}) -- "
                 "continuing without a log file for the rest of this run.")

    def _toggle_gfm_prewarm_browsers(self):
        """GFM's counterpart to _toggle_ifm_prewarm_browsers -- shares the
        SAME underlying pool (wie_prewarm_auto_search_pool /
        wie_close_auto_search_pool / wie_get_prewarmed_contexts /
        wie_verify_auto_search_pool) IFM's button does -- opening browsers
        here also makes them available to an IFM run and vice versa, since
        both just want N pre-launched, verified Chromium contexts to pull
        from. Tracked separately (_gfm_browsers_prewarmed / gfm_prewarm_
        btn) only so each section's own button reflects its own click."""
        if getattr(self, "_gfm_auto_search_running", False):
            return
        if getattr(self, "_gfm_browsers_prewarmed", False):
            self.gfm_prewarm_btn.config(state=tk.DISABLED, text="Closing browsers ...")

            def _do_close():
                wie_close_auto_search_pool(log=lambda m: print(f"[GFM Auto Search] {m}"))
                self.root.after(0, _finish_close)

            def _finish_close():
                self._gfm_browsers_prewarmed = False
                self.gfm_prewarm_btn.config(state=tk.NORMAL, text="\U0001F310  Open Browsers",
                                            bg="#16a085", activebackground="#1abc9c")

            threading.Thread(target=_do_close, daemon=True).start()
        else:
            try:
                num_browsers = max(1, int(self.gfm_auto_browsers_var.get()))
            except (ValueError, tk.TclError):
                num_browsers = 1
            self.gfm_prewarm_btn.config(state=tk.DISABLED, text="Opening browsers ...")

            def _do_open():
                try:
                    wie_prewarm_auto_search_pool(
                        num_browsers, log=lambda m: print(f"[GFM Auto Search] {m}"))
                    verified = wie_verify_auto_search_pool(
                        log=lambda m: print(f"[GFM Auto Search] {m}"))
                except Exception as e:
                    print(f"[GFM Auto Search] Pre-launching browser(s) failed -- {e}")
                    verified = 0
                self.root.after(0, lambda: _finish_open(verified, num_browsers))

            def _finish_open(verified: int, requested: int):
                if verified >= 1:
                    self._gfm_browsers_prewarmed = True
                    label = (f"\U0001F310  Close Browsers ({verified})" if verified == requested
                             else f"\U0001F310  Close Browsers ({verified}/{requested} opened)")
                    self.gfm_prewarm_btn.config(state=tk.NORMAL, text=label,
                                                bg="#c0392b", activebackground="#e74c3c")
                    if verified < requested:
                        messagebox.showwarning(
                            "Some Browsers Failed To Open",
                            f"Only {verified} of {requested} browser(s) opened and passed their "
                            "startup check. Automatic Search can still use the "
                            f"{verified} that did -- but you asked for {requested} in the "
                            "\"Parallel browsers\" box above, so it'll fall back to launching "
                            "fresh ones for a full match if you start a search with that count.")
                else:
                    wie_close_auto_search_pool()
                    self._gfm_browsers_prewarmed = False
                    self.gfm_prewarm_btn.config(state=tk.NORMAL, text="\U0001F310  Open Browsers")
                    messagebox.showerror(
                        "Browser Launch Failed",
                        "Couldn't pre-launch the browser(s) -- make sure Playwright/Chromium is "
                        "installed (pip install playwright && playwright install chromium). "
                        "Check the terminal/console output for the exact error.")

            threading.Thread(target=_do_open, daemon=True).start()

    def _start_gfm_auto_search(self):
        if getattr(self, "_gfm_auto_search_running", False):
            messagebox.showinfo("Already Running", "An automatic search is already in progress.")
            return
        search_source = self.gfm_node_source_var.get() if hasattr(self, "gfm_node_source_var") else "AMX Section"
        self._sync_gfm_random_candidate_flag()  # M3-165
        self._sync_auto_search_show_browser_flag()  # M3-166
        replace_existing = self.gfm_replace_existing_var.get()
        gathered = self._gfm_gather_search_targets(include_existing=replace_existing)
        if gathered is None:
            return
        dfs_nodes, terms, sheet_indices, sheet_sizes = gathered
        if not dfs_nodes:
            messagebox.showinfo("Nothing To Do",
                                 "Every node in the checked sheet(s) already has an image "
                                 "(or no sheets are checked below). Tick \"Replace images "
                                 "already in the file\" above to search for those too.")
            return
        try:
            num_browsers = max(1, int(self.gfm_auto_browsers_var.get()))
        except (ValueError, tk.TclError):
            num_browsers = 1
        self.gfm_auto_browsers_var.set(str(num_browsers))
        max_retry_passes = self._gfm_get_max_retry_passes()
        engine = self._gfm_engine_key()

        initial_positional = None
        recovered_count = 0
        if (getattr(self, "gfm_recovered_positional", None) is not None
                and getattr(self, "gfm_recovered_terms", None) == terms
                and getattr(self, "gfm_recovered_sheet_indices", None) == sheet_indices
                and getattr(self, "gfm_recovered_replace_existing", None) == replace_existing):
            initial_positional = list(self.gfm_recovered_positional)
            recovered_count = sum(1 for p in initial_positional if p)

        browser_desc = ("one at a time, using a hidden browser (no windows will pop up)"
                        if num_browsers == 1 else
                        f"using {num_browsers} hidden browsers running at once, to go faster")
        sheet_desc = (f" across the {len(sheet_indices)} checked sheets"
                     if len(sheet_indices) > 1 else "")
        recovered_desc = (f"\n\n{recovered_count} of these already have a GIF recovered via "
                          f"\"Load & Resume\" and won't be re-searched -- only the remaining "
                          f"{len(terms) - recovered_count} will actually be looked up."
                          if recovered_count else "")
        if not messagebox.askyesno(
                "Automatic Search",
                f"This will search {_GFM_ENGINE_LABELS.get(engine, engine)} for each of the "
                f"{len(terms)} node name(s){sheet_desc} below, {browser_desc}, and download the "
                f"first usable GIF for each. Node names that repeat elsewhere in the mindmap are "
                f"automatically qualified with their parent (and grandparent, etc. as needed) so "
                f"each search stays aimed at the right node.{recovered_desc}\n\n"
                "This can take a while for a large mindmap. Continue?"):
            return

        if initial_positional is not None:
            self.gfm_recovered_positional = None
            self.gfm_recovered_terms = None
            self.gfm_recovered_sheet_indices = None
            self.gfm_recovered_replace_existing = None

        self._gfm_auto_stop_event = threading.Event()
        self._gfm_auto_search_running = True
        self.gfm_prewarm_btn.config(state=tk.DISABLED)

        log_dir = os.path.join(os.path.expanduser("~"), ".webpage_image_extractor",
                               "gfm_auto_search_logs")
        try:
            os.makedirs(log_dir, exist_ok=True)
        except Exception:
            log_dir = tempfile.gettempdir()
        log_file_path = os.path.join(
            log_dir, f"gfm_auto_search_{time.strftime('%Y%m%d_%H%M%S')}.txt")

        win = self._build_gfm_auto_search_window(
            len(terms), log_file_path, num_browsers=num_browsers, terms=terms,
            sheet_indices=sheet_indices, replace_existing=replace_existing,
            max_retry_passes=max_retry_passes, search_source=search_source, engine=engine)
        threading.Thread(target=self._run_gfm_auto_search,
                         args=(terms, win, num_browsers, max_retry_passes, sheet_indices,
                               replace_existing, log_file_path),
                         kwargs={"initial_positional": initial_positional,
                                 "search_source": search_source, "engine": engine},
                         daemon=True).start()

    def _build_gfm_auto_search_window(self, total: int, log_file_path: Optional[str] = None,
                                      num_browsers: int = 1, terms: Optional[List[str]] = None,
                                      sheet_indices: Optional[List[int]] = None,
                                      replace_existing: bool = False,
                                      max_retry_passes: Optional[int] = None,
                                      search_source: str = "AMX Section",
                                      engine: str = "google") -> tk.Toplevel:
        win = tk.Toplevel(self.root)
        win.title("Automatic Search -- GFM Section")
        win.configure(bg="#1e1e1e")
        win.geometry("560x420")
        win.protocol("WM_DELETE_WINDOW", lambda: None)

        win.gfm_terms = terms
        win.gfm_sheet_indices = sheet_indices
        win.gfm_replace_existing = replace_existing
        win.gfm_max_retry_passes = max_retry_passes
        win.gfm_search_source = search_source
        win.gfm_engine = engine

        tk.Label(win, text=f"Searching {total} node name(s) one by one ...", bg="#1e1e1e",
                 fg="#ffffff", font=("Helvetica", 10, "bold")).pack(anchor="w", padx=10, pady=(10, 4))

        win.timer_var = tk.StringVar(value="Elapsed: 0:00")
        tk.Label(win, textvariable=win.timer_var, bg="#1e1e1e", fg="#a0a0a0",
                 font=("Helvetica", 8)).pack(anchor="w", padx=10, pady=(0, 4))

        if num_browsers > 1:
            browsers_row = tk.Frame(win, bg="#1e1e1e")
            browsers_row.pack(fill=tk.X, padx=10, pady=(0, 4))
            tk.Label(browsers_row, text="Active browsers:", bg="#1e1e1e", fg="#a0a0a0",
                     font=("Helvetica", 8)).pack(side=tk.LEFT)
            win.active_browsers_var = tk.StringVar(value=str(num_browsers))
            browsers_spin = tk.Spinbox(browsers_row, from_=1, to=num_browsers, width=4,
                                       textvariable=win.active_browsers_var,
                                       font=("Helvetica", 8), justify=tk.CENTER)
            browsers_spin.pack(side=tk.LEFT, padx=(6, 6))

            def _apply_active_browsers():
                try:
                    requested = int(win.active_browsers_var.get())
                except (ValueError, tk.TclError):
                    requested = self._gfm_auto_active_browsers_limit[0]
                current = self._gfm_auto_active_browsers_limit[0]
                clamped = max(1, min(requested, current))
                win.active_browsers_var.set(str(clamped))
                if clamped == current:
                    return
                self._gfm_auto_active_browsers_limit[0] = clamped
                msg = (f"Active browsers reduced to {clamped} -- browser(s) above that count "
                       f"will finish their current search, then stop picking up new ones.")
                self._gfm_auto_log(win, msg)
                print(f"[GFM Auto Search] {msg}")
                self._gfm_auto_file_log(f"-- {msg} --")

            tk.Button(browsers_row, text="Apply", command=_apply_active_browsers,
                     bg="#0984e3", fg="#ffffff", relief=tk.FLAT, cursor="hand2",
                     font=("Helvetica", 8)).pack(side=tk.LEFT)
            tk.Label(browsers_row, text="(can only be lowered, not raised back up)",
                     bg="#1e1e1e", fg="#636e72", font=("Helvetica", 7)).pack(side=tk.LEFT, padx=(8, 0))
            win.active_browsers_spin = browsers_spin

        if log_file_path:
            log_path_row = tk.Frame(win, bg="#1e1e1e")
            log_path_row.pack(fill=tk.X, padx=10, pady=(0, 4))
            tk.Label(log_path_row, text="Log file:", bg="#1e1e1e", fg="#a0a0a0",
                     font=("Helvetica", 8)).pack(side=tk.LEFT)
            log_path_entry = tk.Entry(log_path_row, font=("Consolas", 8), fg="#dcdcdc",
                                      bg="#111111", relief=tk.FLAT, insertbackground="#dcdcdc")
            log_path_entry.insert(0, log_file_path)
            log_path_entry.configure(state="readonly", readonlybackground="#111111")
            log_path_entry.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=(6, 6))
            open_log_btn = tk.Button(log_path_row, text="Open Log File",
                                     command=lambda: self._open_file_external(log_file_path),
                                     bg="#0984e3", fg="#ffffff", relief=tk.FLAT, cursor="hand2",
                                     font=("Helvetica", 8))
            open_log_btn.pack(side=tk.RIGHT)
            win.log_path_entry = log_path_entry

        prog = ttk.Progressbar(win, maximum=max(total, 1), value=0)
        prog.pack(fill=tk.X, padx=10, pady=(0, 8))

        log_box = tk.Text(win, height=16, bg="#111111", fg="#dcdcdc", font=("Consolas", 9), wrap="word")
        log_box.pack(fill=tk.BOTH, expand=True, padx=10, pady=(0, 8))
        log_box.configure(state=tk.DISABLED)

        btn_row = tk.Frame(win, bg="#1e1e1e")
        btn_row.pack(fill=tk.X, padx=10, pady=(0, 10))
        stop_btn = tk.Button(btn_row, text="Stop", command=lambda: self._gfm_auto_stop_event.set(),
                             bg="#e74c3c", fg="#ffffff", relief=tk.FLAT, cursor="hand2")
        stop_btn.pack(side=tk.LEFT)
        resume_btn = tk.Button(btn_row, text="Resume", state=tk.DISABLED,
                               command=lambda: self._resume_gfm_auto_search(win),
                               bg="#27ae60", fg="#ffffff", relief=tk.FLAT, cursor="hand2")
        resume_btn.pack(side=tk.LEFT, padx=(6, 0))
        close_btn = tk.Button(btn_row, text="Close", state=tk.DISABLED, command=win.destroy,
                              bg="#636e72", fg="#ffffff", relief=tk.FLAT, cursor="hand2")
        close_btn.pack(side=tk.RIGHT)

        win.progress = prog
        win.log_box = log_box
        win.stop_btn = stop_btn
        win.resume_btn = resume_btn
        win.close_btn = close_btn
        return win

    def _run_gfm_auto_search(self, terms: List[str], win: tk.Toplevel, num_browsers: int = 1,
                             max_retry_passes: Optional[int] = None,
                             sheet_indices: Optional[List[int]] = None,
                             replace_existing: bool = False,
                             log_file_path: Optional[str] = None,
                             initial_positional: Optional[List[Optional[str]]] = None,
                             search_source: str = "AMX Section",
                             engine: str = "google"):
        """GFM's counterpart to _run_ifm_auto_search -- same main-pass +
        retry-passes + resume + prewarmed-pool + progress-window/log-file
        machinery, dispatching through _gfm_run_auto_search_pool /
        _gfm_search_and_download_one (engine-selectable, raw GIF bytes)
        instead of _wie_run_auto_search_pool / _wie_search_and_download_one
        (fixed Google Images, PIL-converted to a fixed format). See
        _run_ifm_auto_search's own (much longer) docstring for the full
        reasoning behind every piece of bookkeeping below -- unchanged
        here, just against GFM's own state fields."""
        self._gfm_auto_log_file_path = log_file_path
        self._gfm_auto_log_file_lock = threading.Lock()
        self._gfm_auto_log_file_broken = False
        if max_retry_passes is None:
            max_retry_passes = self._GFM_AUTO_SEARCH_MAX_RETRY_PASSES
        min_size = 0
        shrink_to, output_format = self._gfm_shrink_and_format_args()
        total = len(terms)
        out_dir = tempfile.mkdtemp(prefix="xmind_gfm_autosearch_")
        _WIE_TEMP_DIRS.append(out_dir)
        self._gfm_search_temp_dirs.append(out_dir)

        num_browsers = max(1, min(int(num_browsers or 1), total if total else 1))
        self._gfm_auto_active_browsers_limit = [num_browsers]
        self._gfm_auto_active_browsers_original = num_browsers

        prewarmed_ctxs = (wie_get_prewarmed_contexts(num_browsers)
                          if getattr(self, "_gfm_browsers_prewarmed", False) else None)
        if prewarmed_ctxs:
            rig_desc = (f"{len(prewarmed_ctxs)} pre-opened Chromium instance(s), headless -- "
                       "no cold-launch wait")
        else:
            rig_desc = "Chromium, headless" if num_browsers == 1 else \
                f"{num_browsers} independent Chromium instances, headless, running in parallel"
        engine_label = _GFM_ENGINE_LABELS.get(engine, engine)
        print(f"[GFM Auto Search] Starting automatic search for {total} node name(s) ({rig_desc}) "
              f"via {engine_label} ...")
        self._gfm_auto_log(win, f"Starting search for {total} node name(s) using {rig_desc} "
                                f"via {engine_label}.")
        if log_file_path:
            self._gfm_auto_log(win, f"Log file: {log_file_path}")

        header = "\n".join([
            "=" * 78,
            "GFM Automatic Search -- run log",
            f"Started:            {time.strftime('%Y-%m-%d %H:%M:%S')}",
            f"Node names to find: {total}",
            f"Browser rig:        {rig_desc}",
            f"Search engine:      {engine_label}",
            f"Max retry passes:   {max_retry_passes}",
            f"Sheets included:    {sheet_indices if sheet_indices else [0]}",
            f"Replace existing:   {replace_existing}",
            f"Search node source: {search_source}",
            f"Source .xmind:      "
            f"{self.gfm_loaded_xmind_path if search_source != 'Text Area (Condensed Data)' else '(none -- searched from the Text Area hierarchy)'}",
            f"Downloaded-GIF temp folder: {out_dir}",
            "=" * 78,
            "",
        ])
        self._gfm_auto_file_log(header, timestamp=False)

        self._gfm_auto_start_time = time.time()
        self._gfm_auto_progress_lock = threading.Lock()
        self._gfm_auto_total_processed = 0
        self._gfm_auto_current_batch_remaining = total
        self._gfm_auto_run_loaded_count = 0
        self.root.after(0, lambda: self._gfm_auto_tick_timer(win))

        if initial_positional is not None and len(initial_positional) == total:
            positional: List[Optional[str]] = list(initial_positional)
        else:
            positional: List[Optional[str]] = [None] * total
        carried_over_count = sum(1 for p in positional if p)

        last_errors: Dict[int, str] = {}
        attempts_count: Dict[int, int] = {}
        pass_resolved: Dict[int, str] = {}
        all_failure_categories: Dict[str, int] = {}

        existing_image_paths = set(self.gfm_gif_pool)

        run_seen_hashes: set = set()
        run_hash_lock = threading.Lock()

        def run_batch(term_items: List[Tuple[int, str]], on_result, item_delay: float = 0.0,
                     stagger: float = min(1.5, 0.4 * num_browsers),
                     min_request_interval: float = 0.35):
            if num_browsers <= 1:
                ctx0 = prewarmed_ctxs[0] if prewarmed_ctxs else None
                remaining = list(term_items)
                for pos, (index, term) in enumerate(remaining):
                    if self._gfm_auto_stop_event.is_set():
                        for j_index, j_term in remaining[pos:]:
                            on_result(j_index, j_term, None, RuntimeError("stopped by user"))
                        return
                    if item_delay > 0 and pos > 0:
                        self._gfm_auto_stop_event.wait(item_delay)
                        if self._gfm_auto_stop_event.is_set():
                            for j_index, j_term in remaining[pos:]:
                                on_result(j_index, j_term, None, RuntimeError("stopped by user"))
                            return
                    searching_msg = f"[{index}/{total}] Searching \"{term}\" ..."
                    self._gfm_auto_log(win, searching_msg)
                    print(f"[GFM Auto Search] {searching_msg}")
                    self._gfm_auto_file_log(f"[{index}/{total}] Searching \"{term}\" ...")

                    def _console(m, index=index):
                        print(f"[GFM Auto Search] [{index}/{total}] {m}")
                        self._gfm_auto_file_log(f"    [{index}/{total}] {m}")

                    t0 = time.time()
                    try:
                        path = _gfm_auto_search_download(term, out_dir, index, engine, min_size=min_size,
                                                         timeout=25, log=_console, prewarmed_context=ctx0,
                                                         seen_hashes=run_seen_hashes,
                                                         hash_lock=run_hash_lock,
                                                         shrink_to=shrink_to, output_format=output_format)
                        on_result(index, term, path, None, elapsed=time.time() - t0, worker_id=0)
                    except Exception as e:
                        on_result(index, term, None, e, elapsed=time.time() - t0, worker_id=0)
            else:
                def _pool_log(m):
                    print(f"[GFM Auto Search] {m}")
                    self._gfm_auto_file_log(f"    {m}")
                current_num_browsers = max(1, min(
                    num_browsers, self._gfm_auto_active_browsers_limit[0]))
                _gfm_run_auto_search_pool(
                    list(term_items), num_browsers=current_num_browsers, out_dir=out_dir, engine=engine,
                    min_size=min_size, timeout=25, stop_event=self._gfm_auto_stop_event,
                    on_result=on_result, log=_pool_log,
                    prewarmed_contexts=prewarmed_ctxs, stagger=stagger, item_delay=item_delay,
                    min_request_interval=min_request_interval,
                    seen_hashes=run_seen_hashes, hash_lock=run_hash_lock,
                    active_limit_getter=lambda: self._gfm_auto_active_browsers_limit[0],
                    shrink_to=shrink_to, output_format=output_format)

        def make_dispatcher(batch_items: List[Tuple[int, str]], is_main: bool, label: str = "",
                            pass_name: str = "main"):
            # M3-161 fix: see the matching comment in IFM's own
            # make_dispatcher -- logging used to wait for every earlier
            # index in the batch to report first (flush_ready), so one
            # slow straggler held up every already-finished later item's
            # log line until it finally resolved, making the window look
            # frozen even though GIFs were still landing on disk. Each
            # result is now logged the instant it arrives, and the
            # progress bar/status advance off a monotonic high-water mark
            # (largest index seen) instead of the just-arrived index, so
            # out-of-order completions can't make it jump backward.
            total_batch = len(batch_items)
            handled: set = set()
            lock = threading.Lock()
            items_by_index = dict(batch_items)
            high_water = [0]

            def on_result(index, term, path, err, elapsed=None, worker_id=None):
                with lock:
                    if index in handled:
                        return
                    handled.add(index)
                    attempts_count[index] = attempts_count.get(index, 0) + 1
                    if path:
                        positional[index - 1] = path
                        last_errors.pop(index, None)
                        pass_resolved[index] = pass_name
                        if path not in existing_image_paths:
                            existing_image_paths.add(path)
                            self.gfm_gif_pool.append(path)
                            self.gfm_auto_gif_source[path] = search_source
                    elif err is not None:
                        last_errors[index] = str(err)
                        category = _gfm_categorize_search_error(str(err))
                        all_failure_categories[category] = all_failure_categories.get(category, 0) + 1
                    remaining_in_batch = total_batch - len(handled)
                    if index > high_water[0]:
                        high_water[0] = index
                    display_index = high_water[0]
                with self._gfm_auto_progress_lock:
                    self._gfm_auto_total_processed += 1
                    self._gfm_auto_current_batch_remaining = remaining_in_batch
                    if path:
                        self._gfm_auto_run_loaded_count += 1

                def _flush(index=index, path=path, err=err, elapsed=elapsed,
                          worker_id=worker_id, display_index=display_index):
                    term_for_index = items_by_index.get(index, "?")
                    tag = f" (browser {worker_id})" if worker_id else ""
                    timing = f" [{elapsed:.2f}s]" if elapsed is not None else ""
                    if err is not None:
                        self._gfm_auto_log(win, f"{label}[{index}/{total}] Skipped -- {err}")
                        print(f"[GFM Auto Search] {label}[{index}/{total}] Skipped -- {err}")
                        self._gfm_auto_file_log(
                            f"{label}[{index}/{total}] FAILED  \"{term_for_index}\"{tag}{timing} "
                            f"-- {err}")
                    elif path:
                        self._gfm_auto_log(win, f"{label}[{index}/{total}] Saved {os.path.basename(path)}")
                        print(f"[GFM Auto Search] {label}[{index}/{total}] Found it -- downloaded "
                              f"{os.path.basename(path)}")
                        self._gfm_auto_file_log(
                            f"{label}[{index}/{total}] SUCCESS \"{term_for_index}\"{tag}{timing} "
                            f"-- saved {os.path.basename(path)}")
                        self._update_gif_pool_status()
                    if is_main:
                        try:
                            if win.winfo_exists():
                                win.progress["value"] = display_index
                        except tk.TclError:
                            pass
                        nxt = min(display_index + 1, total)
                        self.gfm_auto_status_var.set(
                            f"Searching {nxt}/{total} ..." if display_index < total else "Finishing up ...")

                self.root.after(0, _flush)

            return on_result

        try:
            main_items = [(i, t) for i, t in enumerate(terms, start=1) if positional[i - 1] is None]
            if carried_over_count:
                carry_msg = (f"Resuming -- {carried_over_count}/{total} node(s) already have a "
                             f"GIF from the earlier run and won't be re-searched.")
                self._gfm_auto_log(win, carry_msg)
                print(f"[GFM Auto Search] {carry_msg}")
                self._gfm_auto_file_log(f"-- {carry_msg} --")
            try:
                run_batch(main_items, make_dispatcher(main_items, is_main=True), item_delay=0.4)
            except Exception as e:
                main_pass_err_msg = (
                    f"Main pass hit an unexpected error and stopped early ({e}) -- "
                    f"whatever wasn't found yet will still go through the normal "
                    f"retry passes below instead of the run just quietly ending here.")
                self._gfm_auto_log(win, main_pass_err_msg)
                print(f"[GFM Auto Search] {main_pass_err_msg}")
                self._gfm_auto_file_log(f"-- {main_pass_err_msg} --")
                self.root.after(0, lambda m=main_pass_err_msg: self.gfm_auto_status_var.set(m))

            for attempt in range(1, max_retry_passes + 1):
                if self._gfm_auto_stop_event.is_set():
                    break
                retry_indices = [i for i in range(1, total + 1) if positional[i - 1] is None]
                if not retry_indices:
                    break
                blocked_now = [i for i in retry_indices
                              if _gfm_categorize_search_error(last_errors.get(i, "")) ==
                              "blocked by Google (verification/CAPTCHA page)"]
                if blocked_now and attempt > 1:
                    cooldown = min(60.0, 15.0 * attempt)
                    cooldown_msg = (f"{len(blocked_now)} node(s) were blocked last "
                                    f"attempt -- waiting {cooldown:.0f}s before retrying them ...")
                    self._gfm_auto_log(win, cooldown_msg)
                    print(f"[GFM Auto Search] {cooldown_msg}")
                    self._gfm_auto_file_log(f"-- {cooldown_msg} --")
                    self.root.after(0, lambda m=cooldown_msg: self.gfm_auto_status_var.set(m))
                    if self._gfm_auto_stop_event.wait(cooldown):
                        break
                retry_items = [(i, terms[i - 1]) for i in retry_indices]
                retry_msg = (f"Retrying {len(retry_items)} node(s) that didn't find a GIF yet "
                             f"(attempt {attempt}/{max_retry_passes}) ...")
                self._gfm_auto_log(win, retry_msg)
                print(f"[GFM Auto Search] {retry_msg}")
                self._gfm_auto_file_log(f"-- {retry_msg} --")
                self.root.after(0, lambda m=retry_msg: self.gfm_auto_status_var.set(m))
                with self._gfm_auto_progress_lock:
                    self._gfm_auto_current_batch_remaining = len(retry_items)
                retry_delay = min(10.0, 2.0 * attempt)
                retry_min_interval = min(2.0, 0.35 + 0.25 * attempt)
                run_batch(retry_items, make_dispatcher(
                    retry_items, is_main=False, label=f"retry {attempt}/"
                    f"{max_retry_passes} ", pass_name=f"retry {attempt}"), item_delay=retry_delay,
                    min_request_interval=retry_min_interval)
        finally:
            self._gfm_auto_search_running = False
            self._gfm_auto_run_loaded_count = None
            self.root.after(0, self._update_gif_pool_status)
            saved = sum(1 for p in positional if p)
            self.gfm_auto_search_positional_gifs = positional
            self.gfm_auto_search_source_path = (
                None if search_source == "Text Area (Condensed Data)" else self.gfm_loaded_xmind_path)
            self.gfm_auto_search_sheet_indices = list(sheet_indices) if sheet_indices else [0]
            self.gfm_auto_search_replace_existing = replace_existing
            win.gfm_last_positional = list(positional)
            win.gfm_last_num_browsers = self._gfm_auto_active_browsers_limit[0]
            done_msg = f"Done -- {saved}/{total} GIF(s) downloaded and added to GFM's GIF pool."
            if saved < total:
                done_msg += f" {total - saved} node(s) never found a usable GIF and will be left unimaged."
            self._gfm_auto_log(win, done_msg)
            print(f"[GFM Auto Search] {done_msg}")
            self._gfm_auto_file_log(f"-- {done_msg} --", timestamp=False)
            self.root.after(0, lambda m=done_msg: self.gfm_auto_status_var.set(m))
            self._gfm_spinner_stop("")

            failed_indices = [i for i in range(1, total + 1) if not positional[i - 1]]
            stopped_early = self._gfm_auto_stop_event.is_set()
            summary_lines = ["-" * 78, "Run summary:",
                             f"  Total nodes:     {total}",
                             f"  Downloaded:      {saved}",
                             f"  Still unimaged:  {len(failed_indices)}",
                             f"  Stopped by user: {stopped_early}"]
            if all_failure_categories:
                summary_lines.append("  Failure categories (across every attempt):")
                for cat, n in sorted(all_failure_categories.items(), key=lambda kv: -kv[1]):
                    summary_lines.append(f"    {cat}: {n}")
            if failed_indices:
                summary_lines.append("")
                summary_lines.append("Failed node names (still unimaged at the end of this run):")
                for i in failed_indices:
                    reason = last_errors.get(i, "stopped by user" if stopped_early else "unknown reason")
                    attempts_made = attempts_count.get(i, 0)
                    summary_lines.append(
                        f"  [{i}/{total}] \"{terms[i - 1]}\" -- {attempts_made} attempt(s) -- {reason}")
            summary_lines.append("-" * 78)
            self._gfm_auto_file_log("\n".join(summary_lines), timestamp=False)

            def _finish():
                try:
                    if win.winfo_exists():
                        win.stop_btn.config(state=tk.DISABLED)
                        win.close_btn.config(state=tk.NORMAL)
                        if failed_indices:
                            win.resume_btn.config(state=tk.NORMAL)
                        else:
                            win.resume_btn.config(state=tk.DISABLED)
                        win.protocol("WM_DELETE_WINDOW", win.destroy)
                except tk.TclError:
                    pass
                try:
                    self.gfm_prewarm_btn.config(state=tk.NORMAL)
                except tk.TclError:
                    pass
            self.root.after(0, _finish)

    def _resume_gfm_auto_search(self, win: tk.Toplevel):
        """GFM's counterpart to _resume_ifm_auto_search."""
        if getattr(self, "_gfm_auto_search_running", False):
            messagebox.showinfo("Already Running", "An automatic search is already in progress.")
            return
        previous_positional = getattr(win, "gfm_last_positional", None)
        terms = getattr(win, "gfm_terms", None)
        if not terms or previous_positional is None or len(previous_positional) != len(terms):
            messagebox.showerror("Can't Resume",
                                 "This window's run details are no longer available -- start a "
                                 "new Automatic Search instead.")
            return
        missing = sum(1 for p in previous_positional if not p)
        if missing == 0:
            messagebox.showinfo("Nothing To Resume", "Every node already has a GIF.")
            try:
                win.resume_btn.config(state=tk.DISABLED)
            except tk.TclError:
                pass
            return
        num_browsers = max(1, int(getattr(win, "gfm_last_num_browsers", 1) or 1))
        max_retry_passes = getattr(win, "gfm_max_retry_passes", None)
        sheet_indices = getattr(win, "gfm_sheet_indices", None)
        replace_existing = getattr(win, "gfm_replace_existing", False)
        search_source = getattr(win, "gfm_search_source", "AMX Section")
        engine = getattr(win, "gfm_engine", "google")

        self._gfm_auto_stop_event = threading.Event()
        self._gfm_auto_search_running = True
        self.gfm_prewarm_btn.config(state=tk.DISABLED)

        try:
            if win.winfo_exists():
                win.stop_btn.config(state=tk.NORMAL)
                win.resume_btn.config(state=tk.DISABLED)
                win.close_btn.config(state=tk.DISABLED)
                win.protocol("WM_DELETE_WINDOW", lambda: None)
                win.progress["value"] = len(terms) - missing
                if hasattr(win, "active_browsers_spin"):
                    win.active_browsers_var.set(str(num_browsers))
                    win.active_browsers_spin.config(to=num_browsers)
        except tk.TclError:
            pass

        resume_msg = f"Resuming -- {missing}/{len(terms)} node(s) still need a GIF."
        self._gfm_auto_log(win, resume_msg)
        print(f"[GFM Auto Search] {resume_msg}")

        log_dir = os.path.join(os.path.expanduser("~"), ".webpage_image_extractor",
                               "gfm_auto_search_logs")
        try:
            os.makedirs(log_dir, exist_ok=True)
        except Exception:
            log_dir = tempfile.gettempdir()
        log_file_path = os.path.join(
            log_dir, f"gfm_auto_search_{time.strftime('%Y%m%d_%H%M%S')}_resumed.txt")
        if hasattr(win, "log_path_entry"):
            try:
                win.log_path_entry.configure(state="normal")
                win.log_path_entry.delete(0, tk.END)
                win.log_path_entry.insert(0, log_file_path)
                win.log_path_entry.configure(state="readonly")
            except tk.TclError:
                pass

        threading.Thread(target=self._run_gfm_auto_search,
                         args=(terms, win, num_browsers, max_retry_passes, sheet_indices,
                               replace_existing, log_file_path),
                         kwargs={"initial_positional": previous_positional,
                                 "search_source": search_source, "engine": engine},
                         daemon=True).start()

    # ── Shared helpers: mousewheel auto-delete spinner, open+autodelete,
    #    open-after-export, and two-way checkbox syncing (RXF <-> section
    #    Enable switches) -- used by the main Export box, IFM, and RXF. ──
    def _sync_bool_vars(self, var_a: tk.BooleanVar, var_b: tk.BooleanVar):
        """Mirror two BooleanVars both ways without recursing on each
        other's writes. Used to keep RXF's F-Node/IFM checkboxes locked
        to the F-Node/IFM section's own Enable switch: toggle either one
        and the other follows -- ON turns the section on, OFF turns it
        off, in both directions."""
        def _from_a(*_):
            if self._rxf_sync_guard:
                return
            self._rxf_sync_guard = True
            try:
                if var_b.get() != var_a.get():
                    var_b.set(var_a.get())
            finally:
                self._rxf_sync_guard = False

        def _from_b(*_):
            if self._rxf_sync_guard:
                return
            self._rxf_sync_guard = True
            try:
                if var_a.get() != var_b.get():
                    var_a.set(var_b.get())
            finally:
                self._rxf_sync_guard = False

        var_a.trace_add("write", _from_a)
        var_b.trace_add("write", _from_b)

    def _link_dependent_enable_var(self, dependent_var: tk.BooleanVar, master_var: tk.BooleanVar):
        """One-way control (not a mirror): dependent_var (RXF's F-Node
        checkbox) fully drives master_var (the F-Node Section's own Enable
        switch) -- checking OR unchecking dependent_var sets master_var to
        match, every time. But master_var never drives dependent_var back --
        toggling the F-Node Section's own Enable switch (on or off) leaves
        RXF's F-Node checkbox exactly as it was. Only one trace is
        registered (on dependent_var); master_var has none, so there's
        nothing for it to trigger back to dependent_var in the first
        place. Uses the same _rxf_sync_guard as _sync_bool_vars so setting
        master_var here doesn't itself get treated as a fresh user action
        by any other trace on master_var (e.g. the IFM pair's)."""
        def _from_dependent(*_):
            if self._rxf_sync_guard:
                return
            self._rxf_sync_guard = True
            try:
                if master_var.get() != dependent_var.get():
                    master_var.set(dependent_var.get())
            finally:
                self._rxf_sync_guard = False

        dependent_var.trace_add("write", _from_dependent)

    def _build_autodelete_spinner(self, parent, initial_seconds: int = 30):
        """Build a mousewheel-driven auto-delete timer spinbox -- same
        widget/behavior as the main Export box's 'Auto-delete in'
        control -- and return a small holder with .seconds (current
        value, read by Preview at click-time) and .frame (pack this)."""
        frame = tk.Frame(parent, bg=self.colors["bg"])
        tk.Label(frame, text="\U0001F550 Auto-delete in ",
                 bg=self.colors["bg"], fg="#888888",
                 font=("Helvetica", 9)).pack(side=tk.LEFT)

        class _DelayHolder:
            pass
        holder = _DelayHolder()
        holder.seconds = initial_seconds
        holder.var = tk.StringVar(value=self._format_delay(initial_seconds))

        spin = tk.Spinbox(frame, width=14, textvariable=holder.var,
                          bg=self.colors["entry_bg"], fg="#000000",
                          font=("Consolas", 9), relief=tk.SOLID, bd=1,
                          state="readonly")
        spin.pack(side=tk.LEFT, padx=(2, 2))

        def _on_wheel(event):
            if event.delta > 0:
                holder.seconds = self._next_delay_up(holder.seconds)
            elif event.delta < 0:
                holder.seconds = self._next_delay_down(holder.seconds)
            holder.var.set(self._format_delay(holder.seconds))
            return "break"

        def _on_linux_up(event):
            holder.seconds = self._next_delay_up(holder.seconds)
            holder.var.set(self._format_delay(holder.seconds))
            return "break"

        def _on_linux_down(event):
            holder.seconds = self._next_delay_down(holder.seconds)
            holder.var.set(self._format_delay(holder.seconds))
            return "break"

        spin.bind("<MouseWheel>", _on_wheel)
        spin.bind("<Button-4>", _on_linux_up)
        spin.bind("<Button-5>", _on_linux_down)

        holder.frame = frame
        return holder

    def _open_file_external(self, path: str):
        try:
            if os.name == "nt":
                os.startfile(path)
            elif os.name == "posix":
                subprocess.Popen(["xdg-open", path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            else:
                subprocess.Popen(["open", path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except Exception as e:
            messagebox.showerror("Open Failed", f"Could not open the exported file: {e}")

    def _open_and_autodelete(self, path: str, delay_seconds: int) -> bool:
        """Open `path` in the OS default viewer and schedule its deletion
        after `delay_seconds` (same retry/backoff behavior as the main
        Preview button). Returns False (and shows an error) if the file
        could not be opened."""
        _register_temp(path)
        try:
            if os.name == "nt":
                os.startfile(path)
            elif os.name == "posix":
                subprocess.Popen(["xdg-open", path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            else:
                subprocess.Popen(["open", path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except Exception as e:
            messagebox.showerror("Open Failed", f"Could not open preview: {e}")
            try:
                os.remove(path)
            except OSError:
                pass
            return False

        def _cleanup():
            time.sleep(delay_seconds)
            for attempt, wait in enumerate((0, 2, 5, 10)):
                if wait:
                    time.sleep(wait)
                try:
                    if not os.path.exists(path):
                        return
                    os.remove(path)
                    self.root.after(0, lambda: self.status_var.set(
                        f"Preview deleted after {self._format_delay(delay_seconds)}"))
                    return
                except Exception as e:
                    if attempt == 3:
                        print(f"[Cleanup] Could not delete preview after retries: {e}", file=sys.stderr)

        threading.Thread(target=_cleanup, daemon=True).start()
        return True

    # ============================================================
    # RXF Section (Re-Building XMind Files)
    # ============================================================
    def _rxf_apply_strip(self, raw: str, level_colors: Optional[List[Dict[str, Any]]]):
        """Non-destructive counterpart to _strip_properties(): returns a
        stripped copy of the hierarchy text and level-color list for this
        rebuild only. The live editor text and the Levels Design
        Section's color rows are never touched."""
        strip_border = self.strip_border_var.get()
        strip_fill = self.strip_fill_var.get()
        strip_labels = self.strip_labels_var.get()
        strip_notes = self.strip_notes_var.get()
        strip_equation = self.strip_equation_var.get()

        if level_colors and (strip_border or strip_fill):
            level_colors = copy.deepcopy(level_colors)
            for lc in level_colors:
                if strip_border:
                    lc["border"] = ""
                    lc["border_opacity"] = 100
                if strip_fill:
                    lc["fill"] = ""
                    lc["fill_opacity"] = 100

        if strip_labels or strip_notes or strip_equation:
            if strip_labels:
                raw = re.sub(r'label:\s*"[^"]*"', '', raw)
            if strip_notes:
                raw = re.sub(r'note:\s*"[^"]*"', '', raw)
            if strip_equation:
                raw = re.sub(r'equation:\s*"[^"]*"', '', raw)
                raw = re.sub(r'eq_w:\s*\d+', '', raw)
                raw = re.sub(r'eq_h:\s*\d+', '', raw)
                raw = re.sub(r'eq_font:\s*\d+', '', raw)
                raw = re.sub(r'eq_color:\s*"[^"]*"', '', raw)
                raw = re.sub(r'eq_bg:\s*"[^"]*"', '', raw)
                raw = re.sub(r'img_fmt:\s*"?[^",}]*"?', '', raw)
            for _ in range(3):
                raw = re.sub(r'\{\s*,+\s*\}', '', raw)
                raw = re.sub(r',\s*\}', '}', raw)
                raw = re.sub(r'\{\s*,', '{', raw)
                raw = re.sub(r',\s*,', ',', raw)
                raw = re.sub(r'\{\s+', '{', raw)
                raw = re.sub(r'\s+\}', '}', raw)
            raw = re.sub(r'\{\s*\}', '', raw)

        return raw, level_colors

    def _rxf_apply_color_randomization(self, level_colors: Optional[List[Dict[str, Any]]]):
        """Non-destructive counterpart to _randomize_colors(), honoring
        the Color Capacity Section's ranges -- returns a randomized copy
        for this rebuild only; the live color rows are untouched."""
        if not level_colors:
            return level_colors
        randomize_pct = self.randomize_pct_var.get()
        out = []
        for lc in level_colors:
            lc = dict(lc)
            fill = f"#{random.randint(0,255):02x}{random.randint(0,255):02x}{random.randint(0,255):02x}"
            border = f"#{random.randint(0,255):02x}{random.randint(0,255):02x}{random.randint(0,255):02x}"
            line = f"#{random.randint(0,255):02x}{random.randint(0,255):02x}{random.randint(0,255):02x}"
            brightness = (int(fill[1:3], 16) * 299 + int(fill[3:5], 16) * 587 + int(fill[5:7], 16) * 114) / 1000
            text = "#ffffff" if brightness < 128 else "#000000"
            if random.random() < 0.1:
                text = "#000000" if text == "#ffffff" else "#ffffff"
            lc["fill"] = fill
            lc["border"] = border
            lc["line"] = line
            lc["text"] = text
            if randomize_pct:
                if self.cap_fill_chk.get():
                    lc["fill_opacity"] = random.randint(self.cap_fill_min.get(), self.cap_fill_max.get())
                else:
                    lc["fill_opacity"] = random.randint(20, 100)
                if self.cap_line_chk.get():
                    lc["line_opacity"] = random.randint(self.cap_line_min.get(), self.cap_line_max.get())
                else:
                    lc["line_opacity"] = random.randint(20, 100)
                if self.cap_border_chk.get():
                    lc["border_opacity"] = random.randint(self.cap_border_min.get(), self.cap_border_max.get())
                else:
                    lc["border_opacity"] = random.randint(20, 100)
            out.append(lc)
        return out

    def _rxf_toggle_add_sheets_options(self):
        """Shows/hides the "Add sheet from text area" / "Add sheets
        manually" pair under RXF's "Add sheets to xmind file" checkbox."""
        if self.rxf_add_sheets_var.get():
            self.rxf_add_sheets_options_frame.pack(fill=tk.X, pady=(2, 0))
        else:
            self.rxf_add_sheets_options_frame.pack_forget()

    def _rxf_toggle_add_sheets_from_text(self):
        """"Add sheet from text area" and "Add sheets manually" are
        mutually exclusive (radio-button-like) -- checking this one
        unchecks and hides the other's spinbox row."""
        if self.rxf_add_sheets_from_text_var.get():
            self.rxf_add_sheets_manual_var.set(False)
            self.rxf_add_sheets_manual_row.pack_forget()

    def _rxf_toggle_add_sheets_manual_spin(self):
        """Shows/hides the sheet-count spinbox under "Add sheets manually".
        Mutually exclusive with "Add sheet from text area" -- see
        _rxf_toggle_add_sheets_from_text."""
        if self.rxf_add_sheets_manual_var.get():
            self.rxf_add_sheets_from_text_var.set(False)
            self.rxf_add_sheets_manual_row.pack(fill=tk.X, padx=(18, 0), pady=(2, 4))
        else:
            self.rxf_add_sheets_manual_row.pack_forget()

    def _rxf_apply_add_sheets(self, path: str) -> None:
        """RXF's "Add sheets to xmind file" option -- runs as the very
        last step of _rxf_build (see the call site there) so newly
        appended sheets are never touched by Strip Properties / Level
        Design / Color Capacity / F-Node / IFM, all of which only ever
        target whichever sheet(s) already existed going into this
        rebuild.

        Appends, in order:
          1. If "Add sheet(s) from text area" is checked: one sheet per
             NON-BLANK sheet in the multi-sheet hierarchy text-area
             editor (tab strip) -- read live via _get_all_sheet_texts
             (so the active tab's unsaved edits are included). If every
             tab is blank, nothing is added (never an error).
          2. N blank, auto-numbered placeholder sheets if "Add sheets
             manually" is checked, continuing from the sheet count the
             file had BEFORE this step (e.g. a 3-sheet file + 4 picked
             in the spinbox -> new sheets named "4", "5", "6", "7").

        No-ops entirely if the parent checkbox, or both sub-checkboxes,
        are unchecked.

        Every appended sheet is added raw/unstyled -- no layout/
        level_colors/color_mode/map_bg/etc -- then its theme AND
        rootTopic structureClass are overwritten with the LAST sheet
        already in `path` going into this step (its "parent" sheet), so
        it visually blends into the file's existing look (same palette/
        background, same tree/org-chart/etc layout).
        """
        if not self.rxf_add_sheets_var.get():
            return
        from_text_on = self.rxf_add_sheets_from_text_var.get()
        manual_on = self.rxf_add_sheets_manual_var.get()
        if not (from_text_on or manual_on):
            return

        def _extract(xbytes: bytes) -> Tuple[List[Dict[str, Any]], Dict[str, bytes]]:
            with zipfile.ZipFile(io.BytesIO(xbytes), "r") as zin:
                content = json.loads(zin.read("content.json").decode("utf-8"))
                images = {name: zin.read(name) for name in zin.namelist()
                          if name not in ("content.json", "metadata.json", "manifest.json")}
            return content, images

        # Built one sheet at a time (rather than batched through a single
        # build_xmind_bytes_multi_sheet call) so a per-sheet parse
        # failure only skips that ONE sheet instead of risking
        # misaligning which built sheet corresponds to which original
        # tab. `styled` is always False here -- every text-area/manual
        # sheet is added raw/unstyled and blends into the parent sheet's
        # theme below; kept as a tuple element only because the
        # parent-theme-copy loop further down still checks it.
        built: List[Tuple[List[Dict[str, Any]], Dict[str, bytes], bool]] = []

        if from_text_on:
            # Every sheet in the multi-sheet hierarchy editor (tab
            # strip), not just whichever one happens to be active --
            # same _get_all_sheet_texts source the Eq Adjuster / IFM
            # Text Area / Main Export all already read from instead of
            # re-deriving this locally (see _get_all_sheet_texts's
            # docstring).
            for _name, raw in self._get_all_sheet_texts():
                if not raw.strip():
                    continue
                try:
                    # No layout/level_colors/color_mode/map_bg/note_
                    # heading/eq_* args here on purpose -- see
                    # docstring. Bare-default theme/structure, which
                    # gets overwritten below with the parent's actual
                    # theme/structure.
                    sheet_bytes = build_xmind_bytes_multi_sheet([("", raw)])
                except ValueError:
                    # This one sheet failed to parse -- skip only it, not
                    # the whole batch.
                    continue
                content, images = _extract(sheet_bytes)
                built.append((content, images, False))

        if manual_on:
            try:
                existing_count = len(list_xmind_sheets(path))
            except Exception:
                existing_count = 0
            count = max(0, self.rxf_add_sheets_count_var.get())
            for i in range(1, count + 1):
                n = existing_count + i
                try:
                    sheet_bytes = build_xmind_bytes_multi_sheet([(str(n), f"lvl1[1]{n}")])
                except ValueError:
                    continue
                content, images = _extract(sheet_bytes)
                built.append((content, images, False))

        if not built:
            return

        # The "parent" sheet each UNSTYLED new sheet copies its look
        # from: whichever sheet is LAST in the file at this point in the
        # rebuild (the one immediately preceding the sheets about to be
        # appended).
        try:
            with zipfile.ZipFile(path, "r") as zin:
                existing_content = json.loads(zin.read("content.json").decode("utf-8"))
        except Exception:
            existing_content = []
        parent_sheet = existing_content[-1] if existing_content else None
        parent_theme = parent_sheet.get("theme") if parent_sheet else None
        parent_structure = (parent_sheet.get("rootTopic", {}).get("structureClass")
                             if parent_sheet else None)

        mini_content: List[Dict[str, Any]] = []
        mini_images: Dict[str, bytes] = {}
        for content, images, styled in built:
            if not styled and parent_sheet:
                for sheet in content:
                    if parent_theme is not None:
                        sheet["theme"] = copy.deepcopy(parent_theme)
                    if parent_structure:
                        sheet.setdefault("rootTopic", {})["structureClass"] = parent_structure
            mini_content.extend(content)
            mini_images.update(images)

        tmp_out = path + ".rxf_addsheets_tmp"
        _xmind_append_sheets(path, tmp_out, mini_content, mini_images)
        os.replace(tmp_out, path)

    def _rxf_build(self, output_path: str) -> Tuple[str, int]:
        """Core rebuild: honors only the ticked RXF checkboxes. Raises
        ValueError with a user-facing message on any precondition
        failure. Returns (output_path, images_placed_by_ifm) -- the second
        element is always 0 now that RXF no longer pastes IFM images itself
        (see the "F-Node/IFM removed from RXF" note below); kept in the
        return signature so callers (_rxf_preview / _rxf_export) don't need
        to change."""
        # F-Node injection and IFM image-pasting used to be triggerable
        # from right here via RXF's own "F-Node Section" / "IFM Section" /
        # "Automatic search" checkboxes. Those were removed -- F-Nodes and
        # IFM images are now only ever added from their own respective
        # sections (F-Node Section's own Preview/Export, IFM Section's own
        # Preview/Export), never as an RXF rebuild step. RXF now only ever
        # handles Strip Properties / Level Design / Color Capacity /
        # "Add sheets to xmind file".

        # RXF's own loaded source file takes priority; fall back to the
        # F-Node AMX Section's loaded file if RXF has none of its own.
        rxf_source_path = self.rxf_loaded_xmind_path or self.loaded_xmind_path

        if rxf_source_path:
            # RXF's own loaded-file checklist (\U0001F4C4 Include /
            # \U0001F3A8 Apply changes) only exists for RXF's OWN loaded
            # file -- it has no meaning for the F-Node AMX Section's file
            # when RXF is only using it as a fallback (that section has no
            # such checklist of its own), so it's only consulted when
            # that's actually the file in play here.
            use_checklist = rxf_source_path == self.rxf_loaded_xmind_path
            included_indices: Optional[List[int]] = None
            style_indices: Optional[List[int]] = None

            # Apply exactly whichever of Strip Properties / Level Design /
            # Color Capacity are ticked -- nothing is required and nothing
            # unchecked is asked about.
            strip_on = self.rxf_strip_properties_var.get()
            level_design_on = self.rxf_level_design_var.get()
            color_capacity_on = self.rxf_color_design_var.get()
            # Color Capacity's color randomization has no colors of its
            # own to fall back to -- it only makes sense layered on top
            # of Level Design's per-level palette, so the color-overwrite
            # pass only touches fill/border/line when Level Design is
            # checked. Color Capacity's H1/Bold note formatting has
            # nothing to do with colors, so it's independent and can run
            # even with Level Design unchecked (checking only Color
            # Capacity must never silently re-color every topic the way
            # Level Design does).
            apply_colors = level_design_on
            use_h1 = color_capacity_on and self.note_heading_var.get()
            use_bold = color_capacity_on and self.note_bold_var.get()
            need_restyle = apply_colors or use_h1 or use_bold

            if use_checklist:
                included_indices = self._rxf_loaded_included_indices()
                if not included_indices:
                    raise ValueError(
                        "Every sheet was excluded from the rebuild -- check at least one "
                        "\U0001F4C4 box in the loaded file's sheet checklist.")
                style_indices = self._rxf_loaded_styled_indices()
                # Strip/restyle only actually have anything to do when at
                # least one included sheet has \U0001F3A8 Apply changes
                # checked -- if every row's Apply-changes box is
                # unchecked, skip both steps outright regardless of which
                # RXF checkboxes above are ticked, rather than running
                # them against an empty target list for no reason.
                if not style_indices:
                    strip_on = False
                    need_restyle = False

            # Dropping unincluded sheets has to run AFTER Strip/restyle
            # (which target sheets by their ORIGINAL index, matching the
            # checklist rows) and be the very last step before output --
            # same ordering reasoning as _xmind_append_sheets/
            # _xmind_filter_sheets elsewhere.
            need_filter = use_checklist and len(included_indices) < len(self.rxf_loaded_xmind_sheets)

            current_path = rxf_source_path
            tmp_files: List[str] = []

            # Whether a later step still needs to run after this one, so
            # each step knows whether to write straight to output_path
            # (last step) or stage into a temp file for the next step to
            # read from.
            more_after_strip = need_restyle or need_filter
            more_after_restyle = need_filter

            try:
                if strip_on:
                    strip_out = output_path + ".rxf_strip_tmp" if more_after_strip else output_path
                    apply_rxf_strip_style(
                        current_path, strip_out,
                        strip_border=self.strip_border_var.get(),
                        strip_fill=self.strip_fill_var.get(),
                        strip_labels=self.strip_labels_var.get(),
                        strip_notes=self.strip_notes_var.get(),
                        strip_fnodes=self.strip_fnodes_var.get(),
                        strip_fnode_images=self.strip_fnode_images_var.get(),
                        strip_ifm_images=self.strip_ifm_images_var.get(),
                        # None = every sheet, always (no checklist in
                        # play); otherwise only the checklist's
                        # \U0001F3A8-checked sheets.
                        sheet_index=style_indices if use_checklist else None)
                    if strip_out != output_path:
                        tmp_files.append(strip_out)
                    current_path = strip_out

                if need_restyle:
                    level_colors, color_mode, *_rest = self._get_config()
                    if color_capacity_on:
                        level_colors = self._rxf_apply_color_randomization(level_colors)
                    restyle_out = output_path + ".rxf_restyle_tmp" if more_after_restyle else output_path
                    apply_rxf_color_level_style(
                        current_path, restyle_out, level_colors, color_mode,
                        sheet_index=style_indices if use_checklist else None,
                        use_h1=use_h1,
                        use_bold=use_bold,
                        apply_colors=apply_colors)
                    if restyle_out != output_path:
                        tmp_files.append(restyle_out)
                    current_path = restyle_out

                if need_filter:
                    # Last step: drop every sheet whose \U0001F4C4 Include
                    # box was unchecked. Always writes straight to
                    # output_path -- nothing follows this.
                    _xmind_filter_sheets(current_path, output_path, keep_indices=included_indices)
                    current_path = output_path

                if current_path != output_path:
                    # Nothing above actually ran -- carry the source
                    # through unchanged.
                    shutil.copyfile(current_path, output_path)
            finally:
                for tmp in tmp_files:
                    try:
                        os.remove(tmp)
                    except OSError:
                        pass
        else:
            raw = self.input_text.get("1.0", tk.END)
            if not raw.strip():
                raise ValueError("Paste some hierarchy data first.")
            raw = self._apply_heading_tags(raw)

            level_colors, color_mode, layout, map_bg, note_heading, note_bold, eq_fmt, \
                eq_override_flags, eq_design = self._get_config()

            if self.rxf_strip_properties_var.get():
                raw, level_colors = self._rxf_apply_strip(raw, level_colors)

            # Color Capacity's randomization generates its own fresh
            # colors (it doesn't reuse Level Design's configured hex
            # values -- see _rxf_apply_color_randomization), so it must
            # still take effect even when Level Design itself is
            # unchecked; only fall back to "no color styling at all"
            # when neither box is ticked. Previously this order was
            # reversed and unconditionally nulled out level_colors
            # whenever Level Design was unchecked, silently discarding
            # Color Capacity's randomization even though it was ticked.
            if self.rxf_color_design_var.get():
                level_colors = self._rxf_apply_color_randomization(level_colors)
            elif not self.rxf_level_design_var.get():
                level_colors, color_mode = None, None

            try:
                xmind_bytes = build_xmind_bytes(
                    raw, layout=layout, level_colors=level_colors, color_mode=color_mode,
                    map_bg=map_bg, note_heading=note_heading, default_img_fmt=eq_fmt,
                    eq_override_flags=eq_override_flags, eq_design=eq_design)
            except Exception as e:
                raise ValueError(str(e))
            with open(output_path, "wb") as f:
                f.write(xmind_bytes)

        self._rxf_apply_add_sheets(output_path)

        return output_path, 0

    def _rxf_preview(self):
        if self.eq_adjust_frame is not None:
            self.eq_adjust_frame._close()
            self.eq_adjust_frame = None
        path = os.path.join(tempfile.gettempdir(), f"mindmap_preview_{uuid.uuid4().hex}.xmind")
        try:
            result_path, _placed = self._rxf_build(path)
        except Exception as e:
            messagebox.showerror("Preview Failed", str(e))
            self.status_var.set(f"Error: {e}")
            return
        if not self._open_and_autodelete(result_path, self._rxf_delay.seconds):
            return
        self.status_var.set("RXF preview opened")

    def _rxf_export(self):
        if self.eq_adjust_frame is not None:
            self.eq_adjust_frame._close()
            self.eq_adjust_frame = None
        out_path = filedialog.asksaveasfilename(
            title="RXF -- Save Rebuilt Mindmap As",
            defaultextension=".xmind",
            filetypes=[("XMind", "*.xmind"), ("All", "*.*")])
        if not out_path:
            return
        try:
            result_path, _placed = self._rxf_build(out_path)
        except Exception as e:
            messagebox.showerror("Export Failed", str(e))
            self.status_var.set(f"Error: {e}")
            return
        self.status_var.set(f"RXF exported: {os.path.basename(result_path)}")
        if self.rxf_open_after_export_var.get():
            self._open_file_external(result_path)

    def _select_float_axis(self, key: str):
        self.float_selected_axis = key
        a = self.float_axes[key]
        state = "ON" if a["en"].get() else "OFF"
        self.float_axis_title_var.set(f"Selected: {a['label']} ({state})")
        self.float_qty_spin.config(textvariable=a["qty"])

    def _draw_float_radar(self):
        c = self.float_canvas
        c.delete("all")
        cx, cy, r = 90, 90, 65
        c.create_oval(cx - r, cy - r, cx + r, cy + r, outline="#555555", width=1)
        c.create_oval(cx - r // 2, cy - r // 2, cx + r // 2, cy + r // 2, outline="#3a3a3a", width=1)
        c.create_oval(cx - 2, cy - 2, cx + 2, cy + 2, fill="#888888", outline="")
        for key, a in self.float_axes.items():
            ang = math.radians(a["angle"])
            length = 25 + min(60, a["spread"].get() / 25)
            ex = cx + length * math.cos(ang)
            ey = cy + length * math.sin(ang)
            on = a["en"].get()
            selected = (key == self.float_selected_axis)
            color = "#00b894" if on else "#666666"
            width = 4 if selected else 2
            c.create_line(cx, cy, ex, ey, fill=color, width=width, arrow=tk.LAST, tags=(key,))
            hr = 5
            c.create_oval(ex - hr, ey - hr, ex + hr, ey + hr,
                          fill=color, outline="#ffffff" if selected else "", tags=(key,))
            lx = cx + (length + 16) * math.cos(ang)
            ly = cy + (length + 16) * math.sin(ang)
            c.create_text(lx, ly, text=a["label"], fill=color,
                          font=("Helvetica", 8, "bold" if selected else "normal"), tags=(key,))

    def _on_float_canvas_press(self, event):
        cx, cy = 90, 90
        dx, dy = event.x - cx, event.y - cy
        dist = (dx * dx + dy * dy) ** 0.5
        if dist == 0:
            self._float_radar_drag = None
            self._float_radar_click_key = None
            return
        click_ang = math.degrees(math.atan2(dy, dx)) % 360
        best_key, best_diff = None, 999
        for key, a in self.float_axes.items():
            diff = abs(click_ang - a["angle"])
            diff = min(diff, 360 - diff)
            if diff < best_diff:
                best_diff, best_key = diff, key
        self._float_radar_click_key = best_key
        if best_key is None:
            self._float_radar_drag = None
            return
        a = self.float_axes[best_key]
        length = 25 + min(60, a["spread"].get() / 25)
        ang = math.radians(a["angle"])
        tip_x = cx + length * math.cos(ang)
        tip_y = cy + length * math.sin(ang)
        if ((event.x - tip_x) ** 2 + (event.y - tip_y) ** 2) ** 0.5 <= 12:
            self._float_radar_drag = best_key
        else:
            self._float_radar_drag = None

    def _on_float_canvas_drag(self, event):
        key = self._float_radar_drag
        if not key:
            return
        cx, cy = 90, 90
        dist = ((event.x - cx) ** 2 + (event.y - cy) ** 2) ** 0.5
        length = max(0.0, dist - 25)
        spread = max(0, min(5000, int(round(length * 25))))
        self.float_axes[key]["spread"].set(spread)
        self._draw_float_radar()

    def _on_float_canvas_release(self, event):
        if self._float_radar_drag:
            self._float_radar_drag = None
            return
        best_key = self._float_radar_click_key
        if best_key is None:
            return
        if best_key == self.float_selected_axis:
            a = self.float_axes[best_key]
            a["en"].set(not a["en"].get())
        self._select_float_axis(best_key)
        self._draw_float_radar()

    def _on_float_canvas_scroll(self, event, direction: Optional[int] = None):
        if direction is None:
            direction = 1 if event.delta > 0 else -1
        a = self.float_axes[self.float_selected_axis]
        a["qty"].set(max(0, a["qty"].get() + direction))
        return "break"

