    def _on_fng_inside_qty_edited(self, *_args):
        """Inside spinbox edited (split mode only, but harmless otherwise
        since the guard blocks this while _apply_fng_scope_quantities /
        _on_fng_total_qty_changed are driving it). Trades directly with
        Inline -- Quantity itself is never touched."""
        if self._fng_qty_sync_guard:
            return
        self._fng_qty_sync_guard = True
        try:
            total = max(5, self.fng_total_qty_var.get())
            inside = max(0, min(total, self.fng_inside_qty.get()))
            if self.fng_inside_qty.get() != inside:
                self.fng_inside_qty.set(inside)
            line = total - inside
            if self.fng_line_qty_var.get() != line:
                self.fng_line_qty_var.set(line)
            self._distribute_fng_edges_only(line)
        except (tk.TclError, ValueError):
            pass
        finally:
            self._fng_qty_sync_guard = False
        self._update_fng_qty_status()

    def _on_fng_line_qty_edited(self, *_args):
        """Inline (on-line total) spinbox edited (split mode only, same
        guard-based harmlessness as above). Trades directly with Inside --
        Quantity itself is never touched."""
        if self._fng_qty_sync_guard:
            return
        self._fng_qty_sync_guard = True
        try:
            total = max(5, self.fng_total_qty_var.get())
            line = max(0, min(total, self.fng_line_qty_var.get()))
            if self.fng_line_qty_var.get() != line:
                self.fng_line_qty_var.set(line)
            inside = total - line
            if self.fng_inside_qty.get() != inside:
                self.fng_inside_qty.set(inside)
            self._distribute_fng_edges_only(line)
        except (tk.TclError, ValueError):
            pass
        finally:
            self._fng_qty_sync_guard = False
        self._update_fng_qty_status()

    def _on_fng_edge_changed(self, *_args):
        """One of the 4 individual PMM-box-edge spinboxes (main panel) was
        edited directly. Keeps Quantity and Inline mirrored to the new
        edge total -- Inside is left exactly as it was."""
        if self._fng_qty_sync_guard:
            return
        self._fng_qty_sync_guard = True
        try:
            total = max(5, self._fng_parts_sum())
            if self.fng_total_qty_var.get() != total:
                self.fng_total_qty_var.set(total)
            line = sum(v.get() for v in self.fng_edge_qty.values())
            if self.fng_line_qty_var.get() != line:
                self.fng_line_qty_var.set(line)
        except (tk.TclError, ValueError):
            pass
        finally:
            self._fng_qty_sync_guard = False
        self._update_fng_qty_status()

    def _get_fng_config(self, manual_offsets=None, box_bounds=None) -> Dict[str, Any]:
        """Build the FnG (Floating-Nodes GIF) config -- same shape as
        _get_floating_config, but reads the FnG Section's own independent
        state (its own axes/qty/palette/gif pool/AMX file), so F-Node and
        FnG can each place their own floating nodes onto the same export
        without sharing or colliding on any of this state. manual_offsets/
        box_bounds default to the FnG AMX Section's own drag state
        (self.fng_manual_offsets/self.fng_box_bounds) when omitted."""
        axes = {}
        for key, a in self.fng_axes.items():
            axes[key] = {
                "angle": a["angle"],
                "enabled": a["en"].get(),
                "spread": a["spread"].get(),
                "qty": a["qty"].get(),
            }
        return {
            "axes": axes,
            "show_name": self.fng_name_var.get(),
            "fill_assignment": list(self.fng_fill_assignment),
            "border_assignment": list(self.fng_border_assignment),
            "fill_palette": list(self.fng_fill_palette),
            "border_palette": list(self.fng_border_palette),
            "no_fill": self.fng_no_fill_var.get(),
            "no_border": self.fng_no_border_var.get(),
            "images": list(self.fng_gifs),
            "dot_spacing": self.fng_dot_spacing_var.get(),
            "img_width": self.fng_img_width_var.get(),
            "img_height": self.fng_img_height_var.get(),
            "random_size": self.fng_random_size_var.get(),
            "size_assignment": list(self.fng_size_assignment),
            "origin_x": self.fng_origin_x_var.get(),
            "origin_y": self.fng_origin_y_var.get(),
            "box": dict(zip(("left","top","right","bottom"),
                            box_bounds if box_bounds is not None
                            else getattr(self, "fng_box_bounds", (-400.0,-300.0,400.0,300.0)))),
            "manual_offsets": dict(manual_offsets if manual_offsets is not None else self.fng_manual_offsets),
        }

    # ------------------------------------------------------------------
    # Combines the F-Node Section's config and the FnG Section's config
    # (each independently enabled/configured) into whatever
    # build_floating_topics()/build_xmind_bytes()/convert_to_xmind()/
    # inject_floating_topics_into_xmind() expect for their own
    # `floating_config` parameter -- a single config dict, a list of
    # them, or None. This is the ONE place Preview/Export/AMX-export
    # decide "which floating-node configs are actually active right
    # now" so F-Node and FnG can both contribute floating topics to the
    # same exported/previewed document without either section needing
    # to know the other exists.
    # ------------------------------------------------------------------
    def _floating_nodes_ready(self, enabled_var, axes) -> bool:
        return bool(enabled_var.get()) and any(
            a["en"].get() and a["qty"].get() > 0 for a in axes.values())

    def _get_combined_floating_config(self, manual_offsets=None, box_bounds=None,
                                      fng_manual_offsets=None, fng_box_bounds=None):
        configs = []
        if self.float_nodes_enabled_var.get():
            configs.append(self._get_floating_config(
                manual_offsets=manual_offsets, box_bounds=box_bounds))
        if self.fng_nodes_enabled_var.get():
            configs.append(self._get_fng_config(
                manual_offsets=fng_manual_offsets, box_bounds=fng_box_bounds))
        return configs or None

    _FISHBONE_LINE_COLOR = "#8bdc8b"
    _FISHBONE_FNODE_COLOR = "#e63946"
    _FISHBONE_HANDLE_COLOR = "#4fa3ff"
    _FISHBONE_ORIGIN_COLOR = "#fdcb6e"
    # Was 22.0 -- roughly a node's half-HEIGHT, so dots stayed clear of the
    # thin branch line but not of a real topic node's actual box, which is
    # far wider than tall (default node width ~120px, i.e. ~60px half-width
    # to either side of the line). That's what let dots look clear of the
    # structure in this preview yet land on top of nodes in the real
    # exported .xmind. Raised to comfortably clear a default-sized node's
    # half-width plus some padding.
    _FNODE_STRUCTURE_CLEARANCE = 90.0

    @staticmethod
    def _node_extent(node, base_w=120.0, base_h=44.0):
        img_data = node.get("image_data") or {}
        w = img_data.get("eq_w") or node.get("_img_w")
        h = img_data.get("eq_h") or node.get("_img_h")
        extent_w = max(base_w, float(w)) if w else base_w
        extent_h = max(base_h, float(h)) if h else base_h
        return extent_w, extent_h

    @staticmethod
    def _subtree_span(node, node_spacing=44.0, sibling_gap=18.0):
        _, own_h = MindMapExporterApp._node_extent(node, base_h=node_spacing)
        kids = node.get("children") or []
        if not kids:
            return own_h, 1
        total_h = 0.0
        total_leaves = 0
        for k in kids:
            h, l = MindMapExporterApp._subtree_span(k, node_spacing, sibling_gap)
            total_h += h
            total_leaves += l
        if len(kids) > 1:
            total_h += (len(kids) - 1) * sibling_gap
        return max(total_h, own_h), max(total_leaves, 1)

    def _get_preview_direction(self) -> str:
        return _preview_direction_for_category(self.cat_var.get(), self.sub_var.get()) or "two_sided"

    @classmethod
    def _layout_tree_preview(cls, root_node: Dict[str, Any], direction: str,
                             level_width: float = 165.0, node_spacing: float = 44.0,
                             sibling_gap: float = 18.0):
        def axis_of(d):
            return 'y' if d in ('down', 'up') else 'x'

        def own_dir(node):
            return _direction_for_structure_class(node.get("_structure_class"))

        root_entry = {"x": 0.0, "y": 0.0, "level": 0, "parent": None,
                      "is_leaf": False, "sign": 0, "axis": axis_of(direction), "node": root_node}
        nodes: List[Dict[str, Any]] = [root_entry]
        children = root_node.get("children") or []
        if not children:
            return nodes, root_entry["axis"]

        def footprint(node, axis):
            own_w, own_h = cls._node_extent(node)
            return own_h if axis == 'x' else own_w

        def reach_extent(node, axis):
            own_w, own_h = cls._node_extent(node)
            return own_w if axis == 'x' else own_h

        def child_layout_of(node, fallback_axis, fallback_sign):
            d = own_dir(node)
            if d == "two_sided":
                return 'x', None, True
            if d is not None:
                axis = axis_of(d)
                if axis == 'x' and d in ("left", "right") and fallback_axis == 'x' and fallback_sign in (1, -1):
                    return axis, fallback_sign, False
                return axis, (1 if d in ("right", "down") else -1), False
            return fallback_axis, fallback_sign, False

        def subtree_span(node, axis):
            kids = node.get("children") or []
            own = footprint(node, axis)
            if not kids:
                return own, 1
            child_axis, child_sign, two_sided = child_layout_of(node, axis, 1)
            total_h = 0.0
            total_leaves = 0
            for k in kids:
                h, l = subtree_span(k, child_axis)
                total_h += h
                total_leaves += l
            if len(kids) > 1:
                total_h += (len(kids) - 1) * sibling_gap
            return max(total_h, own), max(total_leaves, 1)

        def place(node, level, sign, secondary, parent_entry, parent_reach, axis):
            reach = parent_reach + max(level_width, reach_extent(node, axis))
            primary = sign * reach
            x, y = (primary, secondary) if axis == 'x' else (secondary, primary)
            kids = node.get("children") or []
            entry = {"x": x, "y": y, "level": level, "parent": parent_entry,
                     "is_leaf": not kids, "sign": sign, "axis": axis, "node": node}
            nodes.append(entry)
            if kids:
                place_children(node, kids, entry, x, y, axis, sign, level, reach)

        def place_group(kids, parent_entry, anchor_x, anchor_y, axis, sign, parent_level, parent_reach):
            if not kids:
                return
            spans = [subtree_span(k, axis) for k in kids]
            total = sum(h for h, _ in spans) + (len(kids) - 1) * sibling_gap
            cursor = (anchor_y if axis == 'x' else anchor_x) - total / 2
            for k, (h, _) in zip(kids, spans):
                place(k, parent_level + 1, sign, cursor + h / 2, parent_entry, parent_reach, axis)
                cursor += h + sibling_gap

        def place_children(node, kids, parent_entry, anchor_x, anchor_y,
                           inherited_axis, inherited_sign, parent_level, parent_reach):
            child_axis, child_sign, two_sided = child_layout_of(node, inherited_axis, inherited_sign)
            if child_axis == inherited_axis:
                base_reach = parent_reach
            else:
                base_reach = abs(anchor_x if child_axis == 'x' else anchor_y)
            if two_sided:
                weighted = [(k, subtree_span(k, 'x')[1]) for k in kids]
                right_kids, left_kids = [], []
                right_w = left_w = 0
                for k, wt in weighted:
                    if right_w <= left_w:
                        right_kids.append(k)
                        right_w += wt
                    else:
                        left_kids.append(k)
                        left_w += wt
                place_group(right_kids, parent_entry, anchor_x, anchor_y, 'x', 1, parent_level, base_reach)
                place_group(left_kids, parent_entry, anchor_x, anchor_y, 'x', -1, parent_level, base_reach)
            else:
                place_group(kids, parent_entry, anchor_x, anchor_y, child_axis, child_sign, parent_level, base_reach)

        place_children(root_node, children, root_entry, 0.0, 0.0,
                       axis_of(direction), 1 if direction in ('right', 'down') else -1, 0, 0.0)

        return nodes, root_entry["axis"]

    @staticmethod
    def _draw_elbow(canvas, p1, p2, growth_axis, color):
        x1, y1 = p1
        x2, y2 = p2
        if growth_axis == 'x':
            mid = (x1 + x2) / 2
            canvas.create_line(x1, y1, mid, y1, mid, y2, x2, y2,
                               fill=color, width=2, smooth=False, joinstyle="miter")
        else:
            mid = (y1 + y2) / 2
            canvas.create_line(x1, y1, x1, mid, x2, mid, x2, y2,
                               fill=color, width=2, smooth=False, joinstyle="miter")

    def _xmind_extract_tree(self, path: str, sheet_index: int) -> Optional[Dict[str, Any]]:
        try:
            with zipfile.ZipFile(path, "r") as zin:
                content = json.loads(zin.read("content.json").decode("utf-8"))
        except Exception:
            return None
        if not content or not (0 <= sheet_index < len(content)):
            return None
        root_topic = content[sheet_index].get("rootTopic") or {}

        def walk(topic):
            node = {"title": topic.get("title") or ""}
            img = topic.get("image") or {}
            # _has_image mirrors inject_images_into_xmind_nodes' own
            # "image" not in n check exactly (presence of the key, not
            # whether width/height happen to be set) -- IFM's Automatic
            # Search (_ifm_dfs_targets) must use the identical definition
            # of "already has an image" that injection uses, or the two
            # could disagree on which nodes need a search and which
            # target node each downloaded image lands on at export time,
            # silently misaligning the whole positional mapping instead
            # of the length-mismatch check catching it.
            node["_has_image"] = "image" in topic
            if img.get("width"):
                node["_img_w"] = img.get("width")
            if img.get("height"):
                node["_img_h"] = img.get("height")
            struct_class = topic.get("structureClass")
            if struct_class:
                node["_structure_class"] = struct_class
            attached = ((topic.get("children") or {}).get("attached")) or []
            if attached:
                node["children"] = [walk(c) for c in attached]
            return node

        return walk(root_topic)

    def _fnode_final_size(self, image_path: Optional[str], box_w: float, box_h: float) -> Tuple[int, int]:
        box_w = max(1, int(round(box_w)))
        box_h = max(1, int(round(box_h)))
        if not image_path:
            return box_w, box_h
        key = (image_path, box_w, box_h)
        cached = self._fnode_size_cache.get(key)
        if cached:
            return cached
        w, h = box_w, box_h
        try:
            with Image.open(image_path) as im:
                nat_w, nat_h = im.size
            if nat_w > 0 and nat_h > 0:
                scale = min(box_w / nat_w, box_h / nat_h, 1.0)
                w = max(1, int(round(nat_w * scale)))
                h = max(1, int(round(nat_h * scale)))
        except Exception:
            pass
        self._fnode_size_cache[key] = (w, h)
        return w, h

    def _get_preview_tree(self, mode: str = "text") -> Optional[Dict[str, Any]]:
        cached_key, cached_tree = getattr(self, "_preview_tree_cache", (None, None))
        if mode in ("xmind", "fng_xmind"):
            # "xmind" reads the F-Node AMX Section's own loaded file;
            # "fng_xmind" reads the FnG AMX Section's own loaded file.
            # These are deliberately independent (see the FnG AMX
            # Section comment near _open_fng_xmind_structure_view) --
            # this used to hardcode self.loaded_xmind_path/
            # _loaded_sheet_index() for BOTH modes, so a file loaded
            # only into the FnG AMX Section could never be previewed.
            if mode == "fng_xmind":
                path, sheet_index = self.fng_loaded_xmind_path, self._fng_loaded_sheet_index()
            else:
                path, sheet_index = self.loaded_xmind_path, self._loaded_sheet_index()
            if not path:
                self._preview_tree_cache = (None, None)
                return None
            key = (mode, path, sheet_index)
            if key == cached_key:
                return cached_tree
            tree = self._xmind_extract_tree(path, sheet_index)
            self._preview_tree_cache = (key, tree)
            return tree
        try:
            raw = self.input_text.get("1.0", tk.END)
            if not raw.strip():
                self._preview_tree_cache = (None, None)
                return None
            key = ("text", hash(raw))
            if key == cached_key:
                return cached_tree
            tagged = self._apply_heading_tags(raw)
            tree = HierarchyParser(tagged).build_tree()
            self._preview_tree_cache = (key, tree)
            return tree
        except Exception:
            return None

    def _schedule_float_preview_redraw(self, canvas: tk.Canvas):
        if getattr(canvas, "_redraw_scheduled", False):
            return
        canvas._redraw_scheduled = True
        def _do():
            canvas._redraw_scheduled = False
            try:
                self._draw_float_preview(canvas)
            except tk.TclError:
                self._float_preview_canvas = None
        canvas.after(16, _do)

